import React, { useState, useEffect, useCallback } from 'react';
import {
  FaChartLine, FaUsers, FaDollarSign, FaEye, FaShareAlt, FaHeart, FaComment,
  FaGlobe, FaMobile, FaDesktop, FaTablet, FaChrome, FaSafari, FaFirefox, FaEdge,
  FaWhatsapp, FaLinkedin, FaTwitter, FaTelegram, FaInstagram, FaFacebook,
  FaMapMarkerAlt, FaClock, FaTrophy, FaRocket, FaNetworkWired, FaBullseye,
  FaTrendingUp, FaTrendingDown, FaChartPie, FaChartBar, FaChartArea,
  FaArrowUp, FaArrowDown, FaExternalLinkAlt, FaDownload, FaFilter, FaSearch,
  FaPlus, FaEdit, FaTrash, FaCopy, FaCheck, FaTimes, FaInfoCircle, FaBell,
  FaCog, FaStar, FaFire, FaLightbulb, FaBrain, FaTarget, FaAnalytics,
  FaDatabase, FaServer, FaCloud, FaWifi, FaSignal, FaBatteryFull, FaCpu,
  FaMemory, FaCalendar, FaPercentage, FaCoins, FaMapPin, FaRoute, FaUserPlus,
  FaUserCheck, FaUserTimes, FaBuilding, FaShieldAlt, FaCheckCircle
} from 'react-icons/fa';
import { API_BASE_URL } from '../utils/constants';
import { subscribeToGlobalAnalyticsUpdates, subscribeToPostAnalyticsUpdates } from '../utils/socket';
import Navbar from '../components/Navbar';

const Analytics = () => {
  const [analyticsData, setAnalyticsData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('overview');
  const [lastUpdate, setLastUpdate] = useState(null);
  const [realTimeStats, setRealTimeStats] = useState({
    activeUsers: 0,
    liveEvents: 0,
    conversions: 0,
    revenue: 0
  });

  const fetchAnalyticsData = useCallback(async () => {
    try {
      setLoading(true);
      const userId = localStorage.getItem('userId') || JSON.parse(localStorage.getItem('user') || '{}')._id;
      const response = await fetch(`${API_BASE_URL}/real-time-analytics/user/${userId}`, {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });
      
      if (response.ok) {
        const data = await response.json();
        setAnalyticsData(data.analytics);
        setLastUpdate(new Date());
      }
    } catch (error) {
      console.error('Error fetching analytics data:', error);
    } finally {
      setLoading(false);
    }
  }, []);

  // Real-time updates
  useEffect(() => {
    const unsubscribeGlobal = subscribeToGlobalAnalyticsUpdates((data) => {
      console.log('Real-time analytics update:', data);
      setRealTimeStats(prev => ({
        activeUsers: prev.activeUsers + (data.type === 'user_activity' ? 1 : 0),
        liveEvents: prev.liveEvents + (data.type === 'event' ? 1 : 0),
        conversions: prev.conversions + (data.type === 'conversion' ? 1 : 0),
        revenue: prev.revenue + (data.type === 'revenue' ? data.amount : 0)
      }));
      setLastUpdate(new Date());
      fetchAnalyticsData();
    });

    const unsubscribePost = subscribeToPostAnalyticsUpdates((data) => {
      console.log('Real-time post analytics update:', data);
      setLastUpdate(new Date());
      fetchAnalyticsData();
    });

    return () => {
      unsubscribeGlobal();
      unsubscribePost();
    };
  }, [fetchAnalyticsData]);

  useEffect(() => {
    fetchAnalyticsData();
  }, [fetchAnalyticsData]);

  const getPlatformIcon = (platform) => {
    const icons = {
      whatsapp: FaWhatsapp,
      linkedin: FaLinkedin,
      twitter: FaTwitter,
      telegram: FaTelegram,
      instagram: FaInstagram,
      facebook: FaFacebook,
      web: FaGlobe,
      email: FaGlobe,
      sms: FaMobile,
      copy: FaCopy
    };
    return icons[platform] || FaGlobe;
  };

  const getDeviceIcon = (device) => {
    const icons = {
      mobile: FaMobile,
      desktop: FaDesktop,
      tablet: FaTablet
    };
    return icons[device] || FaDesktop;
  };

  const getBrowserIcon = (browser) => {
    const icons = {
      chrome: FaChrome,
      safari: FaSafari,
      firefox: FaFirefox,
      edge: FaEdge
    };
    return icons[browser] || FaGlobe;
  };

  const renderOverview = () => (
    <div className="space-y-6">
      {/* Key Metrics */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-gray-300 text-sm font-medium">Total Posts</p>
              <p className="text-3xl font-bold text-white">{analyticsData?.posts?.length || 0}</p>
        </div>
            <FaRocket className="text-blue-400 text-2xl" />
      </div>
        </div>

        <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-gray-300 text-sm font-medium">Total Referrals</p>
              <p className="text-3xl font-bold text-white">{analyticsData?.referrals?.made?.length || 0}</p>
            </div>
            <FaUsers className="text-green-400 text-2xl" />
        </div>
        </div>

        <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-gray-300 text-sm font-medium">Total Earnings</p>
              <p className="text-3xl font-bold text-white">${analyticsData?.user?.totalEarnings || 0}</p>
            </div>
            <FaDollarSign className="text-yellow-400 text-2xl" />
          </div>
            </div>

        <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
                <div className="flex items-center justify-between">
                  <div>
              <p className="text-gray-300 text-sm font-medium">Network Size</p>
              <p className="text-3xl font-bold text-white">{analyticsData?.networkGrowth?.totalNetwork || 0}</p>
            </div>
            <FaNetworkWired className="text-purple-400 text-2xl" />
                  </div>
                </div>
              </div>

      {/* Real-time Stats */}
      <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
        <h3 className="text-xl font-bold text-white mb-6">Real-time Activity</h3>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <div className="text-center">
            <div className="w-12 h-12 bg-gradient-to-r from-blue-500 to-purple-500 rounded-full flex items-center justify-center mx-auto mb-2">
              <FaUsers className="text-white text-xl" />
            </div>
            <p className="text-white font-semibold">{realTimeStats.activeUsers}</p>
            <p className="text-gray-300 text-sm">Active Users</p>
          </div>
          <div className="text-center">
            <div className="w-12 h-12 bg-gradient-to-r from-green-500 to-blue-500 rounded-full flex items-center justify-center mx-auto mb-2">
              <FaClock className="text-white text-xl" />
            </div>
            <p className="text-white font-semibold">{realTimeStats.liveEvents}</p>
            <p className="text-gray-300 text-sm">Live Events</p>
          </div>
          <div className="text-center">
            <div className="w-12 h-12 bg-gradient-to-r from-yellow-500 to-orange-500 rounded-full flex items-center justify-center mx-auto mb-2">
              <FaBullseye className="text-white text-xl" />
            </div>
            <p className="text-white font-semibold">{realTimeStats.conversions}</p>
            <p className="text-gray-300 text-sm">Conversions</p>
          </div>
          <div className="text-center">
            <div className="w-12 h-12 bg-gradient-to-r from-red-500 to-pink-500 rounded-full flex items-center justify-center mx-auto mb-2">
              <FaDollarSign className="text-white text-xl" />
            </div>
            <p className="text-white font-semibold">${realTimeStats.revenue}</p>
            <p className="text-gray-300 text-sm">Revenue</p>
          </div>
        </div>
                  </div>
                </div>
  );

  const renderPostAnalytics = () => (
    <div className="space-y-6">
      {/* Post Performance */}
      <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
        <h3 className="text-xl font-bold text-white mb-6">Post Performance</h3>
        <div className="space-y-4">
          {analyticsData?.posts?.map((post, index) => (
            <div key={index} className="bg-white/5 rounded-lg p-4">
              <div className="flex items-center justify-between mb-3">
                <h4 className="text-lg font-bold text-white">{post.title}</h4>
                <span className={`px-2 py-1 rounded-full text-xs ${
                  post.status === 'active' 
                    ? 'bg-green-500/20 text-green-400' 
                    : 'bg-gray-500/20 text-gray-400'
                }`}>
                  {post.status}
                </span>
              </div>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
                  <div>
                  <p className="text-gray-300">Views</p>
                  <p className="text-white font-semibold">{post.views || 0}</p>
                  </div>
                <div>
                  <p className="text-gray-300">Clicks</p>
                  <p className="text-white font-semibold">{post.clicks || 0}</p>
                </div>
                <div>
                  <p className="text-gray-300">Shares</p>
                  <p className="text-white font-semibold">{post.shares || 0}</p>
              </div>
                  <div>
                  <p className="text-gray-300">Conversions</p>
                  <p className="text-white font-semibold">{post.conversions || 0}</p>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );

  const renderPlatformAnalytics = () => (
    <div className="space-y-6">
      {/* Platform Distribution */}
      <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
        <h3 className="text-xl font-bold text-white mb-6">Platform Distribution</h3>
        <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
          {Object.entries(analyticsData?.postAnalytics?.platformDistribution || {}).map(([platform, count]) => {
            const Icon = getPlatformIcon(platform);
            return (
              <div key={platform} className="text-center">
                <div className="w-12 h-12 bg-gradient-to-r from-blue-500 to-purple-500 rounded-full flex items-center justify-center mx-auto mb-2">
                  <Icon className="text-white text-xl" />
                </div>
                <p className="text-white font-semibold">{count}</p>
                <p className="text-gray-300 text-sm capitalize">{platform}</p>
                  </div>
            );
          })}
                  </div>
                  </div>

      {/* Device Distribution */}
      <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
        <h3 className="text-xl font-bold text-white mb-6">Device Distribution</h3>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {Object.entries(analyticsData?.postAnalytics?.deviceDistribution || {}).map(([device, count]) => {
            const Icon = getDeviceIcon(device);
            return (
              <div key={device} className="text-center">
                <div className="w-16 h-16 bg-gradient-to-r from-green-500 to-blue-500 rounded-full flex items-center justify-center mx-auto mb-3">
                  <Icon className="text-white text-2xl" />
                </div>
                <p className="text-white font-semibold text-xl">{count}</p>
                <p className="text-gray-300 capitalize">{device}</p>
              </div>
            );
          })}
                </div>
              </div>

      {/* Browser Distribution */}
      <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
        <h3 className="text-xl font-bold text-white mb-6">Browser Distribution</h3>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          {Object.entries(analyticsData?.postAnalytics?.browserDistribution || {}).map(([browser, count]) => {
            const Icon = getBrowserIcon(browser);
            return (
              <div key={browser} className="text-center">
                <div className="w-12 h-12 bg-gradient-to-r from-orange-500 to-red-500 rounded-full flex items-center justify-center mx-auto mb-2">
                  <Icon className="text-white text-xl" />
                </div>
                <p className="text-white font-semibold">{count}</p>
                <p className="text-gray-300 text-sm capitalize">{browser}</p>
              </div>
            );
          })}
                </div>
              </div>
            </div>
  );

  const renderGeographicAnalytics = () => (
          <div className="space-y-6">
      {/* Location Distribution */}
      <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
        <h3 className="text-xl font-bold text-white mb-6">Geographic Distribution</h3>
        <div className="space-y-3">
          {Object.entries(analyticsData?.postAnalytics?.locationDistribution || {})
            .sort(([,a], [,b]) => b - a)
            .slice(0, 10)
            .map(([location, count]) => (
              <div key={location} className="flex items-center justify-between">
                <div className="flex items-center space-x-3">
                  <FaMapMarkerAlt className="text-red-400" />
                  <span className="text-white">{location}</span>
                    </div>
                <div className="flex items-center space-x-2">
                  <div className="w-20 bg-gray-700 rounded-full h-2">
                    <div 
                      className="bg-gradient-to-r from-red-500 to-pink-500 h-2 rounded-full"
                      style={{ width: `${(count / Math.max(...Object.values(analyticsData?.postAnalytics?.locationDistribution || {}))) * 100}%` }}
                    ></div>
                  </div>
                  <span className="text-white font-semibold w-8 text-right">{count}</span>
                </div>
              </div>
            ))}
        </div>
      </div>
    </div>
  );

  const renderEngagementAnalytics = () => (
    <div className="space-y-6">
      {/* Engagement Metrics */}
      <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
        <h3 className="text-xl font-bold text-white mb-6">Engagement Metrics</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                      <div className="text-center">
            <div className="w-16 h-16 bg-gradient-to-r from-blue-500 to-purple-500 rounded-full flex items-center justify-center mx-auto mb-3">
              <FaClock className="text-white text-2xl" />
            </div>
            <p className="text-white font-semibold text-xl">
              {analyticsData?.postAnalytics?.engagementMetrics?.averageTimeSpent?.toFixed(1) || 0}s
            </p>
            <p className="text-gray-300">Avg. Time Spent</p>
                      </div>
                      <div className="text-center">
            <div className="w-16 h-16 bg-gradient-to-r from-green-500 to-blue-500 rounded-full flex items-center justify-center mx-auto mb-3">
              <FaEye className="text-white text-2xl" />
            </div>
            <p className="text-white font-semibold text-xl">
              {analyticsData?.postAnalytics?.engagementMetrics?.averageScrollDepth?.toFixed(1) || 0}%
            </p>
            <p className="text-gray-300">Avg. Scroll Depth</p>
                      </div>
                      <div className="text-center">
            <div className="w-16 h-16 bg-gradient-to-r from-yellow-500 to-orange-500 rounded-full flex items-center justify-center mx-auto mb-3">
              <FaHeart className="text-white text-2xl" />
            </div>
            <p className="text-white font-semibold text-xl">
              {analyticsData?.postAnalytics?.engagementMetrics?.engagementRate?.toFixed(1) || 0}%
            </p>
            <p className="text-gray-300">Engagement Rate</p>
                      </div>
                      <div className="text-center">
            <div className="w-16 h-16 bg-gradient-to-r from-red-500 to-pink-500 rounded-full flex items-center justify-center mx-auto mb-3">
              <FaBullseye className="text-white text-2xl" />
            </div>
            <p className="text-white font-semibold text-xl">
              {analyticsData?.postAnalytics?.engagementMetrics?.conversionRate?.toFixed(1) || 0}%
            </p>
            <p className="text-gray-300">Conversion Rate</p>
          </div>
                        </div>
                      </div>
                    </div>
  );

  const renderContent = () => {
    switch (activeTab) {
      case 'overview':
        return renderOverview();
      case 'posts':
        return renderPostAnalytics();
      case 'platforms':
        return renderPlatformAnalytics();
      case 'geographic':
        return renderGeographicAnalytics();
      case 'engagement':
        return renderEngagementAnalytics();
      default:
        return renderOverview();
    }
  };

  // DON'T block rendering! Show page with Navbar even while loading
  const showLoading = loading && !analyticsData;

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-purple-900 to-slate-900">
      {/* ALWAYS SHOW NAVBAR */}
      <Navbar />
      
      {/* Header */}
      <div className="bg-white/10 backdrop-blur-lg border-b border-white/20">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <div className="flex items-center space-x-4">
              <div className="w-10 h-10 bg-gradient-to-r from-purple-500 to-pink-500 rounded-lg flex items-center justify-center">
                <FaChartLine className="text-white text-xl" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-white">Analytics Dashboard</h1>
                <p className="text-gray-300 text-sm">Real-time analytics and insights</p>
              </div>
            </div>
            <div className="flex items-center space-x-4">
              {lastUpdate && (
                <div className="text-sm text-gray-400">
                  Last updated: {lastUpdate.toLocaleTimeString()}
                </div>
              )}
              <div className="flex items-center space-x-2">
                <div className="w-3 h-3 bg-green-400 rounded-full animate-pulse"></div>
                <span className="text-sm text-white">Live</span>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Navigation Tabs */}
      <div className="bg-white/5 backdrop-blur-lg border-b border-white/10">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <nav className="flex space-x-8 overflow-x-auto">
            {[
              { id: 'overview', label: 'Overview', icon: FaChartLine },
              { id: 'posts', label: 'Posts', icon: FaRocket },
              { id: 'platforms', label: 'Platforms', icon: FaGlobe },
              { id: 'geographic', label: 'Geographic', icon: FaMapMarkerAlt },
              { id: 'engagement', label: 'Engagement', icon: FaHeart }
            ].map((tab) => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`flex items-center space-x-2 py-4 px-1 border-b-2 font-medium text-sm transition-colors whitespace-nowrap ${
                  activeTab === tab.id
                    ? 'border-purple-500 text-purple-400'
                    : 'border-transparent text-gray-300 hover:text-white hover:border-gray-300'
                }`}
              >
                <tab.icon className="w-4 h-4" />
                <span>{tab.label}</span>
              </button>
            ))}
          </nav>
        </div>
      </div>

      {/* Main Content */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {showLoading ? (
          <div className="flex items-center justify-center h-96">
            <div className="text-center">
              <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-white mx-auto mb-4"></div>
              <h2 className="text-2xl font-bold text-white mb-2">Loading Analytics</h2>
              <p className="text-gray-300">Fetching REAL data from database...</p>
            </div>
          </div>
        ) : (
          renderContent()
        )}
      </div>
    </div>
  );
};

export default Analytics;