import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { API_URL } from '../utils/constants';

const FollowButton = ({ userId, initialIsFollowing = false, onFollowChange, size = 'md', variant = 'primary' }) => {
  const [isFollowing, setIsFollowing] = useState(initialIsFollowing);
  const [isLoading, setIsLoading] = useState(false);
  const [showUnfollowConfirm, setShowUnfollowConfirm] = useState(false);

  const sizeClasses = {
    sm: 'text-xs px-3 py-1',
    md: 'text-sm px-4 py-2',
    lg: 'text-base px-6 py-2.5'
  };

  const variantClasses = {
    primary: isFollowing
      ? 'bg-gray-200 text-gray-700 hover:bg-gray-300'
      : 'bg-blue-600 text-white hover:bg-blue-700',
    secondary: isFollowing
      ? 'border border-gray-300 bg-white text-gray-700 hover:bg-gray-50'
      : 'border border-blue-600 bg-white text-blue-600 hover:bg-blue-50',
    minimal: isFollowing
      ? 'text-gray-600 hover:text-gray-800'
      : 'text-blue-600 hover:text-blue-700'
  };

  useEffect(() => {
    setIsFollowing(initialIsFollowing);
  }, [initialIsFollowing]);

  useEffect(() => {
    checkFollowStatus();
  }, [userId]);

  const checkFollowStatus = async () => {
    try {
      const token = localStorage.getItem('token');
      if (!token) return;

      const response = await axios.get(`${API_URL}/follows/${userId}/check`, {
        headers: { Authorization: `Bearer ${token}` }
      });

      if (response.data.success) {
        setIsFollowing(response.data.isFollowing);
      }
    } catch (error) {
      console.error('Error checking follow status:', error);
    }
  };

  const handleFollow = async () => {
    if (isLoading) return;

    // If already following, show confirmation
    if (isFollowing && !showUnfollowConfirm) {
      setShowUnfollowConfirm(true);
      setTimeout(() => setShowUnfollowConfirm(false), 3000);
      return;
    }

    setIsLoading(true);

    try {
      const token = localStorage.getItem('token');
      if (!token) {
        alert('Please login to follow users');
        setIsLoading(false);
        return;
      }

      const response = await axios.post(
        `${API_URL}/follows/toggle`,
        { userId },
        { headers: { Authorization: `Bearer ${token}` } }
      );

      if (response.data.success) {
        const newFollowingState = response.data.action === 'followed';
        setIsFollowing(newFollowingState);
        setShowUnfollowConfirm(false);

        // Callback for parent component
        if (onFollowChange) {
          onFollowChange(newFollowingState);
        }
      }
    } catch (error) {
      console.error('Error toggling follow:', error);
      if (error.response?.data?.message) {
        alert(error.response.data.message);
      } else {
        alert('Failed to update follow status. Please try again.');
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="relative inline-block">
      <button
        onClick={handleFollow}
        disabled={isLoading}
        className={`
          ${sizeClasses[size]}
          ${variantClasses[variant]}
          font-medium rounded-full transition-all
          disabled:opacity-50 disabled:cursor-not-allowed
          flex items-center gap-2
        `}
      >
        {isLoading ? (
          <>
            <svg className="animate-spin h-4 w-4" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
              <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
              <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
            </svg>
            <span>{isFollowing ? 'Unfollowing...' : 'Following...'}</span>
          </>
        ) : (
          <>
            {isFollowing ? (
              <>
                <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"/>
                </svg>
                <span>{showUnfollowConfirm ? 'Unfollow?' : 'Following'}</span>
              </>
            ) : (
              <>
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                </svg>
                <span>Follow</span>
              </>
            )}
          </>
        )}
      </button>

      {/* Unfollow Confirmation Tooltip */}
      {showUnfollowConfirm && (
        <div className="absolute top-full left-1/2 transform -translate-x-1/2 mt-2 bg-gray-800 text-white text-xs rounded-lg py-2 px-3 whitespace-nowrap z-10 animate-fade-in">
          Click again to unfollow
          <div className="absolute bottom-full left-1/2 transform -translate-x-1/2 border-4 border-transparent border-b-gray-800"></div>
        </div>
      )}
    </div>
  );
};

export default FollowButton;

