import React, { useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Home from './pages/Home';
import Login from './pages/Login';
import ModernLogin from './pages/ModernLogin';
import Register from './pages/Register';
import Profile from './pages/Profile';
import Dashboard from './pages/Dashboard';
import Analytics from './pages/Analytics';
import Journey from './pages/Journey';
import PostCreate from './pages/PostCreate';
import PostView from './pages/PostView';
import ComprehensivePostDetail from './pages/ComprehensivePostDetail';
import Marketplace from './pages/Marketplace';
import AdminDashboard from './pages/AdminDashboard';
import Notifications from './pages/Notifications';
import Settings from './pages/Settings';
import Gamification from './pages/Gamification';
import pushNotificationManager from './utils/pushNotifications';

function App() {
  useEffect(() => {
    // Initialize push notifications on app start
    const token = localStorage.getItem('token');
    if (token) {
      try {
        const decoded = JSON.parse(atob(token.split('.')[1]));
        pushNotificationManager.initialize(decoded.id);
      } catch (error) {
        console.error('Error initializing push notifications:', error);
      }
    }
  }, []);

  return (
    <Router>
      <div className="min-h-screen bg-gray-100">
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/login" element={<ModernLogin />} />
          <Route path="/register" element={<Register />} />
          <Route path="/dashboard" element={<Dashboard />} />
          <Route path="/profile" element={<Profile />} />
          <Route path="/profile/:userId" element={<Profile />} />
          <Route path="/analytics" element={<Analytics />} />
          <Route path="/journey" element={<Journey />} />
          <Route path="/marketplace" element={<Marketplace />} />
          <Route path="/notifications" element={<Notifications />} />
          <Route path="/settings" element={<Settings />} />
          <Route path="/gamification" element={<Gamification />} />
          <Route path="/create-post" element={<PostCreate />} />
          <Route path="/edit-post/:id" element={<PostCreate />} />
          <Route path="/post/:postId" element={<PostView />} />
          <Route path="/posts/:postId" element={<ComprehensivePostDetail />} />
          <Route path="/referrals/:postId" element={<ComprehensivePostDetail />} />
          <Route path="/admin" element={<AdminDashboard />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;