import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { FaBell, FaCheck, FaTrash, FaFilter, FaEye, FaEyeSlash, FaCog, FaExclamationTriangle, FaInfoCircle, FaCheckCircle, FaTimesCircle } from 'react-icons/fa';
import Navbar from '../components/Navbar';
import { REACT_APP_API_URL } from '../utils/constants';
import socket from '../utils/socket';

const Notifications = () => {
  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState({ total: 0, unread: 0, byType: {} });
  const [filter, setFilter] = useState('all'); // all, unread, read
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [user, setUser] = useState(null);

  const fetchNotifications = async (page = 1, filterType = 'all') => {
    try {
      setLoading(true);
      const token = localStorage.getItem('token');
      if (token) {
        axios.defaults.headers.common['Authorization'] = `Bearer ${token}`;
        const userRes = await axios.get(`${REACT_APP_API_URL}/auth/profile`);
        setUser(userRes.data);
      }

      const params = { page, limit: 20 };
      if (filterType === 'unread') params.unreadOnly = true;

      const response = await axios.get(`${REACT_APP_API_URL}/notifications`, { params });
      setNotifications(response.data.notifications || []);
      setTotalPages(response.data.pagination.totalPages);
      setCurrentPage(page);
    } catch (err) {
      console.error('Error fetching notifications:', err);
    } finally {
      setLoading(false);
    }
  };

  const fetchStats = async () => {
    try {
      const response = await axios.get(`${REACT_APP_API_URL}/notifications/stats`);
      setStats(response.data);
    } catch (err) {
      console.error('Error fetching notification stats:', err);
    }
  };

  useEffect(() => {
    fetchNotifications();
    fetchStats();
  }, []);

  useEffect(() => {
    fetchNotifications(1, filter);
  }, [filter]);

  // Real-time notification updates
  useEffect(() => {
    const handleNewNotification = (data) => {
      console.log('New notification received:', data);
      fetchNotifications(currentPage, filter);
      fetchStats();
    };

    socket.on('notification', handleNewNotification);

    return () => {
      socket.off('notification', handleNewNotification);
    };
  }, [currentPage, filter]);

  const markAsRead = async (notificationId) => {
    try {
      await axios.put(`${REACT_APP_API_URL}/notifications/${notificationId}/read`);
      fetchNotifications(currentPage, filter);
      fetchStats();
    } catch (err) {
      console.error('Error marking notification as read:', err);
    }
  };

  const markAllAsRead = async () => {
    try {
      await axios.put(`${REACT_APP_API_URL}/notifications/read-all`);
      fetchNotifications(currentPage, filter);
      fetchStats();
    } catch (err) {
      console.error('Error marking all notifications as read:', err);
    }
  };

  const deleteNotification = async (notificationId) => {
    try {
      await axios.delete(`${REACT_APP_API_URL}/notifications/${notificationId}`);
      fetchNotifications(currentPage, filter);
      fetchStats();
    } catch (err) {
      console.error('Error deleting notification:', err);
    }
  };

  const getNotificationIcon = (type) => {
    switch (type) {
      case 'referral_click':
        return <FaEye className="w-5 h-5 text-blue-500" />;
      case 'referral_conversion':
        return <FaCheckCircle className="w-5 h-5 text-green-500" />;
      case 'commission_earned':
        return <FaCheckCircle className="w-5 h-5 text-yellow-500" />;
      case 'post_shared':
        return <FaBell className="w-5 h-5 text-purple-500" />;
      case 'comment_received':
        return <FaInfoCircle className="w-5 h-5 text-indigo-500" />;
      case 'like_received':
        return <FaCheckCircle className="w-5 h-5 text-red-500" />;
      case 'new_follower':
        return <FaCheckCircle className="w-5 h-5 text-green-500" />;
      case 'system_announcement':
        return <FaExclamationTriangle className="w-5 h-5 text-orange-500" />;
      case 'admin_message':
        return <FaCog className="w-5 h-5 text-gray-500" />;
      case 'engagement_reminder':
        return <FaBell className="w-5 h-5 text-blue-500" />;
      default:
        return <FaBell className="w-5 h-5 text-gray-500" />;
    }
  };

  const getNotificationColor = (type) => {
    switch (type) {
      case 'referral_click':
        return 'border-blue-200 bg-blue-50';
      case 'referral_conversion':
        return 'border-green-200 bg-green-50';
      case 'commission_earned':
        return 'border-yellow-200 bg-yellow-50';
      case 'post_shared':
        return 'border-purple-200 bg-purple-50';
      case 'comment_received':
        return 'border-indigo-200 bg-indigo-50';
      case 'like_received':
        return 'border-red-200 bg-red-50';
      case 'new_follower':
        return 'border-green-200 bg-green-50';
      case 'system_announcement':
        return 'border-orange-200 bg-orange-50';
      case 'admin_message':
        return 'border-gray-200 bg-gray-50';
      case 'engagement_reminder':
        return 'border-blue-200 bg-blue-50';
      default:
        return 'border-gray-200 bg-gray-50';
    }
  };

  const formatTimeAgo = (timestamp) => {
    const now = new Date();
    const diff = now - new Date(timestamp);
    const minutes = Math.floor(diff / (1000 * 60));
    const hours = Math.floor(minutes / 60);
    const days = Math.floor(hours / 24);

    if (minutes < 1) return 'Just now';
    if (minutes < 60) return `${minutes}m ago`;
    if (hours < 24) return `${hours}h ago`;
    return `${days}d ago`;
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 via-white to-purple-50">
        <Navbar />
        <div className="flex justify-center items-center h-64">
          <div className="text-lg">Loading notifications...</div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 via-white to-purple-50">
      <Navbar />

      <header className="bg-white/95 backdrop-blur-md shadow-lg">
        <div className="max-w-7xl mx-auto py-8 px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-4xl font-bold bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent">
                Notifications
              </h1>
              <p className="text-gray-600 mt-2">Stay updated with your referral activity</p>
            </div>
            <div className="flex items-center space-x-4">
              {stats.unread > 0 && (
                <button
                  onClick={markAllAsRead}
                  className="bg-green-500 hover:bg-green-600 text-white px-4 py-2 rounded-lg text-sm font-medium transition-colors"
                >
                  Mark All Read ({stats.unread})
                </button>
              )}
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto py-8 sm:px-6 lg:px-8">
        {/* Stats Cards */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-6 mb-8">
          <div className="bg-white rounded-2xl p-6 shadow-lg">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600">Total</p>
                <p className="text-3xl font-bold text-gray-900">{stats.total}</p>
              </div>
              <FaBell className="w-8 h-8 text-blue-500" />
            </div>
          </div>
          <div className="bg-white rounded-2xl p-6 shadow-lg">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600">Unread</p>
                <p className="text-3xl font-bold text-orange-600">{stats.unread}</p>
              </div>
              <FaEyeSlash className="w-8 h-8 text-orange-500" />
            </div>
          </div>
          <div className="bg-white rounded-2xl p-6 shadow-lg">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600">Commissions</p>
                <p className="text-3xl font-bold text-green-600">{stats.byType.commission_earned?.total || 0}</p>
              </div>
              <FaCheckCircle className="w-8 h-8 text-green-500" />
            </div>
          </div>
          <div className="bg-white rounded-2xl p-6 shadow-lg">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600">Referrals</p>
                <p className="text-3xl font-bold text-purple-600">{(stats.byType.referral_click?.total || 0) + (stats.byType.referral_conversion?.total || 0)}</p>
              </div>
              <FaEye className="w-8 h-8 text-purple-500" />
            </div>
          </div>
        </div>

        {/* Filters */}
        <div className="bg-white rounded-2xl shadow-lg p-6 mb-8">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-4">
              <button
                onClick={() => setFilter('all')}
                className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                  filter === 'all' ? 'bg-blue-500 text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                }`}
              >
                All ({stats.total})
              </button>
              <button
                onClick={() => setFilter('unread')}
                className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                  filter === 'unread' ? 'bg-orange-500 text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                }`}
              >
                Unread ({stats.unread})
              </button>
            </div>
          </div>
        </div>

        {/* Notifications List */}
        {notifications.length === 0 ? (
          <div className="bg-white rounded-2xl shadow-lg p-12 text-center">
            <FaBell className="w-16 h-16 text-gray-300 mx-auto mb-4" />
            <h3 className="text-lg font-medium text-gray-900 mb-2">No notifications</h3>
            <p className="text-gray-600">You're all caught up! Notifications will appear here.</p>
          </div>
        ) : (
          <div className="space-y-4">
            {notifications.map((notification) => (
              <div
                key={notification._id}
                className={`bg-white rounded-2xl shadow-lg p-6 border-l-4 transition-all duration-200 hover:shadow-xl ${
                  notification.isRead ? 'opacity-75' : 'border-blue-500'
                } ${getNotificationColor(notification.type)}`}
              >
                <div className="flex items-start justify-between">
                  <div className="flex items-start space-x-4">
                    <div className={`p-3 rounded-full ${notification.isRead ? 'bg-gray-100' : 'bg-white shadow-sm'}`}>
                      {getNotificationIcon(notification.type)}
                    </div>
                    <div className="flex-1">
                      <div className="flex items-center space-x-2 mb-2">
                        <h3 className={`font-semibold ${notification.isRead ? 'text-gray-600' : 'text-gray-900'}`}>
                          {notification.title}
                        </h3>
                        {!notification.isRead && (
                          <div className="w-2 h-2 bg-blue-500 rounded-full"></div>
                        )}
                      </div>
                      <p className={`text-sm mb-3 ${notification.isRead ? 'text-gray-500' : 'text-gray-700'}`}>
                        {notification.message}
                      </p>
                      <div className="flex items-center space-x-4 text-xs text-gray-500">
                        <span>{formatTimeAgo(notification.createdAt)}</span>
                        <span className="px-2 py-1 bg-gray-100 rounded-full">{notification.type.replace('_', ' ')}</span>
                        {notification.priority === 'high' && (
                          <span className="px-2 py-1 bg-red-100 text-red-600 rounded-full">High Priority</span>
                        )}
                      </div>
                    </div>
                  </div>
                  <div className="flex items-center space-x-2">
                    {!notification.isRead && (
                      <button
                        onClick={() => markAsRead(notification._id)}
                        className="p-2 text-green-600 hover:bg-green-50 rounded-lg transition-colors"
                        title="Mark as read"
                      >
                        <FaCheck className="w-4 h-4" />
                      </button>
                    )}
                    <button
                      onClick={() => deleteNotification(notification._id)}
                      className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                      title="Delete notification"
                    >
                      <FaTrash className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="flex justify-center mt-8 space-x-2">
            <button
              onClick={() => fetchNotifications(currentPage - 1, filter)}
              disabled={currentPage === 1}
              className="px-4 py-2 bg-white rounded-lg shadow-sm disabled:opacity-50 disabled:cursor-not-allowed"
            >
              Previous
            </button>
            <span className="px-4 py-2 bg-blue-500 text-white rounded-lg">
              Page {currentPage} of {totalPages}
            </span>
            <button
              onClick={() => fetchNotifications(currentPage + 1, filter)}
              disabled={currentPage === totalPages}
              className="px-4 py-2 bg-white rounded-lg shadow-sm disabled:opacity-50 disabled:cursor-not-allowed"
            >
              Next
            </button>
          </div>
        )}
      </main>
    </div>
  );
};

export default Notifications;