import axios from 'axios';
import { API_URL } from './constants';

/**
 * Referral API Utility Functions
 * Handles all API calls related to referrals, analytics, and commissions
 */

// Get authentication headers
const getAuthHeaders = () => {
  const token = localStorage.getItem('token');
  return token ? { Authorization: `Bearer ${token}` } : {};
};

/**
 * Fetch referral chains for a post
 */
export const fetchReferralChains = async (postId) => {
  try {
    const response = await axios.get(`${API_URL}/referral-tracking/tree/${postId}`);
    return response.data;
  } catch (error) {
    console.error('Error fetching referral chains:', error);
    throw error;
  }
};

/**
 * Fetch hub-and-spoke data for map visualization
 */
export const fetchHubAndSpokeData = async (postId) => {
  try {
    const response = await axios.get(`${API_URL}/referral-tracking/hub-and-spoke/${postId}`);
    return response.data;
  } catch (error) {
    console.error('Error fetching hub-and-spoke data:', error);
    throw error;
  }
};

/**
 * Fetch post analytics
 */
export const fetchPostAnalytics = async (postId, params = {}) => {
  try {
    const response = await axios.get(`${API_URL}/referral-tracking/analytics/${postId}`, {
      params
    });
    return response.data;
  } catch (error) {
    console.error('Error fetching analytics:', error);
    throw error;
  }
};

/**
 * Fetch commission data for a post
 */
export const fetchCommissions = async (postId) => {
  try {
    const response = await axios.get(`${API_URL}/referral-tracking/commission-preview/${postId}`, {
      headers: getAuthHeaders()
    });
    return response.data;
  } catch (error) {
    console.error('Error fetching commissions:', error);
    throw error;
  }
};

/**
 * Fetch top referrers
 */
export const fetchTopReferrers = async (postId, limit = 10) => {
  try {
    const response = await axios.get(`${API_URL}/referral-tracking/top-referrers/${postId}`, {
      params: { limit }
    });
    return response.data;
  } catch (error) {
    console.error('Error fetching top referrers:', error);
    throw error;
  }
};

/**
 * Track a referral click
 */
export const trackReferralClick = async (data) => {
  try {
    const response = await axios.post(`${API_URL}/referral-tracking/track`, data);
    return response.data;
  } catch (error) {
    console.error('Error tracking referral:', error);
    throw error;
  }
};

/**
 * Export referral data
 */
export const exportReferralData = async (postId, format = 'json') => {
  try {
    const response = await axios.get(`${API_URL}/referral-tracking/export/${postId}`, {
      params: { format },
      headers: getAuthHeaders(),
      responseType: format === 'csv' ? 'blob' : 'json'
    });

    if (format === 'csv') {
      // Create download link for CSV
      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `referral-data-${postId}.csv`);
      document.body.appendChild(link);
      link.click();
      link.remove();
      return { success: true };
    } else {
      // Return JSON data
      return response.data;
    }
  } catch (error) {
    console.error('Error exporting data:', error);
    throw error;
  }
};

/**
 * Fetch post details
 */
export const fetchPostDetails = async (postId) => {
  try {
    const response = await axios.get(`${API_URL}/posts/${postId}`);
    return response.data;
  } catch (error) {
    console.error('Error fetching post details:', error);
    throw error;
  }
};

/**
 * Batch fetch all data for a post
 */
export const fetchAllPostData = async (postId, options = {}) => {
  try {
    const {
      includeChains = true,
      includeAnalytics = true,
      includeCommissions = true,
      includeHubSpoke = true,
      analyticsParams = {}
    } = options;

    const promises = [];
    const keys = [];

    if (includeChains) {
      promises.push(fetchReferralChains(postId));
      keys.push('chains');
    }

    if (includeAnalytics) {
      promises.push(fetchPostAnalytics(postId, analyticsParams));
      keys.push('analytics');
    }

    if (includeCommissions) {
      promises.push(fetchCommissions(postId).catch(() => null));
      keys.push('commissions');
    }

    if (includeHubSpoke) {
      promises.push(fetchHubAndSpokeData(postId));
      keys.push('hubSpoke');
    }

    const results = await Promise.all(promises);

    const data = {};
    keys.forEach((key, index) => {
      data[key] = results[index];
    });

    return data;
  } catch (error) {
    console.error('Error fetching all post data:', error);
    throw error;
  }
};

