import io from 'socket.io-client';

const API_URL = process.env.REACT_APP_API_URL || 'https://referral-hub-backend-production.up.railway.app';
let SOCKET_URL = process.env.REACT_APP_SOCKET_URL || API_URL;

try {
  // If the page is https and socket url is http, use wss
  const pageIsHttps = typeof window !== 'undefined' && window.location && window.location.protocol === 'https:';
  if (pageIsHttps && SOCKET_URL.startsWith('http://')) {
    SOCKET_URL = SOCKET_URL.replace('http://', 'wss://');
  }
  if (!pageIsHttps && SOCKET_URL.startsWith('https://')) {
    SOCKET_URL = SOCKET_URL.replace('https://', 'ws://');
  }
} catch (_) {}

const socket = io(SOCKET_URL, {
  transports: ['websocket', 'polling'],
  withCredentials: false
});

// Event listeners registry for components to subscribe to real-time updates
const eventListeners = {
  referral_update: [],
  commission_update: [],
  credits_update: [],
  post_analytics_update: [],
  global_analytics_update: [],
  user_analytics_update: [],
  notification: []
};

// Socket event handlers
socket.on('connect', () => {
  console.log('Connected to server:', socket.id);
});

socket.on('disconnect', () => {
  console.log('Disconnected from server');
});

// Real-time event handlers
socket.on('referral_update', (data) => {
  console.log('Real-time referral update:', data);
  eventListeners.referral_update.forEach(callback => callback(data));
});

socket.on('commission_update', (data) => {
  console.log('Real-time commission update:', data);
  eventListeners.commission_update.forEach(callback => callback(data));
});

socket.on('credits_update', (data) => {
  console.log('Real-time credits update:', data);
  eventListeners.credits_update.forEach(callback => callback(data));
});

socket.on('post_analytics_update', (data) => {
  console.log('Real-time post analytics update:', data);
  eventListeners.post_analytics_update.forEach(callback => callback(data));
});

socket.on('global_analytics_update', (data) => {
  console.log('Real-time global analytics update:', data);
  eventListeners.global_analytics_update.forEach(callback => callback(data));
});

socket.on('user_analytics_update', (data) => {
  console.log('Real-time user analytics update:', data);
  eventListeners.user_analytics_update.forEach(callback => callback(data));
});

socket.on('notification', (data) => {
  console.log('Real-time notification:', data);
  eventListeners.notification.forEach(callback => callback(data));
});

// Helper functions for room management
export const joinUserRoom = (userId) => {
  if (userId && socket.connected) {
    socket.emit('join_user_room', userId);
  }
};

export const joinPostRoom = (postId) => {
  if (postId && socket.connected) {
    socket.emit('join_post_room', postId);
  }
};

export const joinAnalyticsRoom = () => {
  if (socket.connected) {
    socket.emit('join_analytics_room');
  }
};

export const joinNotificationsRoom = (userId) => {
  if (userId && socket.connected) {
    socket.emit('join_notifications_room', userId);
  }
};

// Real-time subscription functions
export const subscribeToReferralUpdates = (callback) => {
  eventListeners.referral_update.push(callback);
  return () => {
    const index = eventListeners.referral_update.indexOf(callback);
    if (index > -1) eventListeners.referral_update.splice(index, 1);
  };
};

