import React, { useState, useEffect } from 'react';
import { API_BASE_URL } from '../utils/constants';

const NotificationCenter = ({ notifications }) => {
  const [filteredNotifications, setFilteredNotifications] = useState([]);
  const [filters, setFilters] = useState({
    type: 'all',
    priority: 'all',
    read: 'all'
  });

  useEffect(() => {
    if (notifications) {
      applyFilters();
    }
  }, [notifications, filters]);

  const applyFilters = () => {
    let filtered = [...notifications];

    if (filters.type !== 'all') {
      filtered = filtered.filter(notification => notification.type === filters.type);
    }

    if (filters.priority !== 'all') {
      filtered = filtered.filter(notification => notification.priority === filters.priority);
    }

    if (filters.read !== 'all') {
      filtered = filtered.filter(notification => 
        filters.read === 'read' ? notification.isRead : !notification.isRead
      );
    }

    setFilteredNotifications(filtered);
  };

  const getNotificationIcon = (type) => {
    const icons = {
      'referral_click': '👆',
      'referral_conversion': '💰',
      'commission_earned': '💎',
      'post_shared': '📤',
      'new_follower': '👥',
      'comment_received': '💬',
      'like_received': '❤️',
      'system_announcement': '📢',
      'admin_message': '👨‍💼',
      'milestone_achieved': '🏆',
      'level_up': '⬆️',
      'badge_earned': '🎖️'
    };
    return icons[type] || '📋';
  };

  const getPriorityColor = (priority) => {
    const colors = {
      'low': 'bg-gray-100 text-gray-800',
      'medium': 'bg-blue-100 text-blue-800',
      'high': 'bg-orange-100 text-orange-800',
      'urgent': 'bg-red-100 text-red-800'
    };
    return colors[priority] || 'bg-gray-100 text-gray-800';
  };

  const getTypeColor = (type) => {
    const colors = {
      'referral_click': 'bg-blue-100 text-blue-800',
      'referral_conversion': 'bg-green-100 text-green-800',
      'commission_earned': 'bg-yellow-100 text-yellow-800',
      'post_shared': 'bg-purple-100 text-purple-800',
      'new_follower': 'bg-pink-100 text-pink-800',
      'comment_received': 'bg-indigo-100 text-indigo-800',
      'like_received': 'bg-red-100 text-red-800',
      'system_announcement': 'bg-gray-100 text-gray-800',
      'admin_message': 'bg-yellow-100 text-yellow-800',
      'milestone_achieved': 'bg-green-100 text-green-800',
      'level_up': 'bg-blue-100 text-blue-800',
      'badge_earned': 'bg-purple-100 text-purple-800'
    };
    return colors[type] || 'bg-gray-100 text-gray-800';
  };

  const markAsRead = async (notificationId) => {
    try {
      await fetch(`${API_BASE_URL}/notifications/${notificationId}/read`, {
        method: 'PUT'
      });
      // Update local state
      setFilteredNotifications(prev => 
        prev.map(notif => 
          notif._id === notificationId ? {...notif, isRead: true} : notif
        )
      );
    } catch (error) {
      console.error('Error marking notification as read:', error);
    }
  };

  const renderNotificationItem = (notification) => (
    <div key={notification._id} className={`p-4 rounded-lg shadow hover:shadow-md transition-shadow ${
      notification.isRead ? 'bg-gray-50' : 'bg-white border-l-4 border-blue-500'
    }`}>
      <div className="flex items-start space-x-3">
        <div className="text-2xl">{getNotificationIcon(notification.type)}</div>
        <div className="flex-1">
          <div className="flex items-center justify-between">
            <h4 className="font-semibold text-gray-900">{notification.title}</h4>
            <div className="flex items-center space-x-2">
              <span className={`px-2 py-1 rounded-full text-xs ${getPriorityColor(notification.priority)}`}>
                {notification.priority}
              </span>
              <span className={`px-2 py-1 rounded-full text-xs ${getTypeColor(notification.type)}`}>
                {notification.type.replace('_', ' ')}
              </span>
            </div>
          </div>
          <p className="text-sm text-gray-600 mt-1">{notification.message}</p>
          <div className="flex items-center justify-between mt-2">
            <span className="text-xs text-gray-500">
              {new Date(notification.createdAt).toLocaleString()}
            </span>
            {!notification.isRead && (
              <button
                onClick={() => markAsRead(notification._id)}
                className="text-blue-600 hover:text-blue-800 text-xs font-medium"
              >
                Mark as Read
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div className="space-y-6">
      <div className="bg-white p-6 rounded-lg shadow">
        <h2 className="text-2xl font-bold text-gray-900 mb-4">Notification Center</h2>
        <p className="text-gray-600">Stay updated with all your activities and system notifications</p>
      </div>

      {/* Filters */}
      <div className="bg-white p-6 rounded-lg shadow">
        <h3 className="text-lg font-semibold mb-4">Filters</h3>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Notification Type</label>
            <select
              value={filters.type}
              onChange={(e) => setFilters({...filters, type: e.target.value})}
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              <option value="all">All Types</option>
              <option value="referral_click">Referral Click</option>
              <option value="referral_conversion">Referral Conversion</option>
              <option value="commission_earned">Commission Earned</option>
              <option value="post_shared">Post Shared</option>
              <option value="new_follower">New Follower</option>
              <option value="comment_received">Comment Received</option>
              <option value="like_received">Like Received</option>
              <option value="system_announcement">System Announcement</option>
              <option value="admin_message">Admin Message</option>
              <option value="milestone_achieved">Milestone Achieved</option>
              <option value="level_up">Level Up</option>
              <option value="badge_earned">Badge Earned</option>
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Priority</label>
            <select
              value={filters.priority}
              onChange={(e) => setFilters({...filters, priority: e.target.value})}
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              <option value="all">All Priorities</option>
              <option value="low">Low</option>
              <option value="medium">Medium</option>
              <option value="high">High</option>
              <option value="urgent">Urgent</option>
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Read Status</label>
            <select
              value={filters.read}
              onChange={(e) => setFilters({...filters, read: e.target.value})}
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              <option value="all">All</option>
              <option value="unread">Unread</option>
              <option value="read">Read</option>
            </select>
          </div>
        </div>
      </div>

      {/* Notifications List */}
      <div className="space-y-4">
        {filteredNotifications.map(notification => renderNotificationItem(notification))}
      </div>

      {filteredNotifications.length === 0 && (
        <div className="text-center py-8">
          <div className="text-gray-500">No notifications found</div>
        </div>
      )}
    </div>
  );
};

export default NotificationCenter;