import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import RealTimeJourneyVisualization from '../components/RealTimeJourneyVisualization';
import Navbar from '../components/Navbar';
import { REACT_APP_API_URL } from '../utils/constants';
import socket, { subscribeToPostAnalyticsUpdates, subscribeToReferralUpdates, joinPostRoom } from '../utils/socket';
import comprehensiveReferralService from '../services/comprehensiveReferralService';

const Journey = () => {
  const navigate = useNavigate();
  const [selectedPost, setSelectedPost] = useState(null);
  const [posts, setPosts] = useState([]);
  const [user, setUser] = useState(null);
  const [postAnalytics, setPostAnalytics] = useState(null);
  const [analyticsLoading, setAnalyticsLoading] = useState(false);
  const [referralChains, setReferralChains] = useState([]);
  const [chainsLoading, setChainsLoading] = useState(false);

  useEffect(() => {
    const fetchUserAndPosts = async () => {
      try {
        const token = localStorage.getItem('token');
        if (token) {
          axios.defaults.headers.common['Authorization'] = `Bearer ${token}`;

          // First get user info to check if admin
          const userRes = await axios.get(`${REACT_APP_API_URL}/auth/profile`);
          setUser(userRes.data);

          // Fetch posts based on user role
          const endpoint = userRes.data.role === 'admin' ? '/posts/debug' : '/posts/my';
          const postsRes = await axios.get(`${REACT_APP_API_URL}${endpoint}`);

          if (userRes.data.role === 'admin' && postsRes.data.allPosts) {
            // Admin gets all posts
            setPosts(postsRes.data.allPosts.map(p => ({
              _id: p.id,
              title: p.title,
              description: p.description,
              category: p.category,
              price: p.price,
              originalPrice: p.originalPrice,
              photos: p.photos || [],
              status: p.status,
              referralLink: `https://referral-hub-frontend.vercel.app/post/${p.id}`,
              creator: { email: p.creator },
              createdAt: p.createdAt
            })));
          } else {
            // Regular users get their posts
            setPosts(postsRes.data);
          }
        }
       } catch (error) {
         console.error('Error fetching data:', error);
       }
    };

    fetchUserAndPosts();
  }, []);

  // Listen for real-time updates
  useEffect(() => {
    // Subscribe to post creation events
    const handlePostCreated = (data) => {
      console.log('New post created:', data);
      // Refetch posts
      const token = localStorage.getItem('token');
      if (token && user) {
        axios.defaults.headers.common['Authorization'] = `Bearer ${token}`;
        const endpoint = user.role === 'admin' ? '/posts/debug' : '/posts/my';
        axios.get(`${REACT_APP_API_URL}${endpoint}`)
          .then(postsRes => {
            if (user.role === 'admin' && postsRes.data.allPosts) {
              setPosts(postsRes.data.allPosts.map(p => ({
                _id: p.id,
                title: p.title,
                description: p.description,
                category: p.category,
                price: p.price,
                originalPrice: p.originalPrice,
                photos: p.photos || [],
                status: p.status,
                referralLink: `https://referral-hub-frontend.vercel.app/post/${p.id}`,
                creator: { email: p.creator },
                createdAt: p.createdAt
              })));
            } else {
              setPosts(postsRes.data);
            }
          })
          .catch(err => console.error('Error refreshing posts:', err));
      }
    };

    socket.on('postCreated', handlePostCreated);

    // Subscribe to post analytics updates for selected post
    const unsubscribePostAnalytics = subscribeToPostAnalyticsUpdates((data) => {
      console.log('Real-time post analytics update:', data);
      if (selectedPost && data.postId === selectedPost._id) {
        // Refresh analytics for the selected post
        fetchPostAnalytics(selectedPost);
      }
    });

    // Subscribe to referral updates
    const unsubscribeReferral = subscribeToReferralUpdates((data) => {
      console.log('Real-time referral update:', data);
      if (selectedPost && data.referral && data.referral.post === selectedPost._id) {
        // Refresh analytics for the selected post when new referral happens
        fetchPostAnalytics(selectedPost);
      }
    });

    return () => {
      socket.off('postCreated', handlePostCreated);
      unsubscribePostAnalytics();
      unsubscribeReferral();
    };
  }, [user, selectedPost]);

  // 🚀 Fetch REAL referral chains from comprehensive tracking
  const fetchReferralChains = async (post) => {
    try {
      setChainsLoading(true);
      const response = await comprehensiveReferralService.getPostChains(post._id);
      if (response.success) {
        setReferralChains(response.chains || []);
        console.log('✅ Loaded REAL referral chains:', response.chains?.length || 0);
      }
    } catch (error) {
      console.error('Error fetching referral chains:', error);
      setReferralChains([]);
    } finally {
      setChainsLoading(false);
    }
  };

  const fetchPostAnalytics = async (post) => {
    try {
      const token = localStorage.getItem('token');
      if (token) {
        axios.defaults.headers.common['Authorization'] = `Bearer ${token}`;

        // Check if user is the creator of this post
        if (post.creator && post.creator._id === user?._id) {
          // Post creator: Fetch their own post analytics
          try {
            const res = await axios.get(`${REACT_APP_API_URL}/analytics/my-post/${post._id}`);
            setPostAnalytics(res.data);
          } catch (error) {
            if (error.response?.status === 403) {
              // Fallback to limited data if permission denied
              const postData = {
                post: post,
                analytics: {
                  totalReferrals: 0,
                  totalClicks: 0,
                  totalEarnings: 0,
                  totalConversions: 0,
                  conversionRate: 0,
                  platformStats: [],
                  geoStats: [],
                  deviceStats: [],
                  timeStats: []
                },
                referralChain: [],
                commissions: []
              };
              postData.post.referralLink = `https://referral-hub-frontend.vercel.app/post/${post._id}`;
              setPostAnalytics(postData);
            } else {
              throw error;
            }
          }
        } else if (user?.role === 'admin') {
          // Admin: Fetch comprehensive analytics for this post
          try {
            const res = await axios.get(`${REACT_APP_API_URL}/admin/post-analytics/${post._id}`);
            setPostAnalytics(res.data);
          } catch (error) {
            if (error.response?.status === 403) {
              // Fallback to limited data if permission denied
              const postData = {
                post: post,
                analytics: {
                  totalReferrals: 0,
                  totalClicks: 0,
                  totalEarnings: 0,
                  totalConversions: 0,
                  conversionRate: 0,
                  platformStats: [],
                  geoStats: [],
                  deviceStats: [],
                  timeStats: []
                },
                referralChain: [],
                commissions: []
              };
              postData.post.referralLink = `https://referral-hub-frontend.vercel.app/post/${post._id}`;
              setPostAnalytics(postData);
            } else {
              throw error;
            }
          }
        } else {
          // Other users: Show limited data or access denied
          const postData = {
            post: post,
            analytics: {
              totalReferrals: 0,
              totalClicks: 0,
              totalEarnings: 0,
              totalConversions: 0,
              conversionRate: 0,
              platformStats: [],
              geoStats: [],
              deviceStats: [],
              timeStats: []
            },
            referralChain: [],
            commissions: []
          };
          postData.post.referralLink = `https://referral-hub-frontend.vercel.app/post/${post._id}`;
          setPostAnalytics(postData);
        }
      }
    } catch (error) {
      console.error('Error fetching post analytics:', error);
      setPostAnalytics(null);
    } finally {
      setAnalyticsLoading(false);
    }
  };

  const handlePostSelect = async (post) => {
    setSelectedPost(post);
    setAnalyticsLoading(true);

    // Join the post room for real-time updates
    joinPostRoom(post._id);
    
    // 🚀 Fetch REAL referral chains
    fetchReferralChains(post);

    await fetchPostAnalytics(post);
  };

  return (
    <div className="min-h-screen bg-gray-100">
      <Navbar />

      <header className="bg-white shadow">
        <div className="max-w-7xl mx-auto py-6 px-4 sm:px-6 lg:px-8">
          <h1 className="text-3xl font-bold text-gray-900">Referral Journey Map</h1>
          <p className="mt-2 text-gray-600">Track how your referrals spread across locations and platforms</p>
        </div>
      </header>

      <main className="max-w-7xl mx-auto py-6 sm:px-6 lg:px-8">
        {/* Post Selection */}
        <div className="bg-white p-6 rounded-lg shadow mb-6">
          <h2 className="text-lg font-medium text-gray-900 mb-4">Select Post to View Journey</h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {Array.isArray(posts) && posts.map((post) => (
              <div
                key={post._id}
                onClick={() => handlePostSelect(post)}
                className={`p-4 border rounded-lg cursor-pointer transition-all hover:shadow-md ${
                  selectedPost?._id === post._id
                    ? 'border-blue-500 bg-blue-50 shadow-md'
                    : 'border-gray-200 hover:border-gray-300'
                }`}
              >
                {/* Photo Display */}
                {post.photos && post.photos.length > 0 && (
                  <div className="mb-3">
                    <div className="grid grid-cols-2 gap-1">
                      {post.photos.slice(0, 2).map((photo, index) => (
                        <div key={index} className="aspect-square rounded-md overflow-hidden border border-gray-200">
                          <img
                            src={photo?.startsWith('//') ? `https:${photo}` : (photo?.startsWith('http://') ? photo.replace('http://', 'https://') : photo)}
                            alt={`Photo ${index + 1}`}
                            className="w-full h-full object-cover hover:scale-105 transition-transform duration-200"
                          />
                        </div>
                      ))}
                      {post.photos.length > 2 && (
                        <div className="aspect-square rounded-md bg-gray-100 border border-gray-200 flex items-center justify-center">
                          <span className="text-xs text-gray-600 font-medium">+{post.photos.length - 2}</span>
                        </div>
                      )}
                    </div>
                  </div>
                )}

                <h3 className="font-medium text-gray-900 line-clamp-2">{post.title}</h3>
                <p className="text-sm text-gray-600 mt-1 line-clamp-2">{post.description}</p>

                {/* Price Display */}
                <div className="flex items-center justify-between mt-2">
                  <div className="flex items-center space-x-2">
                    {post.originalPrice && (
                      <span className="text-xs text-gray-500 line-through">${post.originalPrice}</span>
                    )}
                    {post.price && (
                      <span className="text-sm font-semibold text-green-600">${post.price}</span>
                    )}
                  </div>
                  <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                    post.status === 'active' ? 'bg-green-100 text-green-800' :
                    post.status === 'sold' ? 'bg-red-100 text-red-800' :
                    'bg-gray-100 text-gray-800'
                  }`}>
                    {post.status?.toUpperCase() || 'ACTIVE'}
                  </span>
                </div>

                {user?.role === 'admin' && post.creator && (
                  <p className="text-xs text-purple-600 mt-2">By: {post.creator.email}</p>
                )}
                <p className="text-xs text-blue-600 mt-1 break-all line-clamp-1">{post.referralLink}</p>
              </div>
            ))}
          </div>
        </div>

        {/* Journey Map */}
        {selectedPost && (
          <div className="space-y-6">
            {/* Post Overview */}
            <div className="bg-white p-6 rounded-lg shadow">
              <div className="flex justify-between items-start mb-6">
                <div className="flex-1">
                  {/* Photo Gallery */}
                  {selectedPost.photos && selectedPost.photos.length > 0 && (
                    <div className="mb-4">
                      <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
                        {selectedPost.photos.slice(0, 4).map((photo, index) => (
                          <div key={index} className="aspect-square rounded-lg overflow-hidden border border-gray-200">
                          <img
                              src={photo?.startsWith('//') ? `https:${photo}` : (photo?.startsWith('http://') ? photo.replace('http://', 'https://') : photo)}
                              alt={`Photo ${index + 1}`}
                              className="w-full h-full object-cover hover:scale-105 transition-transform duration-200"
                            />
                          </div>
                        ))}
                      </div>
                    </div>
                  )}

                  <h2 className="text-2xl font-bold text-gray-900">{selectedPost.title}</h2>
                  <p className="text-gray-600 mt-1">{selectedPost.description}</p>
                  <div className="flex items-center justify-between mt-3">
                    <div className="flex items-center space-x-4">
                      <span className="text-sm text-gray-500">Created by: <span className="font-medium text-purple-600">{selectedPost.creator?.email}</span></span>
                      <span className="text-sm text-gray-500">Category: <span className="font-medium">{selectedPost.category}</span></span>
                      <span className="text-sm text-gray-500">Price: <span className="font-medium">${selectedPost.price}</span></span>
                    </div>
                    <button
                      onClick={() => navigate(`/post-analytics/${selectedPost._id}`)}
                      className="px-4 py-2 bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-lg hover:from-blue-700 hover:to-purple-700 font-semibold text-sm flex items-center space-x-2"
                      title="View detailed analytics with viewHistory & shareHistory"
                    >
                      <span>📊</span>
                      <span>View Complete Analytics</span>
                    </button>
                  </div>
                </div>
                <span className={`px-3 py-1 rounded-full text-sm font-medium ml-4 ${
                  selectedPost.status === 'active' ? 'bg-green-100 text-green-800' :
                  selectedPost.status === 'sold' ? 'bg-red-100 text-red-800' :
                  'bg-gray-100 text-gray-800'
                }`}>
                  {selectedPost.status?.toUpperCase() || 'ACTIVE'}
                </span>
              </div>
            </div>

            {/* Performance Metrics */}
            {postAnalytics && postAnalytics.analytics && (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <div className="bg-white p-6 rounded-lg shadow">
                  <div className="flex items-center">
                    <div className="flex-shrink-0">
                      <div className="w-8 h-8 bg-blue-100 rounded-full flex items-center justify-center">
                        <span className="text-blue-600 text-sm font-semibold">👁️</span>
                      </div>
                    </div>
                    <div className="ml-5 w-0 flex-1">
                      <dl>
                        <dt className="text-sm font-medium text-gray-500 truncate">Total Clicks</dt>
                        <dd className="text-lg font-medium text-gray-900">{postAnalytics.analytics.totalClicks || 0}</dd>
                      </dl>
                    </div>
                  </div>
                </div>

                <div className="bg-white p-6 rounded-lg shadow">
                  <div className="flex items-center">
                    <div className="flex-shrink-0">
                      <div className="w-8 h-8 bg-green-100 rounded-full flex items-center justify-center">
                        <span className="text-green-600 text-sm font-semibold">🎯</span>
                      </div>
                    </div>
                    <div className="ml-5 w-0 flex-1">
                      <dl>
                        <dt className="text-sm font-medium text-gray-500 truncate">Conversions</dt>
                        <dd className="text-lg font-medium text-gray-900">{postAnalytics.analytics.totalConversions || 0}</dd>
                      </dl>
                    </div>
                  </div>
                </div>

                <div className="bg-white p-6 rounded-lg shadow">
                  <div className="flex items-center">
                    <div className="flex-shrink-0">
                      <div className="w-8 h-8 bg-purple-100 rounded-full flex items-center justify-center">
                        <span className="text-purple-600 text-sm font-semibold">💰</span>
                      </div>
                    </div>
                    <div className="ml-5 w-0 flex-1">
                      <dl>
                        <dt className="text-sm font-medium text-gray-500 truncate">Total Earnings</dt>
                        <dd className="text-lg font-medium text-gray-900">${postAnalytics.analytics.totalEarnings || 0}</dd>
                      </dl>
                    </div>
                  </div>
                </div>

                <div className="bg-white p-6 rounded-lg shadow">
                  <div className="flex items-center">
                    <div className="flex-shrink-0">
                      <div className="w-8 h-8 bg-yellow-100 rounded-full flex items-center justify-center">
                        <span className="text-yellow-600 text-sm font-semibold">📊</span>
                      </div>
                    </div>
                    <div className="ml-5 w-0 flex-1">
                      <dl>
                        <dt className="text-sm font-medium text-gray-500 truncate">Conversion Rate</dt>
                        <dd className="text-lg font-medium text-gray-900">{postAnalytics.analytics.conversionRate || 0}%</dd>
                      </dl>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* Platform & Geographic Analytics */}
            {postAnalytics && postAnalytics.analytics && (
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                {/* Platform Distribution */}
                <div className="bg-white p-6 rounded-lg shadow">
                  <h3 className="text-lg font-medium text-gray-900 mb-4">Platform Distribution</h3>
                  <div className="space-y-3">
                    {Array.isArray(postAnalytics.analytics.platformStats) && postAnalytics.analytics.platformStats.map((platform, index) => (
                      <div key={index} className="flex justify-between items-center">
                        <span className="font-medium capitalize">{platform.platform}</span>
                        <span className="text-blue-600 font-semibold">{platform.clicks} clicks</span>
                      </div>
                    ))}
                    {(!postAnalytics.analytics.platformStats || postAnalytics.analytics.platformStats.length === 0) && (
                      <p className="text-gray-500">No platform data available</p>
                    )}
                  </div>
                </div>

                {/* Geographic Distribution */}
                <div className="bg-white p-6 rounded-lg shadow">
                  <h3 className="text-lg font-medium text-gray-900 mb-4">Geographic Distribution</h3>
                  <div className="space-y-3">
                    {Array.isArray(postAnalytics.analytics.geoStats) && postAnalytics.analytics.geoStats.slice(0, 5).map((geo, index) => (
                      <div key={index} className="flex justify-between items-center">
                        <span className="font-medium">{geo.city}, {geo.state}</span>
                        <span className="text-green-600 font-semibold">{geo.clicks} clicks</span>
                      </div>
                    ))}
                    {(!postAnalytics.analytics.geoStats || postAnalytics.analytics.geoStats.length === 0) && (
                      <p className="text-gray-500">No geographic data available</p>
                    )}
                  </div>
                </div>
              </div>
            )}

            {/* Journey Map */}
            <div className="bg-white p-6 rounded-lg shadow">
              <h2 className="text-xl font-medium text-gray-900 mb-4">Referral Journey Map</h2>
              <RealTimeJourneyVisualization postId={selectedPost._id} />
            </div>

            {/* ✅ REAL COMPREHENSIVE REFERRAL CHAINS */}
            <div className="bg-white p-6 rounded-lg shadow">
              <h2 className="text-xl font-medium text-gray-900 mb-4 flex items-center">
                🔗 Complete Referral Chains
                {!chainsLoading && referralChains.length > 0 && (
                  <span className="ml-3 px-3 py-1 bg-blue-100 text-blue-700 rounded-full text-sm font-semibold">
                    {referralChains.length} Chain{referralChains.length !== 1 ? 's' : ''}
                  </span>
                )}
              </h2>
              
              <div className="space-y-6">
                {chainsLoading ? (
                  <div className="text-center py-8">
                    <div className="animate-spin rounded-full h-12 w-12 border-t-4 border-b-4 border-blue-600 mx-auto mb-4"></div>
                    <p className="text-gray-600">Loading referral chains...</p>
                  </div>
                ) : referralChains.length === 0 ? (
                  <div className="text-center py-12 bg-gray-50 rounded-lg">
                    <p className="text-gray-600 text-lg mb-2">No referral chains yet for this post</p>
                    <p className="text-gray-500 text-sm">Share the post to start building your referral network!</p>
                  </div>
                ) : (
                  referralChains.map((chain, chainIndex) => (
                    <div key={chain.chainId || chainIndex} className="border-2 border-blue-200 rounded-xl p-6 bg-gradient-to-r from-blue-50 to-purple-50">
                      {/* Chain Header */}
                      <div className="flex items-center justify-between mb-6">
                        <div>
                          <h3 className="font-bold text-lg text-gray-900">Chain #{chainIndex + 1}</h3>
                          <p className="text-sm text-gray-600">Chain ID: {chain.chainId}</p>
                        </div>
                        <div className="flex items-center space-x-4">
                          <div className="text-center">
                            <div className="text-2xl font-bold text-blue-600">{chain.totalClicks || 0}</div>
                            <div className="text-xs text-gray-600">Clicks</div>
                          </div>
                          <div className="text-center">
                            <div className="text-2xl font-bold text-purple-600">{chain.totalViews || 0}</div>
                            <div className="text-xs text-gray-600">Views</div>
                          </div>
                          <div className="text-center">
                            <div className="text-2xl font-bold text-pink-600">{chain.totalShares || 0}</div>
                            <div className="text-xs text-gray-600">Shares</div>
                          </div>
                        </div>
                      </div>

                      {/* ✅ VISUAL CHAIN PATH: A → B → C → D */}
                      {chain.chain && chain.chain.length > 0 && (
                        <>
                          <div className="bg-white rounded-lg p-4 mb-6 overflow-x-auto">
                            <div className="flex items-center space-x-3 min-w-max">
                              {chain.chain.map((person, personIndex) => {
                                const isYou = person.userId === user?._id;
                                return (
                                  <React.Fragment key={person.userId || personIndex}>
                                    <div className={`px-4 py-3 rounded-lg border-2 ${
                                      isYou 
                                        ? 'bg-green-100 border-green-500 text-green-900' 
                                        : 'bg-blue-100 border-blue-500 text-blue-900'
                                    } font-semibold text-center min-w-[120px]`}>
                                      <div className="text-sm">{person.username || `User ${personIndex + 1}`}</div>
                                      {isYou && <div className="text-xs text-green-700">(YOU)</div>}
                                      <div className="text-xs text-gray-600 mt-1">Position {person.position || personIndex + 1}</div>
                                    </div>
                                    {personIndex < chain.chain.length - 1 && (
                                      <div className="text-2xl text-gray-400 font-bold">→</div>
                                    )}
                                  </React.Fragment>
                                );
                              })}
                            </div>
                          </div>

                          {/* ✅ DETAILED INFO FOR EACH PERSON IN CHAIN */}
                          <div className="space-y-4">
                            {chain.chain.map((person, personIndex) => {
                              const isYou = person.userId === user?._id;
                              return (
                                <div key={person.userId || personIndex} className={`border rounded-lg p-4 ${
                                  isYou ? 'bg-green-50 border-green-300' : 'bg-white border-gray-200'
                                }`}>
                                  <div className="flex items-start justify-between mb-3">
                                    <div>
                                      <h4 className="font-bold text-gray-900">
                                        {person.username || `User ${personIndex + 1}`}
                                        {isYou && <span className="ml-2 px-2 py-1 bg-green-200 text-green-800 rounded text-xs">YOU</span>}
                                      </h4>
                                      <p className="text-sm text-gray-600">Position {person.position || personIndex + 1} in chain</p>
                                    </div>
                                    {person.sharedAt && (
                                      <div className="text-right text-sm text-gray-600">
                                        Joined: {new Date(person.sharedAt).toLocaleDateString()}
                                      </div>
                                    )}
                                  </div>

                                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
                                    <div>
                                      <span className="text-gray-600">📱 Device:</span>
                                      <p className="font-medium capitalize">{person.device || 'Unknown'}</p>
                                    </div>
                                    <div>
                                      <span className="text-gray-600">🌐 Browser:</span>
                                      <p className="font-medium">{person.browser || 'Unknown'}</p>
                                    </div>
                                    <div>
                                      <span className="text-gray-600">📍 Location:</span>
                                      <p className="font-medium">{person.location?.city || 'Unknown'}, {person.location?.country || ''}</p>
                                    </div>
                                    <div>
                                      <span className="text-gray-600">🔗 Platform:</span>
                                      <p className="font-medium capitalize">{person.platform || 'Web'}</p>
                                    </div>
                                  </div>

                                  <div className="grid grid-cols-3 gap-4 mt-4 pt-4 border-t border-gray-200">
                                    <div className="text-center">
                                      <div className="text-lg font-bold text-blue-600">{person.clicks || 0}</div>
                                      <div className="text-xs text-gray-600">Clicks on their link</div>
                                    </div>
                                    <div className="text-center">
                                      <div className="text-lg font-bold text-purple-600">{person.views || 0}</div>
                                      <div className="text-xs text-gray-600">Views generated</div>
                                    </div>
                                    <div className="text-center">
                                      <div className="text-lg font-bold text-pink-600">{person.shares || 0}</div>
                                      <div className="text-xs text-gray-600">Times shared</div>
                                    </div>
                                  </div>
                                </div>
                              );
                            })}
                          </div>
                        </>
                      )}
                    </div>
                  ))
                )}
              </div>
            </div>
          </div>
        )}

        {!selectedPost && (
          <div className="bg-white p-12 rounded-lg shadow text-center">
            <h3 className="text-lg font-medium text-gray-900 mb-2">Select a Post</h3>
            <p className="text-gray-600">Choose a post from above to view its referral journey map and detailed analytics.</p>
          </div>
        )}
      </main>
    </div>
  );
};

export default Journey;