import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { getSocket } from '../utils/socket';
import { fetchReferralChains } from '../utils/referralApi';
import { formatDistanceToNow } from 'date-fns';

const ReferralTreeView = ({ postId, commissionData = [] }) => {
  const [treeData, setTreeData] = useState([]);
  const [flattenedNodes, setFlattenedNodes] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [expandedNodes, setExpandedNodes] = useState(new Set());
  const [filters, setFilters] = useState({
    platform: 'all',
    deviceType: 'all',
    browser: 'all'
  });
  const [searchTerm, setSearchTerm] = useState('');
  const [hoveredPath, setHoveredPath] = useState([]);

  useEffect(() => {
    loadTreeData();
    setupSocketListeners();

    return () => {
      const socket = getSocket();
      socket.off('referral_update');
      socket.emit('leave_post_room', postId);
    };
  }, [postId]);

  const loadTreeData = async () => {
    try {
      setIsLoading(true);
      const response = await fetchReferralChains(postId);
      if (response.success) {
        setTreeData(response.tree);
        // Auto-expand root nodes
        const rootIds = response.tree.map(node => node._id);
        setExpandedNodes(new Set(rootIds));
      }
    } catch (error) {
      console.error('Error loading tree:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const setupSocketListeners = () => {
    const socket = getSocket();
    socket.emit('join_post_room', postId);

    socket.on('referral_update', (data) => {
      if (data.postId === postId) {
        handleNewReferral(data.chainNode);
      }
    });
  };

  const handleNewReferral = (newNode) => {
    // Animate and add new node
    setTreeData(prev => {
      const updated = [...prev];
      // Find parent and add child
      const addToTree = (nodes) => {
        for (let node of nodes) {
          if (node._id === newNode.parentChainId) {
            if (!node.children) node.children = [];
            node.children.push({
              ...newNode,
              _id: newNode.id,
              children: [],
              _isNew: true // Flag for animation
            });
            return true;
          }
          if (node.children && addToTree(node.children)) {
            return true;
          }
        }
        return false;
      };

      if (!newNode.parentChainId) {
        // Root node
        updated.push({
          ...newNode,
          _id: newNode.id,
          children: [],
          _isNew: true
        });
      } else {
        addToTree(updated);
      }

      return updated;
    });

    // Remove animation flag after 2 seconds
    setTimeout(() => {
      setTreeData(prev => {
        const removeFlag = (nodes) => {
          nodes.forEach(node => {
            delete node._isNew;
            if (node.children) removeFlag(node.children);
          });
        };
        const updated = [...prev];
        removeFlag(updated);
        return updated;
      });
    }, 2000);
  };

  // Flatten tree for virtualization
  useEffect(() => {
    const flatten = (nodes, depth = 0, path = []) => {
      const result = [];
      nodes.forEach((node, index) => {
        const currentPath = [...path, node._id];
        const isExpanded = expandedNodes.has(node._id);
        
        // Apply filters
        if (filters.platform !== 'all' && node.platform !== filters.platform) return;
        if (filters.deviceType !== 'all' && node.deviceInfo?.type !== filters.deviceType) return;
        if (filters.browser !== 'all' && node.deviceInfo?.browser !== filters.browser) return;
        if (searchTerm && !node.user?.username?.toLowerCase().includes(searchTerm.toLowerCase())) return;

        result.push({ ...node, depth, path: currentPath, isExpanded, index });
        
        if (isExpanded && node.children && node.children.length > 0) {
          result.push(...flatten(node.children, depth + 1, currentPath));
        }
      });
      return result;
    };

    setFlattenedNodes(flatten(treeData));
  }, [treeData, expandedNodes, filters, searchTerm]);

  const toggleNode = useCallback((nodeId) => {
    setExpandedNodes(prev => {
      const newSet = new Set(prev);
      if (newSet.has(nodeId)) {
        newSet.delete(nodeId);
      } else {
        newSet.add(nodeId);
      }
      return newSet;
    });
  }, []);

  const expandAll = useCallback(() => {
    const allIds = new Set();
    const collectIds = (nodes) => {
      nodes.forEach(node => {
        allIds.add(node._id);
        if (node.children) collectIds(node.children);
      });
    };
    collectIds(treeData);
    setExpandedNodes(allIds);
  }, [treeData]);

  const collapseAll = useCallback(() => {
    const rootIds = treeData.map(node => node._id);
    setExpandedNodes(new Set(rootIds));
  }, [treeData]);

  const getCommission = useCallback((nodeId) => {
    const commission = commissionData.find(c => c.chainId === nodeId);
    return commission?.commission || 0;
  }, [commissionData]);

  const getPlatformIcon = (platform) => {
    const icons = {
      whatsapp: '💬',
      linkedin: '💼',
      twitter: '🐦',
      facebook: '👥',
      instagram: '📷',
      telegram: '✈️',
      email: '📧',
      sms: '📱',
      direct: '🔗',
      other: '🌐'
    };
    return icons[platform] || '🌐';
  };

  const getDeviceIcon = (deviceType) => {
    const icons = {
      mobile: '📱',
      tablet: '📱',
      desktop: '💻',
      unknown: '❓'
    };
    return icons[deviceType] || '❓';
  };

  const TreeNode = ({ node, depth }) => {
    const hasChildren = node.children && node.children.length > 0;
    const commission = getCommission(node._id);
    const isHighlighted = hoveredPath.includes(node._id);

    return (
      <div
        className={`
          relative transition-all duration-300
          ${node._isNew ? 'animate-pulse bg-blue-50' : ''}
          ${isHighlighted ? 'bg-yellow-50' : ''}
        `}
        style={{ paddingLeft: `${depth * 40}px` }}
        onMouseEnter={() => setHoveredPath(node.path || [])}
        onMouseLeave={() => setHoveredPath([])}
      >
        <div className="flex items-start gap-3 py-2">
          {/* Connector Line */}
          {depth > 0 && (
            <div className="absolute left-0 top-0 bottom-0" style={{ left: `${(depth - 1) * 40 + 16}px` }}>
              <div className="h-full border-l-2 border-gray-300"></div>
              <div className="absolute top-6 w-8 border-t-2 border-gray-300"></div>
            </div>
          )}

          {/* Expand/Collapse Button */}
          {hasChildren ? (
            <button
              onClick={() => toggleNode(node._id)}
              className="flex-shrink-0 w-6 h-6 rounded-full bg-blue-600 text-white flex items-center justify-center text-xs hover:bg-blue-700 transition-colors z-10"
            >
              {node.isExpanded ? '−' : '+'}
            </button>
          ) : (
            <div className="w-6 h-6 flex-shrink-0"></div>
          )}

          {/* Node Card */}
          <div className="flex-1 bg-white rounded-lg shadow-md hover:shadow-lg transition-shadow p-4 border-2 border-gray-200 hover:border-blue-400 group">
            <div className="flex items-start justify-between">
              {/* User Info */}
              <div className="flex items-center gap-3 flex-1">
                {node.user?.avatar ? (
                  <img
                    src={node.user.avatar}
                    alt={node.user.username}
                    className="w-10 h-10 rounded-full"
                  />
                ) : (
                  <div className="w-10 h-10 rounded-full bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center text-white font-bold">
                    {node.user?.username?.[0]?.toUpperCase() || 'A'}
                  </div>
                )}

                <div className="flex-1 min-w-0">
                  <h4 className="font-semibold text-gray-900 truncate">
                    {node.user?.firstName || node.user?.username || 'Anonymous'}
                  </h4>
                  <p className="text-xs text-gray-500">
                    {formatDistanceToNow(new Date(node.clickData?.timestamp || node.createdAt), { addSuffix: true })}
                  </p>
                </div>
              </div>

              {/* Commission Badge */}
              {commission > 0 && (
                <div className="bg-green-100 text-green-800 px-3 py-1 rounded-full text-xs font-bold whitespace-nowrap">
                  +{Math.round(commission)} pts
                </div>
              )}
            </div>

            {/* Metadata - Hidden, shown on hover */}
            <div className="hidden group-hover:flex flex-wrap gap-2 mt-3 animate-fade-in">
              <span className="inline-flex items-center gap-1 px-2 py-1 bg-blue-50 text-blue-700 rounded text-xs">
                {getPlatformIcon(node.platform)}
                <span className="capitalize">{node.platform}</span>
              </span>

              <span className="inline-flex items-center gap-1 px-2 py-1 bg-purple-50 text-purple-700 rounded text-xs">
                {getDeviceIcon(node.deviceInfo?.type)}
                <span className="capitalize">{node.deviceInfo?.type || 'unknown'}</span>
              </span>

              {node.deviceInfo?.browser && (
                <span className="px-2 py-1 bg-gray-100 text-gray-700 rounded text-xs">
                  {node.deviceInfo.browser}
                </span>
              )}

              {node.location?.city && (
                <span className="inline-flex items-center gap-1 px-2 py-1 bg-orange-50 text-orange-700 rounded text-xs">
                  📍 {node.location.city}, {node.location.country}
                </span>
              )}

              <span className="px-2 py-1 bg-indigo-50 text-indigo-700 rounded text-xs font-semibold">
                Level {node.chainDepth}
              </span>

              {hasChildren && (
                <span className="px-2 py-1 bg-green-50 text-green-700 rounded text-xs font-semibold">
                  {node.children.length} {node.children.length === 1 ? 'child' : 'children'}
                </span>
              )}
            </div>
          </div>
        </div>
      </div>
    );
  };

  // Virtualized rendering for performance
  const VirtualizedTree = useMemo(() => {
    const nodesToShow = flattenedNodes;
    
    // If too many nodes, implement simple virtualization
    if (nodesToShow.length > 500) {
      // Simple virtualization: only render visible nodes
      return nodesToShow.slice(0, 100).map(node => (
        <TreeNode key={node._id} node={node} depth={node.depth} />
      ));
    }

    return nodesToShow.map(node => (
      <TreeNode key={node._id} node={node} depth={node.depth} />
    ));
  }, [flattenedNodes, commissionData, hoveredPath]);

  if (isLoading) {
    return (
      <div className="flex justify-center items-center py-12">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  return (
    <div className="bg-gray-50 rounded-lg p-6">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Referral Tree</h2>
          <p className="text-sm text-gray-600 mt-1">
            {flattenedNodes.length} nodes • {treeData.length} root chains
          </p>
        </div>

        <div className="flex gap-2">
          <button
            onClick={expandAll}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 text-sm"
          >
            Expand All
          </button>
          <button
            onClick={collapseAll}
            className="px-4 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700 text-sm"
          >
            Collapse All
          </button>
        </div>
      </div>

      {/* Search Bar */}
      <div className="mb-4">
        <input
          type="text"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          placeholder="Search by username..."
          className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-blue-500"
        />
      </div>

      {/* Filters */}
      <div className="bg-white rounded-lg p-4 mb-6 shadow-sm">
        <h3 className="font-semibold text-gray-700 mb-3">Filters</h3>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Platform</label>
            <select
              value={filters.platform}
              onChange={(e) => setFilters({ ...filters, platform: e.target.value })}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-blue-500"
            >
              <option value="all">All Platforms</option>
              <option value="whatsapp">WhatsApp</option>
              <option value="linkedin">LinkedIn</option>
              <option value="twitter">Twitter</option>
              <option value="facebook">Facebook</option>
              <option value="instagram">Instagram</option>
              <option value="direct">Direct</option>
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Device Type</label>
            <select
              value={filters.deviceType}
              onChange={(e) => setFilters({ ...filters, deviceType: e.target.value })}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-blue-500"
            >
              <option value="all">All Devices</option>
              <option value="mobile">Mobile</option>
              <option value="tablet">Tablet</option>
              <option value="desktop">Desktop</option>
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Browser</label>
            <select
              value={filters.browser}
              onChange={(e) => setFilters({ ...filters, browser: e.target.value })}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-blue-500"
            >
              <option value="all">All Browsers</option>
              <option value="Chrome">Chrome</option>
              <option value="Safari">Safari</option>
              <option value="Firefox">Firefox</option>
              <option value="Edge">Edge</option>
            </select>
          </div>
        </div>
      </div>

      {/* Tree Visualization */}
      <div className="bg-white rounded-lg p-6 shadow-sm overflow-auto max-h-[800px]">
        {flattenedNodes.length === 0 ? (
          <div className="text-center py-12 text-gray-500">
            <p className="text-lg mb-2">No referrals match your filters</p>
            <p className="text-sm">Try adjusting your filters</p>
          </div>
        ) : (
          <div className="space-y-2">
            {VirtualizedTree}
            {flattenedNodes.length > 500 && (
              <div className="text-center py-4 text-gray-500 text-sm">
                Showing first 100 of {flattenedNodes.length} nodes for performance
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default ReferralTreeView;

