import React, { useState, useEffect } from 'react';
import UserTrackingProfile from '../components/UserTrackingProfile';
import Navbar from '../components/Navbar';
import { REACT_APP_API_URL } from '../utils/constants';

const Profile = () => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchUser = async () => {
      try {
        const token = localStorage.getItem('token');
        if (!token) {
          console.log('❌ No token, redirecting to login...');
          window.location.href = '/login';
          return;
        }
        
        const response = await fetch(`${REACT_APP_API_URL}/auth/profile`, {
          headers: {
            'Authorization': `Bearer ${token}`
          }
        });
        
        if (response.ok) {
          const data = await response.json();
          // Backend returns user directly, not in a wrapper
          setUser(data);
          console.log('✅ Profile loaded:', data.username);
        } else if (response.status === 401) {
          console.log('❌ Unauthorized, redirecting to login...');
          localStorage.removeItem('token');
          localStorage.removeItem('user');
          window.location.href = '/login';
        }
      } catch (error) {
        console.error('Error fetching user:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchUser();
  }, []);

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-900 via-purple-900 to-slate-900">
        <Navbar />
        <div className="flex items-center justify-center h-screen">
          <div className="text-center">
            <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-white mx-auto mb-4"></div>
            <h2 className="text-2xl font-bold text-white mb-2">Loading Profile</h2>
            <p className="text-gray-300">Fetching your REAL data...</p>
          </div>
        </div>
      </div>
    );
  }

  if (!user) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-900 via-purple-900 to-slate-900">
        <Navbar />
        <div className="flex items-center justify-center h-screen">
          <div className="text-center">
            <h2 className="text-2xl font-bold text-white mb-4">Profile Not Loaded</h2>
            <p className="text-gray-300 mb-6">Please log in to view your profile</p>
            <a href="/login" className="px-6 py-3 bg-purple-600 text-white rounded-lg hover:bg-purple-700">
              Go to Login
            </a>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-purple-900 to-slate-900">
      <Navbar />
      <UserTrackingProfile user={user} />
    </div>
  );
};

export default Profile;