import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { FaExternalLinkAlt, FaGlobe, FaImage } from 'react-icons/fa';
import { REACT_APP_API_URL } from '../utils/constants';

const LinkPreview = ({ url, compact = false }) => {
  const [preview, setPreview] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);

  useEffect(() => {
    fetchPreview();
  }, [url]);

  const fetchPreview = async () => {
    if (!url) return;

    try {
      setLoading(true);
      setError(false);

      const token = localStorage.getItem('token');
      if (!token) {
        setError(true);
        return;
      }

      axios.defaults.headers.common['Authorization'] = `Bearer ${token}`;
      const response = await axios.post(`${REACT_APP_API_URL}/link-previews/preview`, { url });

      setPreview(response.data);
    } catch (err) {
      console.error('Error fetching link preview:', err);
      setError(true);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className={`bg-gray-50 border border-gray-200 rounded-lg p-4 ${compact ? 'flex items-center space-x-3' : ''}`}>
        <div className="animate-pulse">
          {compact ? (
            <>
              <div className="w-12 h-12 bg-gray-300 rounded"></div>
              <div className="flex-1 space-y-2">
                <div className="h-4 bg-gray-300 rounded w-3/4"></div>
                <div className="h-3 bg-gray-300 rounded w-1/2"></div>
              </div>
            </>
          ) : (
            <div className="space-y-3">
              <div className="h-4 bg-gray-300 rounded w-3/4"></div>
              <div className="h-32 bg-gray-300 rounded"></div>
              <div className="space-y-2">
                <div className="h-4 bg-gray-300 rounded w-1/2"></div>
                <div className="h-3 bg-gray-300 rounded w-2/3"></div>
              </div>
            </div>
          )}
        </div>
      </div>
    );
  }

  if (error || !preview || preview.error) {
    return (
      <div className={`bg-gray-50 border border-gray-200 rounded-lg p-4 ${compact ? 'flex items-center space-x-3' : ''}`}>
        <div className="flex items-center space-x-3 text-gray-500">
          <FaGlobe className="w-5 h-5" />
          <div className="flex-1">
            <p className="text-sm font-medium">Link Preview</p>
            <p className="text-xs text-gray-400 truncate">{url}</p>
          </div>
          <a
            href={url}
            target="_blank"
            rel="noopener noreferrer"
            className="text-gray-400 hover:text-gray-600"
          >
            <FaExternalLinkAlt className="w-4 h-4" />
          </a>
        </div>
      </div>
    );
  }

  if (compact) {
    return (
      <a
        href={url}
        target="_blank"
        rel="noopener noreferrer"
        className="block bg-white border border-gray-200 rounded-lg hover:shadow-md transition-shadow duration-200 overflow-hidden"
      >
        <div className="flex items-center space-x-3 p-3">
          {preview.image ? (
            <img
              src={preview.image}
              alt={preview.title}
              className="w-12 h-12 object-cover rounded"
              onError={(e) => {
                e.target.style.display = 'none';
                e.target.nextElementSibling.style.display = 'flex';
              }}
            />
          ) : null}
          {!preview.image && (
            <div className="w-12 h-12 bg-gradient-to-br from-blue-100 to-blue-200 rounded flex items-center justify-center">
              <FaImage className="w-6 h-6 text-blue-500" />
            </div>
          )}
          <div className="flex-1 min-w-0">
            <h4 className="text-sm font-semibold text-gray-900 truncate">
              {preview.title}
            </h4>
            <p className="text-xs text-gray-600 truncate">
              {preview.siteName || preview.domain}
            </p>
          </div>
          <FaExternalLinkAlt className="w-4 h-4 text-gray-400 flex-shrink-0" />
        </div>
      </a>
    );
  }

  return (
    <a
      href={url}
      target="_blank"
      rel="noopener noreferrer"
      className="block bg-white border border-gray-200 rounded-lg hover:shadow-lg transition-all duration-200 overflow-hidden group"
    >
      {preview.image && (
        <div className="relative overflow-hidden">
          <img
            src={preview.image}
            alt={preview.title}
            className="w-full h-48 object-cover group-hover:scale-105 transition-transform duration-200"
            onError={(e) => {
              e.target.style.display = 'none';
              e.target.nextElementSibling.style.display = 'flex';
            }}
          />
          <div className="absolute inset-0 bg-black bg-opacity-0 group-hover:bg-opacity-10 transition-all duration-200"></div>
          <div className="absolute top-2 right-2 bg-white bg-opacity-90 rounded-full p-2 opacity-0 group-hover:opacity-100 transition-opacity duration-200">
            <FaExternalLinkAlt className="w-4 h-4 text-gray-700" />
          </div>
        </div>
      )}

      <div className="p-4">
        <div className="flex items-start justify-between mb-2">
          <div className="flex-1 min-w-0">
            <h3 className="text-lg font-semibold text-gray-900 mb-1 line-clamp-2">
              {preview.title}
            </h3>
            {preview.siteName && (
              <p className="text-sm text-blue-600 font-medium mb-1">
                {preview.siteName}
              </p>
            )}
          </div>
          {preview.favicon && (
            <img
              src={preview.favicon}
              alt="Favicon"
              className="w-5 h-5 rounded flex-shrink-0 ml-2"
              onError={(e) => e.target.style.display = 'none'}
            />
          )}
        </div>

        {preview.description && (
          <p className="text-sm text-gray-600 mb-3 line-clamp-3">
            {preview.description}
          </p>
        )}

        <div className="flex items-center justify-between text-xs text-gray-500">
          <span className="flex items-center space-x-1">
            <FaGlobe className="w-3 h-3" />
            <span>{preview.domain}</span>
          </span>
          <span className="text-gray-400">
            {preview.type || 'website'}
          </span>
        </div>
      </div>
    </a>
  );
};

export default LinkPreview;