import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { format } from 'date-fns';
import {
  FaMobile, FaDesktop, FaTablet, FaChrome, FaSafari, FaFirefox, FaEdge,
  FaMapMarkerAlt, FaGlobe, FaClock, FaSignInAlt, FaHistory, FaNetworkWired,
  FaWifi, FaSignal, FaTachometerAlt, FaEye, FaMousePointer, FaShieldAlt,
  FaChartBar, FaBrain, FaLayerGroup
} from 'react-icons/fa';
import { API_BASE_URL } from '../utils/constants';
import { LineChart, Line, BarChart, Bar, PieChart, Pie, Cell, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884D8', '#82CA9D'];

const UserTrackingProfile = ({ userId }) => {
  const [trackingData, setTrackingData] = useState(null);
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [timeRange, setTimeRange] = useState(30);

  useEffect(() => {
    fetchUserTrackingData();
  }, [userId, timeRange]);

  const fetchUserTrackingData = async () => {
    try {
      setLoading(true);
      
      // Fetch user profile
      const userResponse = await axios.get(`${API_BASE_URL}/auth/profile`, {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
      });
      setUser(userResponse.data);

      // Fetch comprehensive tracking data
      const trackingResponse = await axios.get(
        `${API_BASE_URL}/tracking/comprehensive/user/${userId}?timeRange=${timeRange}&limit=100`,
        {
          headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
        }
      );
      setTrackingData(trackingResponse.data);
      
      setLoading(false);
    } catch (error) {
      console.error('Error fetching user tracking data:', error);
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500"></div>
      </div>
    );
  }

  if (!trackingData || !user) {
    return (
      <div className="text-center py-12">
        <p className="text-gray-500">No tracking data available</p>
      </div>
    );
  }

  const { summary, data } = trackingData;

  // Prepare chart data
  const deviceChartData = Object.entries(summary?.deviceBreakdown || {}).map(([device, count]) => ({
    name: device.charAt(0).toUpperCase() + device.slice(1),
    value: count
  }));

  const browserChartData = Object.entries(summary?.browserBreakdown || {}).map(([browser, count]) => ({
    name: browser,
    value: count
  }));

  const locationChartData = Object.entries(summary?.locationBreakdown || {}).map(([location, count]) => ({
    name: location,
    value: count
  })).slice(0, 5); // Top 5 locations

  const platformChartData = Object.entries(summary?.platformBreakdown || {}).map(([platform, count]) => ({
    name: platform.charAt(0).toUpperCase() + platform.slice(1),
    value: count
  }));

  return (
    <div className="space-y-6">
      {/* User Info Card */}
      <div className="bg-gradient-to-r from-blue-600 to-purple-600 rounded-xl p-6 text-white">
        <div className="flex items-center justify-between">
          <div>
            <h2 className="text-2xl font-bold mb-2">User Tracking Profile</h2>
            <p className="text-blue-100">{user.username} ({user.email})</p>
            <p className="text-sm text-blue-200 mt-1">
              Account created: {format(new Date(user.createdAt), 'MMM d, yyyy')}
            </p>
          </div>
          <div className="text-right">
            <p className="text-3xl font-bold">{summary?.totalSessions || 0}</p>
            <p className="text-sm text-blue-100">Total Sessions</p>
          </div>
        </div>

        {/* Quick Stats */}
        <div className="grid grid-cols-3 gap-4 mt-6">
          <div className="bg-white/20 rounded-lg p-3">
            <p className="text-2xl font-bold">{summary?.avgAttentionScore || 0}</p>
            <p className="text-xs text-blue-100">Avg Attention</p>
          </div>
          <div className="bg-white/20 rounded-lg p-3">
            <p className="text-2xl font-bold">{Math.round(summary?.avgSessionDuration || 0)}s</p>
            <p className="text-xs text-blue-100">Avg Duration</p>
          </div>
          <div className="bg-white/20 rounded-lg p-3">
            <p className="text-2xl font-bold">{data?.length || 0}</p>
            <p className="text-xs text-blue-100">Recent Sessions</p>
          </div>
        </div>
      </div>

      {/* Time Range Selector */}
      <div className="flex items-center justify-between">
        <h3 className="text-xl font-bold text-gray-900">Activity Overview</h3>
        <select
          value={timeRange}
          onChange={(e) => setTimeRange(parseInt(e.target.value))}
          className="px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
        >
          <option value={7}>Last 7 days</option>
          <option value={30}>Last 30 days</option>
          <option value={90}>Last 90 days</option>
        </select>
      </div>

      {/* Device & Browser Analytics */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Device Breakdown */}
        <div className="bg-white rounded-xl p-6 shadow-lg">
          <h3 className="text-xl font-bold text-gray-900 mb-4 flex items-center">
            <FaMobile className="mr-2 text-blue-500" />
            Devices Used
          </h3>
          <ResponsiveContainer width="100%" height={250}>
            <PieChart>
              <Pie
                data={deviceChartData}
                cx="50%"
                cy="50%"
                labelLine={false}
                label={({ name, percent }) => `${name}: ${(percent * 100).toFixed(0)}%`}
                outerRadius={80}
                fill="#8884d8"
                dataKey="value"
              >
                {deviceChartData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>

          {/* Device List */}
          <div className="mt-4 space-y-2">
            {deviceChartData.map((device, index) => (
              <div key={index} className="flex items-center justify-between p-2 bg-gray-50 rounded">
                <div className="flex items-center">
                  {device.name === 'Mobile' && <FaMobile className="text-blue-500 mr-2" />}
                  {device.name === 'Desktop' && <FaDesktop className="text-green-500 mr-2" />}
                  {device.name === 'Tablet' && <FaTablet className="text-purple-500 mr-2" />}
                  <span className="text-sm font-medium">{device.name}</span>
                </div>
                <span className="text-sm font-bold">{device.value}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Browser Breakdown */}
        <div className="bg-white rounded-xl p-6 shadow-lg">
          <h3 className="text-xl font-bold text-gray-900 mb-4 flex items-center">
            <FaChrome className="mr-2 text-green-500" />
            Browsers Used
          </h3>
          <ResponsiveContainer width="100%" height={250}>
            <BarChart data={browserChartData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="name" />
              <YAxis />
              <Tooltip />
              <Bar dataKey="value" fill="#10B981" />
            </BarChart>
          </ResponsiveContainer>

          {/* Browser List */}
          <div className="mt-4 space-y-2">
            {browserChartData.map((browser, index) => (
              <div key={index} className="flex items-center justify-between p-2 bg-gray-50 rounded">
                <div className="flex items-center">
                  {browser.name.includes('Chrome') && <FaChrome className="text-yellow-500 mr-2" />}
                  {browser.name.includes('Firefox') && <FaFirefox className="text-orange-500 mr-2" />}
                  {browser.name.includes('Safari') && <FaSafari className="text-blue-500 mr-2" />}
                  {browser.name.includes('Edge') && <FaEdge className="text-blue-600 mr-2" />}
                  <span className="text-sm font-medium">{browser.name}</span>
                </div>
                <span className="text-sm font-bold">{browser.value}</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Location & Platform Analytics */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Location Breakdown */}
        <div className="bg-white rounded-xl p-6 shadow-lg">
          <h3 className="text-xl font-bold text-gray-900 mb-4 flex items-center">
            <FaMapMarkerAlt className="mr-2 text-red-500" />
            Top Locations
          </h3>
          <ResponsiveContainer width="100%" height={250}>
            <BarChart data={locationChartData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="name" />
              <YAxis />
              <Tooltip />
              <Bar dataKey="value" fill="#EF4444" />
            </BarChart>
          </ResponsiveContainer>

          {/* Location List */}
          <div className="mt-4 space-y-2">
            {locationChartData.map((location, index) => (
              <div key={index} className="flex items-center justify-between p-2 bg-gray-50 rounded">
                <div className="flex items-center">
                  <FaGlobe className="text-blue-500 mr-2" />
                  <span className="text-sm font-medium">{location.name}</span>
                </div>
                <span className="text-sm font-bold">{location.value}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Platform/Entry Point Breakdown */}
        <div className="bg-white rounded-xl p-6 shadow-lg">
          <h3 className="text-xl font-bold text-gray-900 mb-4 flex items-center">
            <FaNetworkWired className="mr-2 text-purple-500" />
            Entry Points
          </h3>
          <ResponsiveContainer width="100%" height={250}>
            <PieChart>
              <Pie
                data={platformChartData}
                cx="50%"
                cy="50%"
                labelLine={false}
                label={({ name, percent }) => `${name}: ${(percent * 100).toFixed(0)}%`}
                outerRadius={80}
                fill="#8884d8"
                dataKey="value"
              >
                {platformChartData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>

          {/* Platform List */}
          <div className="mt-4 space-y-2">
            {platformChartData.map((platform, index) => (
              <div key={index} className="flex items-center justify-between p-2 bg-gray-50 rounded">
                <span className="text-sm font-medium">{platform.name}</span>
                <span className="text-sm font-bold">{platform.value}</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Login History */}
      {user.loginHistory && user.loginHistory.length > 0 && (
        <div className="bg-white rounded-xl p-6 shadow-lg">
          <h3 className="text-xl font-bold text-gray-900 mb-4 flex items-center">
            <FaHistory className="mr-2 text-blue-500" />
            Recent Login History
          </h3>
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
              <thead className="bg-gray-50">
                <tr>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Time
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Device
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Browser
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Location
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    IP Address
                  </th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-200">
                {user.loginHistory.slice(0, 10).map((login, index) => (
                  <tr key={index} className="hover:bg-gray-50">
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                      {format(new Date(login.timestamp), 'MMM d, HH:mm')}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                      {login.deviceInfo?.device || 'Unknown'}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                      {login.deviceInfo?.browser || 'Unknown'}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                      {login.location?.city ? `${login.location.city}, ${login.location.country}` : 'Unknown'}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      {login.ipAddress || 'N/A'}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Recent Sessions */}
      <div className="bg-white rounded-xl p-6 shadow-lg">
        <h3 className="text-xl font-bold text-gray-900 mb-4 flex items-center">
          <FaClock className="mr-2 text-purple-500" />
          Recent Activity Sessions
        </h3>
        <div className="space-y-4">
          {data?.slice(0, 10).map((session, index) => (
            <div key={index} className="border border-gray-200 rounded-lg p-4 hover:bg-gray-50 transition-colors">
              <div className="flex items-center justify-between mb-2">
                <div className="flex items-center space-x-3">
                  {session.device?.type === 'mobile' && <FaMobile className="text-blue-500" />}
                  {session.device?.type === 'desktop' && <FaDesktop className="text-green-500" />}
                  {session.device?.type === 'tablet' && <FaTablet className="text-purple-500" />}
                  <div>
                    <p className="text-sm font-medium text-gray-900">
                      {session.device?.browser} on {session.device?.os}
                    </p>
                    <p className="text-xs text-gray-500">
                      {session.session?.startTime && format(new Date(session.session.startTime), 'MMM d, HH:mm:ss')}
                    </p>
                  </div>
                </div>
                <span className={`px-3 py-1 rounded-full text-xs font-medium ${
                  session.session?.sessionQuality === 'excellent' ? 'bg-green-100 text-green-800' :
                  session.session?.sessionQuality === 'good' ? 'bg-blue-100 text-blue-800' :
                  session.session?.sessionQuality === 'fair' ? 'bg-yellow-100 text-yellow-800' :
                  'bg-red-100 text-red-800'
                }`}>
                  {session.session?.sessionQuality || 'unknown'}
                </span>
              </div>

              <div className="grid grid-cols-4 gap-4 mt-3">
                <div>
                  <p className="text-xs text-gray-500">Duration</p>
                  <p className="text-sm font-semibold text-gray-900">{Math.round(session.session?.duration || 0)}s</p>
                </div>
                <div>
                  <p className="text-xs text-gray-500">Attention</p>
                  <p className="text-sm font-semibold text-gray-900">{session.engagement?.attentionScore || 0}/100</p>
                </div>
                <div>
                  <p className="text-xs text-gray-500">Scroll Depth</p>
                  <p className="text-sm font-semibold text-gray-900">{session.engagement?.maxScrollDepth || 0}%</p>
                </div>
                <div>
                  <p className="text-xs text-gray-500">Location</p>
                  <p className="text-sm font-semibold text-gray-900">
                    {session.location?.address?.city || session.location?.ipInfo?.city || 'Unknown'}
                  </p>
                </div>
              </div>

              {session.ai && (
                <div className="mt-3 flex items-center space-x-4 text-xs text-gray-600">
                  <div className="flex items-center">
                    <FaBrain className="mr-1 text-purple-500" />
                    <span>Intent: <strong>{session.ai.userIntent}</strong></span>
                  </div>
                  <div className="flex items-center">
                    <FaChartBar className="mr-1 text-blue-500" />
                    <span>Engagement: <strong>{session.ai.engagementLevel}</strong></span>
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default UserTrackingProfile;

