import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import { API_URL } from '../utils/constants';
import { getSocket } from '../utils/socket';
import { MapContainer, TileLayer, Marker, Popup, Polyline, useMap } from 'react-leaflet';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import { formatDistanceToNow } from 'date-fns';

// Fix for default marker icons in React Leaflet
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: require('leaflet/dist/images/marker-icon-2x.png'),
  iconUrl: require('leaflet/dist/images/marker-icon.png'),
  shadowUrl: require('leaflet/dist/images/marker-shadow.png'),
});

const HubAndSpokeMap = ({ postId }) => {
  const [hubData, setHubData] = useState(null);
  const [spokes, setSpokes] = useState([]);
  const [selectedSpoke, setSelectedSpoke] = useState(null);
  const [colorBy, setColorBy] = useState('platform'); // platform, deviceType
  const [isLoading, setIsLoading] = useState(true);
  const [mapCenter, setMapCenter] = useState([20.5937, 78.9629]); // India center as default
  const [zoomLevel, setZoomLevel] = useState(5);

  useEffect(() => {
    loadHubAndSpokeData();

    // Socket.IO real-time updates
    const socket = getSocket();
    socket.emit('join_post_room', postId);

    socket.on('referral_update', (data) => {
      if (data.postId === postId) {
        // Add new spoke
        const newSpoke = {
          id: data.chainNode.id,
          userId: data.chainNode.userId,
          username: data.chainNode.username,
          avatar: data.chainNode.avatar,
          coordinates: data.chainNode.location?.coordinates || { lat: 0, lng: 0 },
          platform: data.chainNode.platform,
          deviceType: data.chainNode.deviceType,
          browser: data.chainNode.browser,
          city: data.chainNode.location?.city,
          country: data.chainNode.location?.country,
          timestamp: data.chainNode.timestamp,
          chainDepth: data.chainNode.chainDepth,
          type: 'spoke'
        };

        setSpokes(prev => [...prev, newSpoke]);
      }
    });

    return () => {
      socket.off('referral_update');
      socket.emit('leave_post_room', postId);
    };
  }, [postId]);

  const loadHubAndSpokeData = async () => {
    try {
      setIsLoading(true);
      const response = await axios.get(`${API_URL}/referral-tracking/hub-and-spoke/${postId}`);
      if (response.data.success) {
        setHubData(response.data.hub);
        setSpokes(response.data.spokes);

        // Set map center to hub location
        if (response.data.hub?.coordinates) {
          setMapCenter([response.data.hub.coordinates.lat, response.data.hub.coordinates.lng]);
          setZoomLevel(4);
        }
      }
    } catch (error) {
      console.error('Error loading hub-and-spoke data:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const getColorByPlatform = (platform) => {
    const colors = {
      whatsapp: '#25D366',
      linkedin: '#0077B5',
      twitter: '#1DA1F2',
      facebook: '#1877F2',
      instagram: '#E4405F',
      telegram: '#0088CC',
      email: '#EA4335',
      sms: '#34A853',
      direct: '#9333EA',
      other: '#6B7280'
    };
    return colors[platform] || '#6B7280';
  };

  const getColorByDeviceType = (deviceType) => {
    const colors = {
      mobile: '#10B981',
      tablet: '#F59E0B',
      desktop: '#3B82F6',
      unknown: '#6B7280'
    };
    return colors[deviceType] || '#6B7280';
  };

  const getColor = (spoke) => {
    if (colorBy === 'platform') {
      return getColorByPlatform(spoke.platform);
    } else {
      return getColorByDeviceType(spoke.deviceType);
    }
  };

  const createCustomIcon = (color, isHub = false) => {
    return L.divIcon({
      className: 'custom-marker',
      html: `
        <div style="
          width: ${isHub ? '40px' : '30px'};
          height: ${isHub ? '40px' : '30px'};
          background-color: ${color};
          border: 3px solid white;
          border-radius: 50%;
          box-shadow: 0 2px 8px rgba(0,0,0,0.3);
          display: flex;
          align-items: center;
          justify-content: center;
          font-size: ${isHub ? '20px' : '16px'};
        ">
          ${isHub ? '🎯' : '📍'}
        </div>
      `,
      iconSize: [isHub ? 40 : 30, isHub ? 40 : 30],
      iconAnchor: [isHub ? 20 : 15, isHub ? 20 : 15]
    });
  };

  const MapUpdater = () => {
    const map = useMap();
    useEffect(() => {
      if (hubData?.coordinates) {
        map.setView([hubData.coordinates.lat, hubData.coordinates.lng], zoomLevel);
      }
    }, [hubData, zoomLevel, map]);
    return null;
  };

  const handleSpokeClick = (spoke) => {
    setSelectedSpoke(spoke);
    setMapCenter([spoke.coordinates.lat, spoke.coordinates.lng]);
    setZoomLevel(8);
  };

  return (
    <div className="bg-white rounded-lg shadow-lg overflow-hidden">
      {/* Header */}
      <div className="bg-gradient-to-r from-blue-600 to-purple-600 p-6 text-white">
        <h2 className="text-2xl font-bold mb-2">Hub-and-Spoke Referral Map</h2>
        <p className="text-blue-100">Interactive visualization of referral network geography</p>
      </div>

      {/* Controls */}
      <div className="p-4 bg-gray-50 border-b">
        <div className="flex flex-wrap items-center gap-4">
          <div className="flex items-center gap-2">
            <span className="text-sm font-medium text-gray-700">Color By:</span>
            <div className="flex gap-2">
              <button
                onClick={() => setColorBy('platform')}
                className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                  colorBy === 'platform'
                    ? 'bg-blue-600 text-white'
                    : 'bg-white text-gray-700 border border-gray-300 hover:bg-gray-50'
                }`}
              >
                Platform
              </button>
              <button
                onClick={() => setColorBy('deviceType')}
                className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                  colorBy === 'deviceType'
                    ? 'bg-blue-600 text-white'
                    : 'bg-white text-gray-700 border border-gray-300 hover:bg-gray-50'
                }`}
              >
                Device Type
              </button>
            </div>
          </div>

          <div className="flex items-center gap-2 text-sm text-gray-600">
            <span className="font-semibold">{spokes.length}</span>
            <span>Total Referrals</span>
          </div>
        </div>
      </div>

      {/* Map */}
      <div className="relative" style={{ height: '600px' }}>
        {isLoading ? (
          <div className="absolute inset-0 flex items-center justify-center bg-gray-100">
            <div className="text-center">
              <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
              <p className="text-gray-600">Loading map...</p>
            </div>
          </div>
        ) : hubData ? (
          <MapContainer
            center={mapCenter}
            zoom={zoomLevel}
            style={{ height: '100%', width: '100%' }}
            scrollWheelZoom={true}
          >
            <MapUpdater />
            <TileLayer
              attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
              url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
            />

            {/* Hub (Post Creator) Marker */}
            {hubData.coordinates && hubData.coordinates.lat !== 0 && (
              <Marker
                position={[hubData.coordinates.lat, hubData.coordinates.lng]}
                icon={createCustomIcon('#FF6B6B', true)}
              >
                <Popup>
                  <div className="p-2">
                    <div className="flex items-center gap-2 mb-2">
                      {hubData.avatar && (
                        <img
                          src={hubData.avatar}
                          alt={hubData.username}
                          className="w-10 h-10 rounded-full"
                        />
                      )}
                      <div>
                        <h3 className="font-bold text-gray-900">🎯 Hub (Creator)</h3>
                        <p className="text-sm text-gray-600">{hubData.username}</p>
                      </div>
                    </div>
                    <p className="text-xs text-gray-500 font-semibold">{hubData.postTitle}</p>
                  </div>
                </Popup>
              </Marker>
            )}

            {/* Spokes (Referrals) */}
            {spokes.map((spoke) => {
              if (!spoke.coordinates || spoke.coordinates.lat === 0) return null;

              const color = getColor(spoke);

              return (
                <React.Fragment key={spoke.id}>
                  {/* Line from hub to spoke */}
                  {hubData.coordinates && hubData.coordinates.lat !== 0 && (
                    <Polyline
                      positions={[
                        [hubData.coordinates.lat, hubData.coordinates.lng],
                        [spoke.coordinates.lat, spoke.coordinates.lng]
                      ]}
                      color={color}
                      weight={2}
                      opacity={selectedSpoke?.id === spoke.id ? 1 : 0.5}
                      dashArray={selectedSpoke?.id === spoke.id ? null : '5, 10'}
                    />
                  )}

                  {/* Spoke marker */}
                  <Marker
                    position={[spoke.coordinates.lat, spoke.coordinates.lng]}
                    icon={createCustomIcon(color, false)}
                    eventHandlers={{
                      click: () => handleSpokeClick(spoke)
                    }}
                  >
                    <Popup>
                      <div className="p-2 min-w-[200px]">
                        <div className="flex items-center gap-2 mb-2">
                          {spoke.avatar && (
                            <img
                              src={spoke.avatar}
                              alt={spoke.username}
                              className="w-8 h-8 rounded-full"
                            />
                          )}
                          <div className="flex-1">
                            <h4 className="font-semibold text-gray-900">{spoke.username}</h4>
                            <p className="text-xs text-gray-500">
                              {formatDistanceToNow(new Date(spoke.timestamp), { addSuffix: true })}
                            </p>
                          </div>
                        </div>

                        <div className="space-y-1 text-xs">
                          <div className="flex items-center gap-2">
                            <span className="font-semibold">Platform:</span>
                            <span className="capitalize">{spoke.platform}</span>
                          </div>
                          <div className="flex items-center gap-2">
                            <span className="font-semibold">Device:</span>
                            <span className="capitalize">{spoke.deviceType}</span>
                          </div>
                          {spoke.browser && (
                            <div className="flex items-center gap-2">
                              <span className="font-semibold">Browser:</span>
                              <span>{spoke.browser}</span>
                            </div>
                          )}
                          {spoke.city && (
                            <div className="flex items-center gap-2">
                              <span className="font-semibold">Location:</span>
                              <span>{spoke.city}, {spoke.country}</span>
                            </div>
                          )}
                          <div className="flex items-center gap-2">
                            <span className="font-semibold">Chain Depth:</span>
                            <span>{spoke.chainDepth}</span>
                          </div>
                        </div>
                      </div>
                    </Popup>
                  </Marker>
                </React.Fragment>
              );
            })}
          </MapContainer>
        ) : (
          <div className="absolute inset-0 flex items-center justify-center bg-gray-100">
            <p className="text-gray-600">No referral data available</p>
          </div>
        )}
      </div>

      {/* Legend */}
      <div className="p-4 bg-gray-50 border-t">
        <h3 className="text-sm font-semibold text-gray-700 mb-3">Legend</h3>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          {colorBy === 'platform' ? (
            <>
              <div className="flex items-center gap-2">
                <div className="w-4 h-4 rounded-full" style={{ backgroundColor: '#25D366' }}></div>
                <span className="text-xs text-gray-600">WhatsApp</span>
              </div>
              <div className="flex items-center gap-2">
                <div className="w-4 h-4 rounded-full" style={{ backgroundColor: '#0077B5' }}></div>
                <span className="text-xs text-gray-600">LinkedIn</span>
              </div>
              <div className="flex items-center gap-2">
                <div className="w-4 h-4 rounded-full" style={{ backgroundColor: '#1DA1F2' }}></div>
                <span className="text-xs text-gray-600">Twitter</span>
              </div>
              <div className="flex items-center gap-2">
                <div className="w-4 h-4 rounded-full" style={{ backgroundColor: '#1877F2' }}></div>
                <span className="text-xs text-gray-600">Facebook</span>
              </div>
              <div className="flex items-center gap-2">
                <div className="w-4 h-4 rounded-full" style={{ backgroundColor: '#9333EA' }}></div>
                <span className="text-xs text-gray-600">Direct</span>
              </div>
            </>
          ) : (
            <>
              <div className="flex items-center gap-2">
                <div className="w-4 h-4 rounded-full" style={{ backgroundColor: '#10B981' }}></div>
                <span className="text-xs text-gray-600">Mobile</span>
              </div>
              <div className="flex items-center gap-2">
                <div className="w-4 h-4 rounded-full" style={{ backgroundColor: '#F59E0B' }}></div>
                <span className="text-xs text-gray-600">Tablet</span>
              </div>
              <div className="flex items-center gap-2">
                <div className="w-4 h-4 rounded-full" style={{ backgroundColor: '#3B82F6' }}></div>
                <span className="text-xs text-gray-600">Desktop</span>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default HubAndSpokeMap;

