import { API_BASE_URL } from './constants';

class ReferralTracker {
  constructor() {
    this.sessionId = this.generateSessionId();
    this.startTime = Date.now();
    this.scrollDepth = 0;
    this.maxScrollDepth = 0;
    this.interactions = [];
  }

  generateSessionId() {
    return `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  // Detect device type
  detectDevice() {
    const userAgent = navigator.userAgent;
    if (/Android|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(userAgent)) {
      return 'mobile';
    } else if (/iPad|Android.*Tablet/i.test(userAgent)) {
      return 'tablet';
    } else {
      return 'desktop';
    }
  }

  // Detect browser
  detectBrowser() {
    const userAgent = navigator.userAgent;
    if (userAgent.includes('Chrome')) return 'Chrome';
    if (userAgent.includes('Firefox')) return 'Firefox';
    if (userAgent.includes('Safari')) return 'Safari';
    if (userAgent.includes('Edge')) return 'Edge';
    if (userAgent.includes('Brave')) return 'Brave';
    return 'Unknown';
  }

  // Detect platform from referrer
  detectPlatform() {
    const referrer = document.referrer;
    if (referrer.includes('whatsapp')) return 'whatsapp';
    if (referrer.includes('linkedin')) return 'linkedin';
    if (referrer.includes('twitter')) return 'twitter';
    if (referrer.includes('instagram')) return 'instagram';
    if (referrer.includes('facebook')) return 'facebook';
    if (referrer.includes('telegram')) return 'telegram';
    if (referrer.includes('mail')) return 'email';
    return 'web';
  }

  // Get current location
  async getCurrentLocation() {
    return new Promise((resolve) => {
      if (navigator.geolocation) {
        navigator.geolocation.getCurrentPosition(
          (position) => {
            resolve({
              latitude: position.coords.latitude,
              longitude: position.coords.longitude,
              accuracy: position.coords.accuracy
            });
          },
          () => {
            resolve(null);
          }
        );
      } else {
        resolve(null);
      }
    });
  }

  // Get screen size
  getScreenSize() {
    return {
      width: window.screen.width,
      height: window.screen.height
    };
  }

  // Get network info (basic)
  getNetworkInfo() {
    const connection = navigator.connection || navigator.mozConnection || navigator.webkitConnection;
    return {
      isp: 'Unknown',
      connectionType: connection?.effectiveType || 'unknown'
    };
  }

  // Track referral click
  async trackReferralClick(data) {
    try {
      const coordinates = await this.getCurrentLocation();
      
      const trackingData = {
        postId: data.postId,
        referrerId: data.referrerId,
        refereeId: data.refereeId,
        platform: data.platform || this.detectPlatform(),
        device: data.device || this.detectDevice(),
        browser: data.browser || this.detectBrowser(),
        userAgent: navigator.userAgent,
        screenSize: this.getScreenSize(),
        coordinates,
        ipAddress: data.ipAddress,
        networkInfo: this.getNetworkInfo(),
        sessionId: this.sessionId,
        language: navigator.language,
        parentReferralId: data.parentReferralId,
        fromLocation: data.fromLocation,
        toLocation: data.toLocation
      };

      const response = await fetch(`${API_BASE_URL}/referrals/track`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(trackingData)
      });

      if (response.ok) {
        const result = await response.json();
        console.log('Referral tracked:', result);
        return result;
      }
    } catch (error) {
      console.error('Error tracking referral:', error);
    }
  }

  // Track user interactions
  async trackInteraction(data) {
    try {
      const interactionData = {
        postId: data.postId,
        referrerId: data.referrerId,
        interactionType: data.interactionType,
        duration: data.duration,
        scrollDepth: this.maxScrollDepth,
        parentReferralId: data.parentReferralId
      };

      const response = await fetch(`${API_BASE_URL}/referrals/interaction`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(interactionData)
      });

      if (response.ok) {
        const result = await response.json();
        console.log('Interaction tracked:', result);
        return result;
      }
    } catch (error) {
      console.error('Error tracking interaction:', error);
    }
  }

  // Track share action
  async trackShare(data) {
    try {
      const coordinates = await this.getCurrentLocation();
      
      const shareData = {
        postId: data.postId,
        referrerId: data.referrerId,
        platform: data.platform || this.detectPlatform(),
        device: data.device || this.detectDevice(),
        browser: data.browser || this.detectBrowser(),
        coordinates,
        parentReferralId: data.parentReferralId
      };

      const response = await fetch(`${API_BASE_URL}/referrals/share`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(shareData)
      });

      if (response.ok) {
        const result = await response.json();
        console.log('Share tracked:', result);
        return result;
      }
    } catch (error) {
      console.error('Error tracking share:', error);
    }
  }

  // Set up scroll tracking
  setupScrollTracking() {
    let ticking = false;
    
    const updateScrollDepth = () => {
      const scrollTop = window.pageYOffset || document.documentElement.scrollTop;
      const docHeight = document.documentElement.scrollHeight - window.innerHeight;
      this.scrollDepth = Math.round((scrollTop / docHeight) * 100);
      this.maxScrollDepth = Math.max(this.maxScrollDepth, this.scrollDepth);
      ticking = false;
    };

    const requestTick = () => {
      if (!ticking) {
        requestAnimationFrame(updateScrollDepth);
        ticking = true;
      }
    };

    window.addEventListener('scroll', requestTick);
  }

  // Set up time tracking
  setupTimeTracking() {
    // Track time spent on page
    const trackTimeSpent = () => {
      const timeSpent = Date.now() - this.startTime;
      this.trackInteraction({
        postId: this.currentPostId,
        referrerId: this.currentReferrerId,
        interactionType: 'view',
        duration: timeSpent,
        parentReferralId: this.currentParentReferralId
      });
    };

    // Track time spent every 30 seconds
    this.timeInterval = setInterval(trackTimeSpent, 30000);

    // Track time spent on page unload
    window.addEventListener('beforeunload', trackTimeSpent);
  }

  // Set up hover tracking
  setupHoverTracking() {
    let hoverStartTime = 0;
    let hoverDuration = 0;

    const trackHoverStart = () => {
      hoverStartTime = Date.now();
    };

    const trackHoverEnd = () => {
      if (hoverStartTime > 0) {
        hoverDuration = Date.now() - hoverStartTime;
        this.trackInteraction({
          postId: this.currentPostId,
          referrerId: this.currentReferrerId,
          interactionType: 'hover',
          duration: hoverDuration,
          parentReferralId: this.currentParentReferralId
        });
      }
    };

    // Track hover on post elements
    const postElements = document.querySelectorAll('[data-track-hover]');
    postElements.forEach(element => {
      element.addEventListener('mouseenter', trackHoverStart);
      element.addEventListener('mouseleave', trackHoverEnd);
    });
  }

  // Initialize tracking for a post
  initializeTracking(postId, referrerId, parentReferralId) {
    this.currentPostId = postId;
    this.currentReferrerId = referrerId;
    this.currentParentReferralId = parentReferralId;

    // Set up all tracking
    this.setupScrollTracking();
    this.setupTimeTracking();
    this.setupHoverTracking();

    // Track initial view
    this.trackInteraction({
      postId,
      referrerId,
      interactionType: 'view',
      duration: 0,
      parentReferralId
    });
  }

  // Clean up tracking
  cleanup() {
    if (this.timeInterval) {
      clearInterval(this.timeInterval);
    }
    window.removeEventListener('beforeunload', this.trackTimeSpent);
  }
}

// Create global tracker instance
const tracker = new ReferralTracker();

// Export the initializeTracking function
export const initializeTracking = (postId, referrerId, parentReferralId) => {
  return tracker.initializeTracking(postId, referrerId, parentReferralId);
};

// Export trackEngagement function
export const trackEngagement = (data) => {
  return tracker.trackInteraction(data);
};

// Export trackShare function
export const trackShare = (data) => {
  return tracker.trackShare(data);
};

// Export trackConversion function
export const trackConversion = (data) => {
  return tracker.trackReferralClick(data);
};

export default tracker;