class PushNotificationService {
  constructor() {
    this.registration = null;
    this.isSupported = 'serviceWorker' in navigator && 'PushManager' in window;
  }

  // Initialize push notifications
  async initialize(userId) {
    return this.init().then(success => {
      if (success && userId) {
        return this.subscribe(userId);
      }
      return success;
    });
  }

  // Initialize push notifications (legacy method)
  async init() {
    if (!this.isSupported) {
      console.log('Push notifications not supported');
      return false;
    }

    try {
      // TEMPORARILY DISABLE SW REGISTRATION - Enable after frontend redeploy
      console.log('🔍 DEBUG: Service Worker registration temporarily disabled');
      console.log('🔍 DEBUG: Will be enabled after frontend redeployment with sw.js');
      return true; // Return success to prevent errors

      // Register service worker
      console.log('🔍 DEBUG: Attempting to register service worker at /sw.js');
      this.registration = await navigator.serviceWorker.register('/sw.js');
      console.log('🔍 DEBUG: Service Worker registered successfully');
      console.log('🔍 DEBUG: SW registration object:', this.registration);

      // Request permission
      const permission = await this.requestPermission();
      if (permission === 'granted') {
        console.log('Push notifications permission granted');
        return true;
      } else {
        console.log('Push notifications permission denied');
        return false;
      }
    } catch (error) {
      console.error('🔍 DEBUG: Error initializing push notifications:', error);
      console.log('🔍 DEBUG: Error name:', error.name);
      console.log('🔍 DEBUG: Error message:', error.message);
      console.log('🔍 DEBUG: SW supported:', this.isSupported);
      return false;
    }
  }

  // Request permission for push notifications
  async requestPermission() {
    try {
      const permission = await Notification.requestPermission();
      return permission;
    } catch (error) {
      console.error('Error requesting notification permission:', error);
      return 'denied';
    }
  }

  // Subscribe to push notifications
  async subscribe(userId) {
    if (!this.registration) {
      throw new Error('Service worker not registered');
    }

    try {
      // Get VAPID key from backend instead of hardcoding
      const res = await fetch('/api/notifications/vapid-public-key');
      if (!res.ok) throw new Error('Failed to fetch VAPID key');
      const { publicKey } = await res.json();
      if (!publicKey) throw new Error('VAPID key missing');

      const subscription = await this.registration.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: this.urlBase64ToUint8Array(publicKey)
      });

      // Send subscription to server
      await this.sendSubscriptionToServer(subscription, userId);

      console.log('Push notification subscription successful');
      return subscription;
    } catch (error) {
      console.error('Error subscribing to push notifications:', error);
      throw error;
    }
  }

  // Send subscription to server
  async sendSubscriptionToServer(subscription, userId) {
    try {
      const response = await fetch('/api/notifications/subscribe', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({
          subscription: subscription,
          userId: userId
        })
      });

      if (!response.ok) {
        throw new Error('Failed to send subscription to server');
      }
    } catch (error) {
      console.error('Error sending subscription to server:', error);
    }
  }

  // Unsubscribe from push notifications
  async unsubscribe() {
    if (!this.registration) return;

    try {
      const subscription = await this.registration.pushManager.getSubscription();
      if (subscription) {
        await subscription.unsubscribe();
        console.log('Push notification unsubscribed');
      }
    } catch (error) {
      console.error('Error unsubscribing from push notifications:', error);
    }
  }

  // Send test notification
  async sendTestNotification() {
    if (!this.registration) return;

    try {
      await this.registration.showNotification('Test Notification', {
        body: 'This is a test push notification!',
        icon: '/favicon.ico',
        badge: '/favicon.ico',
        vibrate: [200, 100, 200],
        data: {
          url: '/',
        },
        actions: [
          {
            action: 'view',
            title: 'View',
          },
          {
            action: 'dismiss',
            title: 'Dismiss',
          }
        ],
        requireInteraction: true,
      });
    } catch (error) {
      console.error('Error sending test notification:', error);
    }
  }

  // Check if notifications are enabled
  isEnabled() {
    return Notification.permission === 'granted';
  }

  // Get current permission status
  getPermissionStatus() {
    return Notification.permission;
  }

  // Utility function to convert VAPID key
  urlBase64ToUint8Array(base64String) {
    const padding = '='.repeat((4 - base64String.length % 4) % 4);
    const base64 = (base64String + padding)
      .replace(/-/g, '+')
      .replace(/_/g, '/');

    const rawData = window.atob(base64);
    const outputArray = new Uint8Array(rawData.length);

    for (let i = 0; i < rawData.length; ++i) {
      outputArray[i] = rawData.charCodeAt(i);
    }
    return outputArray;
  }
}

// Create singleton instance
const pushNotificationService = new PushNotificationService();

export default pushNotificationService;