import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Navbar from '../components/Navbar';
import socket from '../utils/socket';
import { getRandomOnePieceName } from '../utils/onePieceNames';
const AdminDashboard = () => {
  const [activeTab, setActiveTab] = useState('activities');
  const [activities, setActivities] = useState([]);
  const [platformStats, setPlatformStats] = useState(null);
  const [allPosts, setAllPosts] = useState([]);
  const [selectedPost, setSelectedPost] = useState(null);
  const [postAnalytics, setPostAnalytics] = useState(null);
  const [commissionAnalytics, setCommissionAnalytics] = useState(null);
  const [referralAnalytics, setReferralAnalytics] = useState(null);
  const [linkAnalytics, setLinkAnalytics] = useState(null);
  const [trackingEvents, setTrackingEvents] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetchAdminData();
  }, []);

  // Real-time updates
  useEffect(() => {
    const handleRealTimeUpdate = (data) => {
      console.log('Real-time update received:', data);
      // Refresh data when real-time events occur
      fetchAdminData();
    };

    // Join analytics room for global updates
    socket.emit('join_analytics_room');

    // Listen for various real-time events
    socket.on('postCreated', handleRealTimeUpdate);
    socket.on('referral_update', handleRealTimeUpdate);
    socket.on('commission_update', handleRealTimeUpdate);
    socket.on('user_analytics_update', handleRealTimeUpdate);
    socket.on('global_analytics_update', handleRealTimeUpdate);

    return () => {
      socket.off('postCreated', handleRealTimeUpdate);
      socket.off('referral_update', handleRealTimeUpdate);
      socket.off('commission_update', handleRealTimeUpdate);
      socket.off('user_analytics_update', handleRealTimeUpdate);
      socket.off('global_analytics_update', handleRealTimeUpdate);
    };
  }, []);

  const fetchAdminData = async () => {
    try {
      setLoading(true);

      const [activitiesRes, statsRes, postsRes, trackingRes] = await Promise.all([
        axios.get(`${process.env.REACT_APP_API_URL}/admin/activities`),
        axios.get(`${process.env.REACT_APP_API_URL}/admin/platform-stats`),
        axios.get(`${process.env.REACT_APP_API_URL}/posts/debug`), // Get all posts for admin
        axios.get(`${process.env.REACT_APP_API_URL}/admin/tracking-events`)
      ]);

      setActivities(activitiesRes.data.activities || []);
      setPlatformStats(statsRes.data || null);
      setAllPosts(postsRes.data.allPosts || []);
      setTrackingEvents(trackingRes.data || []);
    } catch (err) {
      setError('Failed to load admin data');
      console.error('Admin data fetch error:', err);
    } finally {
      setLoading(false);
    }
  };

  const fetchPostAnalytics = async (postId) => {
    try {
      const res = await axios.get(`${process.env.REACT_APP_API_URL}/analytics/post/${postId}`);
      setPostAnalytics(res.data);
    } catch (err) {
      console.error('Error fetching post analytics:', err);
    }
  };

  const handlePostSelect = (post) => {
    setSelectedPost(post);
    fetchPostAnalytics(post.id);
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-100">
        <Navbar />
        <div className="flex justify-center items-center h-64">
          <div className="text-lg">Loading admin dashboard...</div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-gray-100">
        <Navbar />
        <div className="flex justify-center items-center h-64">
          <div className="text-red-600">{error}</div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-100">
      <Navbar />

      <header className="bg-white shadow">
        <div className="max-w-7xl mx-auto py-6 px-4 sm:px-6 lg:px-8">
          <h1 className="text-3xl font-bold text-gray-900">Admin Dashboard</h1>
          <p className="mt-2 text-gray-600">Monitor platform activities and referral journeys</p>
        </div>
      </header>

      <main className="max-w-7xl mx-auto py-6 sm:px-6 lg:px-8">
        {/* Platform Stats Overview */}
        {platformStats && (
          <div className="mb-8">
            <h2 className="text-2xl font-bold text-gray-900 mb-6">Platform Overview</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              <div className="bg-white overflow-hidden shadow rounded-lg">
                <div className="p-5">
                  <div className="flex items-center">
                    <div className="flex-shrink-0">
                      <div className="w-8 h-8 bg-blue-100 rounded-full flex items-center justify-center">
                        <span className="text-blue-600 text-sm font-semibold">👥</span>
                      </div>
                    </div>
                    <div className="ml-5 w-0 flex-1">
                      <dl>
                        <dt className="text-sm font-medium text-gray-500 truncate">Total Users</dt>
                        <dd className="text-lg font-medium text-gray-900">{platformStats.overview.totalUsers}</dd>
                      </dl>
                    </div>
                  </div>
                </div>
              </div>

              <div className="bg-white overflow-hidden shadow rounded-lg">
                <div className="p-5">
                  <div className="flex items-center">
                    <div className="flex-shrink-0">
                      <div className="w-8 h-8 bg-green-100 rounded-full flex items-center justify-center">
                        <span className="text-green-600 text-sm font-semibold">📄</span>
                      </div>
                    </div>
                    <div className="ml-5 w-0 flex-1">
                      <dl>
                        <dt className="text-sm font-medium text-gray-500 truncate">Total Posts</dt>
                        <dd className="text-lg font-medium text-gray-900">{platformStats.overview.totalPosts}</dd>
                      </dl>
                    </div>
                  </div>
                </div>
              </div>

              <div className="bg-white overflow-hidden shadow rounded-lg">
                <div className="p-5">
                  <div className="flex items-center">
                    <div className="flex-shrink-0">
                      <div className="w-8 h-8 bg-purple-100 rounded-full flex items-center justify-center">
                        <span className="text-purple-600 text-sm font-semibold">🔗</span>
                      </div>
                    </div>
                    <div className="ml-5 w-0 flex-1">
                      <dl>
                        <dt className="text-sm font-medium text-gray-500 truncate">Total Referrals</dt>
                        <dd className="text-lg font-medium text-gray-900">{platformStats.overview.totalReferrals}</dd>
                      </dl>
                    </div>
                  </div>
                </div>
              </div>

              <div className="bg-white overflow-hidden shadow rounded-lg">
                <div className="p-5">
                  <div className="flex items-center">
                    <div className="flex-shrink-0">
                      <div className="w-8 h-8 bg-yellow-100 rounded-full flex items-center justify-center">
                        <span className="text-yellow-600 text-sm font-semibold">💰</span>
                      </div>
                    </div>
                    <div className="ml-5 w-0 flex-1">
                      <dl>
                        <dt className="text-sm font-medium text-gray-500 truncate">Platform Earnings</dt>
                        <dd className="text-lg font-medium text-gray-900">${platformStats.overview.totalPlatformFees || 0}</dd>
                      </dl>
                    </div>
                  </div>
                </div>
              </div>

              <div className="bg-white overflow-hidden shadow rounded-lg">
                <div className="p-5">
                  <div className="flex items-center">
                    <div className="flex-shrink-0">
                      <div className="w-8 h-8 bg-purple-100 rounded-full flex items-center justify-center">
                        <span className="text-purple-600 text-sm font-semibold">📊</span>
                      </div>
                    </div>
                    <div className="ml-5 w-0 flex-1">
                      <dl>
                        <dt className="text-sm font-medium text-gray-500 truncate">Total Commissions</dt>
                        <dd className="text-lg font-medium text-gray-900">{platformStats.overview.totalCommissions || 0}</dd>
                      </dl>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Tab Navigation */}
        <div className="mb-6">
          <nav className="flex space-x-8">
            {[
              { id: 'activities', label: 'All Activities', icon: '📋' },
              { id: 'posts', label: 'Posts Management', icon: '📄' },
              { id: 'journeys', label: 'Referral Journeys', icon: '🗺️' },
              { id: 'commissions', label: 'Commission Analytics', icon: '💰' },
              { id: 'referrals', label: 'Referral Analytics', icon: '📈' },
              { id: 'links', label: 'Link Performance', icon: '🔗' },
              { id: 'tracking', label: 'Tracking Events', icon: '👁️' },
              { id: 'analytics', label: 'Activity Analytics', icon: '📊' }
            ].map((tab) => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`flex items-center px-3 py-2 border-b-2 font-medium text-sm ${
                  activeTab === tab.id
                    ? 'border-indigo-500 text-indigo-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                }`}
              >
                <span className="mr-2">{tab.icon}</span>
                {tab.label}
              </button>
            ))}
          </nav>
        </div>

        {/* Tab Content */}
        <div>
          {/* Posts Management Tab */}
          {activeTab === 'posts' && (
            <div className="space-y-6">
              <div className="bg-white shadow overflow-hidden sm:rounded-md">
                <div className="px-4 py-5 sm:px-6">
                  <h3 className="text-lg leading-6 font-medium text-gray-900">All Posts Management</h3>
                  <p className="mt-1 max-w-2xl text-sm text-gray-500">Complete overview of all posts with detailed analytics</p>
                </div>
                <div className="px-4 py-4">
                  {allPosts.length === 0 ? (
                    <p className="text-center text-gray-500 py-8">No posts found</p>
                  ) : (
                    <div className="space-y-4">
                      {allPosts.map((post) => (
                        <div key={post.id} className="border border-gray-200 rounded-lg p-6 hover:bg-gray-50 transition-colors">
                          <div className="flex justify-between items-start mb-4">
                            <div className="flex-1">
                              <h4 className="text-lg font-semibold text-gray-900 mb-2">{post.title}</h4>
                              <p className="text-sm text-gray-600 mb-2">Created by: <span className="font-medium text-blue-600">{post.creator}</span></p>
                              <p className="text-xs text-gray-500">Created: {new Date(post.createdAt).toLocaleString()}</p>
                            </div>
                            <div className="text-right">
                              <span className={`px-2 py-1 rounded text-xs font-medium ${
                                post.status === 'active' ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-800'
                              }`}>
                                {post.status}
                              </span>
                            </div>
                          </div>

                          {/* Post Analytics */}
                          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-4">
                            <div className="bg-blue-50 p-3 rounded-lg text-center">
                              <div className="text-2xl font-bold text-blue-600">{post.reach || 0}</div>
                              <div className="text-sm text-blue-700">Views</div>
                            </div>
                            <div className="bg-green-50 p-3 rounded-lg text-center">
                              <div className="text-2xl font-bold text-green-600">0</div>
                              <div className="text-sm text-green-700">Clicks</div>
                            </div>
                            <div className="bg-purple-50 p-3 rounded-lg text-center">
                              <div className="text-2xl font-bold text-purple-600">{post.conversions || 0}</div>
                              <div className="text-sm text-purple-700">Conversions</div>
                            </div>
                            <div className="bg-yellow-50 p-3 rounded-lg text-center">
                              <div className="text-2xl font-bold text-yellow-600">
                                {post.reach > 0 ? ((post.conversions || 0) / post.reach * 100).toFixed(1) : 0}%
                              </div>
                              <div className="text-sm text-yellow-700">Conv. Rate</div>
                            </div>
                          </div>

                          {/* Creation Metadata */}
                          {post.creationMetadata && (
                            <div className="mt-4 p-4 bg-gray-50 rounded-lg">
                              <h5 className="text-sm font-medium text-gray-900 mb-3">Creation Details</h5>
                              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm">
                                <div>
                                  <span className="text-gray-600">Platform:</span>
                                  <span className="ml-2 font-medium">{post.creationMetadata.platform}</span>
                                </div>
                                <div>
                                  <span className="text-gray-600">Device:</span>
                                  <span className="ml-2 font-medium">{post.creationMetadata.device}</span>
                                </div>
                                <div>
                                  <span className="text-gray-600">Browser:</span>
                                  <span className="ml-2 font-medium">{post.creationMetadata.browser}</span>
                                </div>
                                <div>
                                  <span className="text-gray-600">IP Address:</span>
                                  <span className="ml-2 font-medium">{post.creationMetadata.ipAddress || 'Unknown'}</span>
                                </div>
                                {post.creationMetadata.coordinates && post.creationMetadata.coordinates.latitude && (
                                  <div>
                                    <span className="text-gray-600">Coordinates:</span>
                                    <span className="ml-2 font-medium">
                                      {post.creationMetadata.coordinates.latitude.toFixed(4)}, {post.creationMetadata.coordinates.longitude.toFixed(4)}
                                    </span>
                                  </div>
                                )}
                                {post.creationMetadata.screenSize && post.creationMetadata.screenSize.width && (
                                  <div>
                                    <span className="text-gray-600">Screen Size:</span>
                                    <span className="ml-2 font-medium">
                                      {post.creationMetadata.screenSize.width} x {post.creationMetadata.screenSize.height}
                                    </span>
                                  </div>
                                )}
                                <div>
                                  <span className="text-gray-600">Timezone:</span>
                                  <span className="ml-2 font-medium">{post.creationMetadata.timezone || 'Unknown'}</span>
                                </div>
                                <div>
                                  <span className="text-gray-600">Language:</span>
                                  <span className="ml-2 font-medium">{post.creationMetadata.language || 'Unknown'}</span>
                                </div>
                              </div>
                            </div>
                          )}

                          {/* Action Buttons */}
                          <div className="flex space-x-2 mt-4">
                            <button
                              onClick={() => handlePostSelect(post)}
                              className="bg-indigo-600 text-white px-4 py-2 rounded-md text-sm hover:bg-indigo-700"
                            >
                              View Analytics
                            </button>
                            <button
                              onClick={() => window.open(`https://referral-hub-frontend.vercel.app/post/${post.id}`, '_blank')}
                              className="bg-green-600 text-white px-4 py-2 rounded-md text-sm hover:bg-green-700"
                            >
                              View Post
                            </button>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              </div>

              {/* Selected Post Analytics */}
              {selectedPost && postAnalytics && (
                <div className="bg-white shadow overflow-hidden sm:rounded-md">
                  <div className="px-4 py-5 sm:px-6">
                    <h3 className="text-lg leading-6 font-medium text-gray-900">Detailed Analytics: {selectedPost.title}</h3>
                    <p className="mt-1 max-w-2xl text-sm text-gray-500">Comprehensive analytics for this post</p>
                  </div>
                  <div className="px-4 py-4">
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-6">
                      <div className="bg-blue-50 p-4 rounded-lg text-center">
                        <div className="text-3xl font-bold text-blue-600">{postAnalytics.totalClicks}</div>
                        <div className="text-sm text-blue-700">Total Clicks</div>
                      </div>
                      <div className="bg-green-50 p-4 rounded-lg text-center">
                        <div className="text-3xl font-bold text-green-600">{postAnalytics.totalConversions}</div>
                        <div className="text-sm text-green-700">Total Conversions</div>
                      </div>
                      <div className="bg-purple-50 p-4 rounded-lg text-center">
                        <div className="text-3xl font-bold text-purple-600">
                          {postAnalytics.totalClicks > 0 ? ((postAnalytics.totalConversions / postAnalytics.totalClicks) * 100).toFixed(1) : 0}%
                        </div>
                        <div className="text-sm text-purple-700">Conversion Rate</div>
                      </div>
                      <div className="bg-yellow-50 p-4 rounded-lg text-center">
                        <div className="text-3xl font-bold text-yellow-600">{postAnalytics.referrals?.length || 0}</div>
                        <div className="text-sm text-yellow-700">Total Referrals</div>
                      </div>
                    </div>

                    {/* Platform Distribution */}
                    <div className="mb-6">
                      <h4 className="text-md font-medium text-gray-900 mb-3">Platform Distribution</h4>
                      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                        {Object.entries(postAnalytics.platformStats || {}).map(([platform, count]) => (
                          <div key={platform} className="bg-gray-50 p-3 rounded-lg text-center">
                            <div className="text-lg font-semibold text-gray-900">{count}</div>
                            <div className="text-sm text-gray-600 capitalize">{platform}</div>
                          </div>
                        ))}
                      </div>
                    </div>

                    {/* Geographic Distribution */}
                    <div className="mb-6">
                      <h4 className="text-md font-medium text-gray-900 mb-3">Geographic Distribution</h4>
                      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                        {Object.entries(postAnalytics.geoStats || {}).map(([location, count]) => (
                          <div key={location} className="bg-gray-50 p-3 rounded-lg text-center">
                            <div className="text-lg font-semibold text-gray-900">{count}</div>
                            <div className="text-sm text-gray-600">{location}</div>
                          </div>
                        ))}
                      </div>
                    </div>

                    {/* Individual Referrals */}
                    <div>
                      <h4 className="text-md font-medium text-gray-900 mb-3">Individual Referrals</h4>
                      <div className="space-y-2">
                        {postAnalytics.referrals?.map((referral, index) => (
                          <div key={referral._id} className="border border-gray-200 rounded-lg p-3">
                            <div className="flex justify-between items-center">
                              <div>
                                <span className="text-sm font-medium text-gray-900">Referral #{index + 1}</span>
                                <span className="text-sm text-gray-600 ml-2">via {referral.platform}</span>
                              </div>
                              <div className="text-sm text-gray-500">
                                {new Date(referral.createdAt).toLocaleString()}
                              </div>
                            </div>
                            <div className="mt-2 text-sm text-gray-600">
                              Location: {referral.location.city}, {referral.location.state}
                            </div>
                          </div>
                        )) || <p className="text-sm text-gray-500">No referrals yet</p>}
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </div>
          )}

          {/* Activities Tab */}
          {activeTab === 'activities' && (
            <div className="space-y-6">
              <div className="bg-white shadow overflow-hidden sm:rounded-md">
                <div className="px-4 py-5 sm:px-6">
                  <h3 className="text-lg leading-6 font-medium text-gray-900">All Platform Activities</h3>
                  <p className="mt-1 max-w-2xl text-sm text-gray-500">Complete activity log of all user actions</p>
                </div>
                <ul className="divide-y divide-gray-200">
                  {activities.length === 0 ? (
                    <li className="px-4 py-4 text-center text-gray-500">No activities found</li>
                  ) : (
                    activities.map((activity) => (
                      <li key={activity._id} className="px-4 py-4">
                        <div className="flex items-center space-x-4">
                          <div className="flex-shrink-0">
                            <div className={`w-10 h-10 rounded-full flex items-center justify-center ${
                              activity.type === 'user_registration' ? 'bg-green-100' :
                              activity.type === 'post_created' ? 'bg-blue-100' :
                              activity.type === 'referral_shared' ? 'bg-purple-100' :
                              activity.type === 'commission_earned' ? 'bg-yellow-100' :
                              'bg-gray-100'
                            }`}>
                              <span className="text-lg">
                                {activity.type === 'user_registration' ? '👤' :
                                 activity.type === 'post_created' ? '📝' :
                                 activity.type === 'referral_shared' ? '🔗' :
                                 activity.type === 'commission_earned' ? '💰' :
                                 '📢'}
                              </span>
                            </div>
                          </div>
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center justify-between">
                              <p className="text-sm font-medium text-gray-900 truncate">
                                {activity.user?.username || 'Unknown User'}
                              </p>
                              <div className="flex items-center space-x-2">
                                <span className={`px-2 py-1 text-xs rounded-full ${
                                  activity.type === 'user_registration' ? 'bg-green-100 text-green-800' :
                                  activity.type === 'post_created' ? 'bg-blue-100 text-blue-800' :
                                  activity.type === 'referral_shared' ? 'bg-purple-100 text-purple-800' :
                                  activity.type === 'commission_earned' ? 'bg-yellow-100 text-yellow-800' :
                                  'bg-gray-100 text-gray-800'
                                }`}>
                                  {activity.type.replace('_', ' ')}
                                </span>
                                <p className="text-sm text-gray-500">
                                  {new Date(activity.createdAt).toLocaleString()}
                                </p>
                              </div>
                            </div>
                            <p className="text-sm text-gray-600 mt-1">{activity.message}</p>
                            {activity.details && (
                              <div className="mt-2 text-xs text-gray-500">
                                {activity.details.amount && <span>Amount: {activity.details.amount} | </span>}
                                {activity.details.platform && <span>Platform: {activity.details.platform} | </span>}
                                {activity.details.level !== undefined && <span>Level: {activity.details.level}</span>}
                              </div>
                            )}
                          </div>
                        </div>
                      </li>
                    ))
                  )}
                </ul>
              </div>
            </div>
          )}

          {/* Referral Journeys Tab */}
          {activeTab === 'journeys' && (
            <div className="space-y-6">
              {!selectedPost ? (
                // Post Selection View
                <div className="bg-white shadow overflow-hidden sm:rounded-md">
                  <div className="px-4 py-5 sm:px-6">
                    <h3 className="text-lg leading-6 font-medium text-gray-900">Referral Journey Map</h3>
                    <p className="mt-1 max-w-2xl text-sm text-gray-500">Track how your referrals spread across locations and platforms</p>
                  </div>
                  <div className="px-4 py-4">
                    <div className="mb-6">
                      <h4 className="text-md font-medium text-gray-900 mb-4">Select Post to View Journey</h4>
                      <p className="text-sm text-gray-600 mb-4">Choose a post from below to view its referral journey map and detailed analytics.</p>

                      {allPosts.length === 0 ? (
                        <p className="text-center text-gray-500 py-8">No posts available</p>
                      ) : (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                          {allPosts.map((post) => (
                            <div
                              key={post.id}
                              onClick={() => handlePostSelect(post)}
                              className="border border-gray-200 rounded-lg p-4 cursor-pointer hover:bg-gray-50 hover:border-indigo-300 transition-colors"
                            >
                              <h5 className="font-medium text-gray-900 mb-2">{post.title}</h5>
                              <p className="text-sm text-gray-600 mb-2">by {post.creator}</p>
                              <div className="flex justify-between text-xs text-gray-500">
                                <span>Status: {post.status}</span>
                                <span>{new Date(post.createdAt).toLocaleDateString()}</span>
                              </div>
                              <div className="mt-3 text-center">
                                <span className="bg-indigo-100 text-indigo-800 text-xs px-2 py-1 rounded">
                                  Click to View Journey
                                </span>
                              </div>
                            </div>
                          ))}
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              ) : (
                // Detailed Journey View
                <div className="space-y-6">
                  {/* Back Button and Post Info */}
                  <div className="bg-white shadow overflow-hidden sm:rounded-md">
                    <div className="px-4 py-5 sm:px-6">
                      <div className="flex items-center justify-between">
                        <button
                          onClick={() => setSelectedPost(null)}
                          className="text-indigo-600 hover:text-indigo-800 text-sm font-medium flex items-center"
                        >
                          ← Back to Post Selection
                        </button>
                        <div className="text-right">
                          <h3 className="text-lg font-medium text-gray-900">{selectedPost.title}</h3>
                          <p className="text-sm text-gray-600">Referral Journey Details</p>
                        </div>
                      </div>
                    </div>
                  </div>

                  {/* Journey Analytics */}
                  {postAnalytics && (
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                      {/* Journey Summary */}
                      <div className="bg-white shadow overflow-hidden sm:rounded-md">
                        <div className="px-4 py-5 sm:px-6">
                          <h4 className="text-md font-medium text-gray-900">Journey Summary</h4>
                        </div>
                        <div className="px-4 py-4">
                          <div className="grid grid-cols-2 gap-4">
                            <div className="text-center p-4 bg-blue-50 rounded-lg">
                              <div className="text-2xl font-bold text-blue-600">{postAnalytics.totalClicks}</div>
                              <div className="text-sm text-blue-700">Total Clicks</div>
                            </div>
                            <div className="text-center p-4 bg-green-50 rounded-lg">
                              <div className="text-2xl font-bold text-green-600">{postAnalytics.totalConversions}</div>
                              <div className="text-sm text-green-700">Conversions</div>
                            </div>
                          </div>
                        </div>
                      </div>

                      {/* Platform Distribution */}
                      <div className="bg-white shadow overflow-hidden sm:rounded-md">
                        <div className="px-4 py-5 sm:px-6">
                          <h4 className="text-md font-medium text-gray-900">Platform Distribution</h4>
                        </div>
                        <div className="px-4 py-4">
                          <div className="space-y-3">
                            {Object.entries(postAnalytics.platformStats || {}).map(([platform, count]) => (
                              <div key={platform} className="flex justify-between items-center p-3 bg-gray-50 rounded-lg">
                                <span className="font-medium capitalize">{platform}</span>
                                <span className="text-gray-600 font-semibold">{count} clicks</span>
                              </div>
                            ))}
                          </div>
                        </div>
                      </div>
                    </div>
                  )}

                  {/* Referral Chain Visualization */}
                  <div className="bg-white shadow overflow-hidden sm:rounded-md">
                    <div className="px-4 py-5 sm:px-6">
                      <h4 className="text-md font-medium text-gray-900">Referral Chain</h4>
                      <p className="text-sm text-gray-600">Visual representation of the referral network</p>
                    </div>
                    <div className="px-4 py-4">
                      {postAnalytics && postAnalytics.referrals?.length > 0 ? (
                        <div className="relative">
                          {/* SVG Chain Visualization */}
                          <svg className="w-full h-32 mb-6" viewBox="0 0 800 100">
                            <defs>
                              <marker id="arrowhead" markerWidth="10" markerHeight="7"
                                refX="9" refY="3.5" orient="auto">
                                <polygon points="0 0, 10 3.5, 0 7" fill="#6b7280" />
                              </marker>
                            </defs>

                            {/* Original Post */}
                            <circle cx="50" cy="50" r="20" fill="#3b82f6" />
                            <text x="50" y="56" textAnchor="middle" fill="white" fontSize="12" fontWeight="bold">Post</text>

                            {/* Referral Chain */}
                            {postAnalytics.referrals.map((ref, index) => {
                              const x = 150 + (index * 150);
                              return (
                                <g key={ref._id}>
                                  {/* Arrow */}
                                  <line x1={index === 0 ? "70" : (150 + ((index-1) * 150) + 30)} y1="50"
                                        x2={x - 30} y2="50" stroke="#6b7280" strokeWidth="2"
                                        markerEnd="url(#arrowhead)" />

                                  {/* Referral Node */}
                                  <circle cx={x} cy="50" r="20" fill="#10b981" />
                                  <text x={x} y="56" textAnchor="middle" fill="white" fontSize="10" fontWeight="bold">
                                    {index + 1}
                                  </text>
                                </g>
                              );
                            })}
                          </svg>

                          {/* Referral Details */}
                          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                            {postAnalytics.referrals.map((ref, index) => (
                              <div key={ref._id} className="border border-gray-200 rounded-lg p-3">
                                <div className="flex items-center space-x-2 mb-2">
                                  <div className="w-6 h-6 bg-green-100 rounded-full flex items-center justify-center">
                                    <span className="text-green-600 font-semibold text-xs">{index + 1}</span>
                                  </div>
                                  <span className="text-sm font-medium text-gray-900">Level {index + 1} Referral</span>
                                </div>
                                <div className="text-xs text-gray-600 space-y-1">
                                  <div>Platform: {ref.platform}</div>
                                  <div>Location: {ref.location.city}, {ref.location.state}</div>
                                  <div>Time: {new Date(ref.createdAt).toLocaleString()}</div>
                                </div>
                              </div>
                            ))}
                          </div>
                        </div>
                      ) : (
                        <div className="text-center py-8">
                          <p className="text-gray-500">No referrals yet for this post</p>
                          <p className="text-sm text-gray-400 mt-2">Share the post to start building your referral network!</p>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              )}
            </div>
          )}

          {/* Commissions Tab */}
          {activeTab === 'commissions' && (
            <div className="space-y-6">
              <div className="bg-white shadow overflow-hidden sm:rounded-md">
                <div className="px-4 py-5 sm:px-6">
                  <h3 className="text-lg leading-6 font-medium text-gray-900">Commission Distribution Analytics</h3>
                  <p className="mt-1 max-w-2xl text-sm text-gray-500">Detailed breakdown of all commission distributions and earnings</p>
                </div>
                <div className="px-4 py-4">
                  {!commissionAnalytics ? (
                    <div className="text-center py-8">
                      <button
                        onClick={async () => {
                          try {
                            const res = await axios.get(`${process.env.REACT_APP_API_URL}/admin/commission-analytics`);
                            setCommissionAnalytics(res.data);
                          } catch (err) {
                            console.error('Error fetching commission analytics:', err);
                          }
                        }}
                        className="bg-indigo-600 text-white px-6 py-2 rounded-md hover:bg-indigo-700"
                      >
                        Load Commission Analytics
                      </button>
                    </div>
                  ) : (
                    <div className="space-y-6">
                      {/* Summary Stats */}
                      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        <div className="bg-green-50 p-4 rounded-lg text-center">
                          <div className="text-2xl font-bold text-green-600">{commissionAnalytics.summary.totalDistributed.toLocaleString()}</div>
                          <div className="text-sm text-green-700">Total Points Distributed</div>
                        </div>
                        <div className="bg-red-50 p-4 rounded-lg text-center">
                          <div className="text-2xl font-bold text-red-600">{commissionAnalytics.summary.totalPlatformFees.toLocaleString()}</div>
                          <div className="text-sm text-red-700">Platform Fees Collected</div>
                        </div>
                        <div className="bg-blue-50 p-4 rounded-lg text-center">
                          <div className="text-2xl font-bold text-blue-600">{commissionAnalytics.summary.totalCommissions}</div>
                          <div className="text-sm text-blue-700">Total Commissions</div>
                        </div>
                      </div>

                      {/* Commission List */}
                      <div className="space-y-4">
                        <h4 className="text-md font-medium text-gray-900">Recent Commissions</h4>
                        {commissionAnalytics.commissions.map((commission) => (
                          <div key={commission._id} className="border border-gray-200 rounded-lg p-4">
                            <div className="flex justify-between items-start mb-3">
                              <div>
                                <h5 className="font-medium text-gray-900">{commission.post.title}</h5>
                                <p className="text-sm text-gray-600">
                                  {commission.distributionType.replace('_', ' ').toUpperCase()} •
                                  {commission.recipient ? ` ${commission.recipient.username}` : ' Platform Fee'}
                                </p>
                              </div>
                              <div className="text-right">
                                <div className="text-lg font-bold text-green-600">{commission.amount} points</div>
                                <div className="text-sm text-gray-500">{commission.percentage}%</div>
                              </div>
                            </div>
                            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
                              <div>
                                <span className="text-gray-600">Chain Position:</span>
                                <p className="font-medium">{commission.chainPosition || 'N/A'}</p>
                              </div>
                              <div>
                                <span className="text-gray-600">Points Pool:</span>
                                <p className="font-medium">{commission.totalPointsPool}</p>
                              </div>
                              <div>
                                <span className="text-gray-600">Platform Fee:</span>
                                <p className="font-medium">{commission.platformFee}</p>
                              </div>
                              <div>
                                <span className="text-gray-600">Date:</span>
                                <p className="font-medium">{new Date(commission.createdAt).toLocaleDateString()}</p>
                              </div>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          {/* Referral Analytics Tab */}
          {activeTab === 'referrals' && (
            <div className="space-y-6">
              <div className="bg-white shadow overflow-hidden sm:rounded-md">
                <div className="px-4 py-5 sm:px-6">
                  <h3 className="text-lg leading-6 font-medium text-gray-900">Detailed Referral Analytics</h3>
                  <p className="mt-1 max-w-2xl text-sm text-gray-500">Comprehensive tracking of referral interactions across all platforms</p>
                </div>
                <div className="px-4 py-4">
                  {!referralAnalytics ? (
                    <div className="text-center py-8">
                      <button
                        onClick={async () => {
                          try {
                            const res = await axios.get(`${process.env.REACT_APP_API_URL}/admin/referral-analytics`);
                            setReferralAnalytics(res.data);
                          } catch (err) {
                            console.error('Error fetching referral analytics:', err);
                          }
                        }}
                        className="bg-indigo-600 text-white px-6 py-2 rounded-md hover:bg-indigo-700"
                      >
                        Load Referral Analytics
                      </button>
                    </div>
                  ) : (
                    <div className="space-y-6">
                      {/* Geographic Distribution */}
                      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                        <div>
                          <h4 className="text-md font-medium text-gray-900 mb-4">Top Locations</h4>
                          <div className="space-y-3">
                            {referralAnalytics.geoStats.slice(0, 10).map((location, index) => (
                              <div key={index} className="flex justify-between items-center p-3 bg-gray-50 rounded-lg">
                                <span className="font-medium">{location._id.city}, {location._id.state}</span>
                                <span className="text-gray-600 font-semibold">{location.count} referrals</span>
                              </div>
                            ))}
                          </div>
                        </div>

                        <div>
                          <h4 className="text-md font-medium text-gray-900 mb-4">Time Distribution</h4>
                          <div className="space-y-3">
                            {referralAnalytics.timeStats.map((timeSlot) => (
                              <div key={timeSlot.hour} className="flex justify-between items-center p-3 bg-blue-50 rounded-lg">
                                <span className="font-medium">{timeSlot.hour}:00</span>
                                <span className="text-blue-600 font-semibold">{timeSlot.count} referrals</span>
                              </div>
                            ))}
                          </div>
                        </div>
                      </div>

                      {/* Recent Referrals */}
                      <div>
                        <h4 className="text-md font-medium text-gray-900 mb-4">Recent Referral Activity</h4>
                        <div className="space-y-4">
                          {referralAnalytics.referrals.slice(0, 20).map((referral) => (
                            <div key={referral._id} className="border border-gray-200 rounded-lg p-4">
                              <div className="flex justify-between items-start mb-3">
                                <div>
                                  <h5 className="font-medium text-gray-900">{referral.post.title}</h5>
                                  <p className="text-sm text-gray-600">
                                    {referral.referrer.username} → {referral.referee?.username || 'Unknown'}
                                  </p>
                                </div>
                                <div className="text-right">
                                  <span className={`px-2 py-1 rounded text-xs font-medium ${
                                    referral.platform === 'whatsapp' ? 'bg-green-100 text-green-800' :
                                    referral.platform === 'linkedin' ? 'bg-blue-100 text-blue-800' :
                                    referral.platform === 'twitter' ? 'bg-blue-100 text-blue-400' :
                                    'bg-gray-100 text-gray-800'
                                  }`}>
                                    {referral.platform}
                                  </span>
                                </div>
                              </div>
                              <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
                                <div>
                                  <span className="text-gray-600">Location:</span>
                                  <p className="font-medium">{referral.location.city}, {referral.location.state}</p>
                                </div>
                                <div>
                                  <span className="text-gray-600">Device:</span>
                                  <p className="font-medium">{referral.device}</p>
                                </div>
                                <div>
                                  <span className="text-gray-600">Browser:</span>
                                  <p className="font-medium">{referral.browser}</p>
                                </div>
                                <div>
                                  <span className="text-gray-600">Clicks:</span>
                                  <p className="font-medium">{referral.clicks}</p>
                                </div>
                              </div>
                              {referral.coordinates && (
                                <div className="mt-3 text-sm">
                                  <span className="text-gray-600">Coordinates:</span>
                                  <span className="font-medium ml-2">
                                    {referral.coordinates.latitude?.toFixed(4)}, {referral.coordinates.longitude?.toFixed(4)}
                                  </span>
                                </div>
                              )}
                              <div className="mt-2 text-xs text-gray-500">
                                {new Date(referral.createdAt).toLocaleString()}
                              </div>
                            </div>
                          ))}
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          {/* Link Performance Tab */}
          {activeTab === 'links' && (
            <div className="space-y-6">
              <div className="bg-white shadow overflow-hidden sm:rounded-md">
                <div className="px-4 py-5 sm:px-6">
                  <h3 className="text-lg leading-6 font-medium text-gray-900">Link Performance Analytics</h3>
                  <p className="mt-1 max-w-2xl text-sm text-gray-500">Comprehensive tracking of referral link performance and user engagement</p>
                </div>
                <div className="px-4 py-4">
                  {!linkAnalytics ? (
                    <div className="text-center py-8">
                      <button
                        onClick={async () => {
                          try {
                            const res = await axios.get(`${process.env.REACT_APP_API_URL}/admin/link-analytics`);
                            setLinkAnalytics(res.data);
                          } catch (err) {
                            console.error('Error fetching link analytics:', err);
                          }
                        }}
                        className="bg-indigo-600 text-white px-6 py-2 rounded-md hover:bg-indigo-700"
                      >
                        Load Link Analytics
                      </button>
                    </div>
                  ) : (
                    <div className="space-y-6">
                      {/* Overview Stats */}
                      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        <div className="bg-blue-50 p-4 rounded-lg text-center">
                          <div className="text-2xl font-bold text-blue-600">{linkAnalytics.overview.totalClicks.toLocaleString()}</div>
                          <div className="text-sm text-blue-700">Total Link Clicks</div>
                        </div>
                        <div className="bg-green-50 p-4 rounded-lg text-center">
                          <div className="text-2xl font-bold text-green-600">{linkAnalytics.overview.uniqueVisitors.toLocaleString()}</div>
                          <div className="text-sm text-green-700">Unique Visitors</div>
                        </div>
                        <div className="bg-purple-50 p-4 rounded-lg text-center">
                          <div className="text-2xl font-bold text-purple-600">{linkAnalytics.overview.clickThroughRate}%</div>
                          <div className="text-sm text-purple-700">Avg Click Rate per Visitor</div>
                        </div>
                      </div>

                      {/* Platform Performance */}
                      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                        <div>
                          <h4 className="text-md font-medium text-gray-900 mb-4">Platform Performance</h4>
                          <div className="space-y-3">
                            {linkAnalytics.platformStats.map((platform, index) => (
                              <div key={platform._id} className="flex justify-between items-center p-3 bg-gray-50 rounded-lg">
                                <span className="font-medium capitalize">{platform._id}</span>
                                <span className="text-gray-600 font-semibold">{platform.count} clicks</span>
                              </div>
                            ))}
                          </div>
                        </div>

                        <div>
                          <h4 className="text-md font-medium text-gray-900 mb-4">Device Distribution</h4>
                          <div className="space-y-3">
                            {linkAnalytics.deviceStats.map((device, index) => (
                              <div key={device._id} className="flex justify-between items-center p-3 bg-blue-50 rounded-lg">
                                <span className="font-medium capitalize">{device._id}</span>
                                <span className="text-blue-600 font-semibold">{device.count} clicks</span>
                              </div>
                            ))}
                          </div>
                        </div>
                      </div>

                      {/* Top Performing Posts */}
                      <div>
                        <h4 className="text-md font-medium text-gray-900 mb-4">Top Performing Posts by Link Clicks</h4>
                        <div className="space-y-4">
                          {linkAnalytics.topPosts.map((post, index) => (
                            <div key={post.postId} className="border border-gray-200 rounded-lg p-4">
                              <div className="flex justify-between items-start mb-3">
                                <div>
                                  <h5 className="font-medium text-gray-900">{post.title}</h5>
                                  <p className="text-sm text-gray-600">Post ID: {post.postId}</p>
                                </div>
                                <div className="text-right">
                                  <div className="text-lg font-bold text-blue-600">{post.clicks}</div>
                                  <div className="text-sm text-gray-500">link clicks</div>
                                </div>
                              </div>
                              <div className="grid grid-cols-2 gap-4 text-sm">
                                <div>
                                  <span className="text-gray-600">Conversions:</span>
                                  <span className="font-medium ml-2">{post.conversions || 0}</span>
                                </div>
                                <div>
                                  <span className="text-gray-600">Conversion Rate:</span>
                                  <span className="font-medium ml-2">
                                    {post.clicks > 0 ? ((post.conversions / post.clicks) * 100).toFixed(1) : 0}%
                                  </span>
                                </div>
                              </div>
                            </div>
                          ))}
                        </div>
                      </div>

                      {/* Geographic Performance */}
                      <div>
                        <h4 className="text-md font-medium text-gray-900 mb-4">Geographic Performance</h4>
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                          {linkAnalytics.geoStats.slice(0, 12).map((location, index) => (
                            <div key={index} className="bg-gray-50 p-3 rounded-lg text-center">
                              <div className="text-lg font-semibold text-gray-900">{location.clicks}</div>
                              <div className="text-sm text-gray-600">{location.location.city}, {location.location.state}</div>
                              <div className="text-xs text-gray-500">{location.uniqueVisitors} unique visitors</div>
                            </div>
                          ))}
                        </div>
                      </div>

                      {/* Time-based Performance */}
                      <div>
                        <h4 className="text-md font-medium text-gray-900 mb-4">Performance by Hour</h4>
                        <div className="grid grid-cols-6 md:grid-cols-12 gap-2">
                          {linkAnalytics.timeStats.map((timeSlot) => (
                            <div key={timeSlot.hour} className="text-center">
                              <div className="bg-orange-100 p-2 rounded">
                                <div className="text-sm font-semibold text-orange-800">{timeSlot.hour}:00</div>
                                <div className="text-xs text-orange-600">{timeSlot.clicks} clicks</div>
                                <div className="text-xs text-orange-500">{timeSlot.uniqueVisitors} visitors</div>
                              </div>
                            </div>
                          ))}
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          {/* Analytics Tab */}
          {activeTab === 'analytics' && platformStats && (
            <div className="space-y-6">
              <div className="bg-white shadow overflow-hidden sm:rounded-md">
                <div className="px-4 py-5 sm:px-6">
                  <h3 className="text-lg leading-6 font-medium text-gray-900">Activity Analytics</h3>
                  <p className="mt-1 max-w-2xl text-sm text-gray-500">Breakdown of recent platform activities</p>
                </div>
                <div className="px-4 py-4">
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    <div className="bg-green-50 p-4 rounded-lg">
                      <div className="flex items-center">
                        <div className="w-10 h-10 bg-green-100 rounded-full flex items-center justify-center">
                          <span className="text-green-600 text-lg">👤</span>
                        </div>
                        <div className="ml-3">
                          <p className="text-sm font-medium text-green-900">User Registrations</p>
                          <p className="text-2xl font-bold text-green-600">{platformStats.recentActivityBreakdown.user_registrations}</p>
                        </div>
                      </div>
                    </div>

                    <div className="bg-blue-50 p-4 rounded-lg">
                      <div className="flex items-center">
                        <div className="w-10 h-10 bg-blue-100 rounded-full flex items-center justify-center">
                          <span className="text-blue-600 text-lg">📝</span>
                        </div>
                        <div className="ml-3">
                          <p className="text-sm font-medium text-blue-900">Posts Created</p>
                          <p className="text-2xl font-bold text-blue-600">{platformStats.recentActivityBreakdown.post_creations}</p>
                        </div>
                      </div>
                    </div>

                    <div className="bg-purple-50 p-4 rounded-lg">
                      <div className="flex items-center">
                        <div className="w-10 h-10 bg-purple-100 rounded-full flex items-center justify-center">
                          <span className="text-purple-600 text-lg">🔗</span>
                        </div>
                        <div className="ml-3">
                          <p className="text-sm font-medium text-purple-900">Referrals Shared</p>
                          <p className="text-2xl font-bold text-purple-600">{platformStats.recentActivityBreakdown.referral_shares}</p>
                        </div>
                      </div>
                    </div>

                    <div className="bg-orange-50 p-4 rounded-lg">
                      <div className="flex items-center">
                        <div className="w-10 h-10 bg-orange-100 rounded-full flex items-center justify-center">
                          <span className="text-orange-600 text-lg">👆</span>
                        </div>
                        <div className="ml-3">
                          <p className="text-sm font-medium text-orange-900">Referral Clicks</p>
                          <p className="text-2xl font-bold text-orange-600">{platformStats.recentActivityBreakdown.referral_clicks}</p>
                        </div>
                      </div>
                    </div>

                    <div className="bg-yellow-50 p-4 rounded-lg">
                      <div className="flex items-center">
                        <div className="w-10 h-10 bg-yellow-100 rounded-full flex items-center justify-center">
                          <span className="text-yellow-600 text-lg">💰</span>
                        </div>
                        <div className="ml-3">
                          <p className="text-sm font-medium text-yellow-900">Commissions Earned</p>
                          <p className="text-2xl font-bold text-yellow-600">{platformStats.recentActivityBreakdown.commission_earnings}</p>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default AdminDashboard;