import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { FaTrophy, FaStar, FaCrown, FaMedal, FaFire, FaCalendar, FaUsers, FaChartLine, FaGift, FaShieldAlt, FaRocket, FaGem } from 'react-icons/fa';
import Navbar from '../components/Navbar';
import { REACT_APP_API_URL } from '../utils/constants';

const Gamification = () => {
  const [userStats, setUserStats] = useState(null);
  const [badges, setBadges] = useState([]);
  const [leaderboard, setLeaderboard] = useState([]);
  const [userBadges, setUserBadges] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('overview');
  const [user, setUser] = useState(null);

  const fetchGamificationData = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('token');
      if (token) {
        axios.defaults.headers.common['Authorization'] = `Bearer ${token}`;
        const userRes = await axios.get(`${REACT_APP_API_URL}/auth/profile`);
        setUser(userRes.data);
      }

      // Fetch user gamification stats
      const statsRes = await axios.get(`${REACT_APP_API_URL}/gamification/stats`);
      setUserStats(statsRes.data);

      // Fetch all available badges
      const badgesRes = await axios.get(`${REACT_APP_API_URL}/gamification/badges`);
      setBadges(badgesRes.data);

      // Fetch user's earned badges
      const userBadgesRes = await axios.get(`${REACT_APP_API_URL}/gamification/my-badges`);
      setUserBadges(userBadgesRes.data.badges || []);

      // Fetch leaderboard
      const leaderboardRes = await axios.get(`${REACT_APP_API_URL}/gamification/leaderboard?limit=10`);
      setLeaderboard(leaderboardRes.data);
    } catch (err) {
      console.error('Error fetching gamification data:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchGamificationData();
  }, []);

  const getBadgeIcon = (rarity) => {
    switch (rarity) {
      case 'legendary':
        return <FaCrown className="w-6 h-6 text-yellow-500" />;
      case 'epic':
        return <FaGem className="w-6 h-6 text-purple-500" />;
      case 'rare':
        return <FaStar className="w-6 h-6 text-blue-500" />;
      case 'uncommon':
        return <FaMedal className="w-6 h-6 text-green-500" />;
      default:
        return <FaShieldAlt className="w-6 h-6 text-gray-500" />;
    }
  };

  const getBadgeColor = (rarity) => {
    switch (rarity) {
      case 'legendary':
        return 'border-yellow-200 bg-yellow-50';
      case 'epic':
        return 'border-purple-200 bg-purple-50';
      case 'rare':
        return 'border-blue-200 bg-blue-50';
      case 'uncommon':
        return 'border-green-200 bg-green-50';
      default:
        return 'border-gray-200 bg-gray-50';
    }
  };

  const getRarityColor = (rarity) => {
    switch (rarity) {
      case 'legendary':
        return 'text-yellow-600';
      case 'epic':
        return 'text-purple-600';
      case 'rare':
        return 'text-blue-600';
      case 'uncommon':
        return 'text-green-600';
      default:
        return 'text-gray-600';
    }
  };

  const getLevelProgress = () => {
    if (!userStats) return 0;
    const currentLevel = userStats.level || 1;
    const experience = userStats.experience || 0;
    const expForNextLevel = currentLevel * 1000; // Simple formula
    const expForCurrentLevel = (currentLevel - 1) * 1000;
    return ((experience - expForCurrentLevel) / (expForNextLevel - expForCurrentLevel)) * 100;
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 via-white to-purple-50">
        <Navbar />
        <div className="flex justify-center items-center h-64">
          <div className="text-lg">Loading gamification data...</div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 via-white to-purple-50">
      <Navbar />

      <header className="bg-white/95 backdrop-blur-md shadow-lg">
        <div className="max-w-7xl mx-auto py-8 px-4 sm:px-6 lg:px-8">
          <h1 className="text-4xl font-bold bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent mb-4">
            Gamification Center
          </h1>
          <p className="text-gray-600">Track your progress, earn badges, and climb the leaderboard</p>
        </div>
      </header>

      <main className="max-w-7xl mx-auto py-8 sm:px-6 lg:px-8">
        {/* Stats Overview */}
        {userStats && (
          <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
            <div className="bg-white rounded-2xl p-6 shadow-lg">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm text-gray-600">Level</p>
                  <p className="text-3xl font-bold text-blue-600">{userStats.level || 1}</p>
                </div>
                <FaTrophy className="w-8 h-8 text-blue-500" />
              </div>
              <div className="mt-4">
                <div className="flex justify-between text-sm mb-1">
                  <span>Progress to Level {userStats.level + 1}</span>
                  <span>{Math.round(getLevelProgress())}%</span>
                </div>
                <div className="w-full bg-gray-200 rounded-full h-2">
                  <div
                    className="bg-gradient-to-r from-blue-500 to-purple-500 h-2 rounded-full transition-all duration-300"
                    style={{ width: `${getLevelProgress()}%` }}
                  ></div>
                </div>
              </div>
            </div>

            <div className="bg-white rounded-2xl p-6 shadow-lg">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm text-gray-600">Total Points</p>
                  <p className="text-3xl font-bold text-green-600">{userStats.totalPoints || 0}</p>
                </div>
                <FaStar className="w-8 h-8 text-green-500" />
              </div>
            </div>

            <div className="bg-white rounded-2xl p-6 shadow-lg">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm text-gray-600">Current Streak</p>
                  <p className="text-3xl font-bold text-orange-600">{userStats.streak?.current || 0}</p>
                </div>
                <FaFire className="w-8 h-8 text-orange-500" />
              </div>
            </div>

            <div className="bg-white rounded-2xl p-6 shadow-lg">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm text-gray-600">Badges Earned</p>
                  <p className="text-3xl font-bold text-purple-600">{userBadges.length}</p>
                </div>
                <FaMedal className="w-8 h-8 text-purple-500" />
              </div>
            </div>
          </div>
        )}

        {/* Tabs */}
        <div className="bg-white rounded-2xl shadow-lg p-6 mb-8">
          <div className="flex space-x-4">
            <button
              onClick={() => setActiveTab('overview')}
              className={`px-6 py-3 rounded-lg font-medium transition-colors ${
                activeTab === 'overview' ? 'bg-blue-500 text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              }`}
            >
              Overview
            </button>
            <button
              onClick={() => setActiveTab('badges')}
              className={`px-6 py-3 rounded-lg font-medium transition-colors ${
                activeTab === 'badges' ? 'bg-purple-500 text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              }`}
            >
              Badges
            </button>
            <button
              onClick={() => setActiveTab('leaderboard')}
              className={`px-6 py-3 rounded-lg font-medium transition-colors ${
                activeTab === 'leaderboard' ? 'bg-green-500 text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              }`}
            >
              Leaderboard
            </button>
          </div>
        </div>

        {/* Tab Content */}
        {activeTab === 'overview' && userStats && (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            {/* Progress Section */}
            <div className="bg-white rounded-2xl shadow-lg p-6">
              <h3 className="text-xl font-bold text-gray-900 mb-6 flex items-center space-x-2">
                <FaChartLine className="w-5 h-5" />
                <span>Your Progress</span>
              </h3>

              <div className="space-y-4">
                <div className="flex justify-between items-center">
                  <span className="text-gray-600">Experience Points</span>
                  <span className="font-semibold">{userStats.experience || 0} XP</span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-gray-600">Current Streak</span>
                  <span className="font-semibold">{userStats.streak?.current || 0} days</span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-gray-600">Longest Streak</span>
                  <span className="font-semibold">{userStats.streak?.longest || 0} days</span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-gray-600">Last Activity</span>
                  <span className="font-semibold">
                    {userStats.streak?.lastActivity ? new Date(userStats.streak.lastActivity).toLocaleDateString() : 'Never'}
                  </span>
                </div>
              </div>
            </div>

            {/* Recent Badges */}
            <div className="bg-white rounded-2xl shadow-lg p-6">
              <h3 className="text-xl font-bold text-gray-900 mb-6 flex items-center space-x-2">
                <FaMedal className="w-5 h-5" />
                <span>Recent Badges</span>
              </h3>

              {userBadges.length === 0 ? (
                <p className="text-gray-500 text-center py-8">No badges earned yet. Keep participating to earn badges!</p>
              ) : (
                <div className="space-y-3">
                  {userBadges.slice(0, 5).map((userBadge) => (
                    <div key={userBadge._id} className="flex items-center space-x-3 p-3 bg-gray-50 rounded-lg">
                      {getBadgeIcon(userBadge.badge?.rarity)}
                      <div className="flex-1">
                        <p className="font-medium text-gray-900">{userBadge.badge?.name}</p>
                        <p className="text-sm text-gray-500">{userBadge.badge?.description}</p>
                      </div>
                      <div className="text-right">
                        <div className="text-sm font-semibold text-yellow-600">+{userBadge.badge?.points} pts</div>
                        <div className="text-xs text-gray-500">
                          {new Date(userBadge.earnedAt).toLocaleDateString()}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        )}

        {activeTab === 'badges' && (
          <div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {badges.map((badge) => {
                const earned = userBadges.some(ub => ub.badge?._id === badge._id);
                return (
                  <div
                    key={badge._id}
                    className={`p-6 rounded-2xl border-2 transition-all duration-200 ${
                      earned
                        ? `${getBadgeColor(badge.rarity)} border-current`
                        : 'bg-gray-50 border-gray-200 opacity-60'
                    }`}
                  >
                    <div className="text-center">
                      <div className={`w-16 h-16 mx-auto mb-4 rounded-full flex items-center justify-center ${
                        earned ? 'bg-white shadow-lg' : 'bg-gray-200'
                      }`}>
                        {getBadgeIcon(badge.rarity)}
                      </div>
                      <h3 className={`font-bold text-lg mb-2 ${earned ? 'text-gray-900' : 'text-gray-500'}`}>
                        {badge.name}
                      </h3>
                      <p className={`text-sm mb-3 ${earned ? 'text-gray-600' : 'text-gray-400'}`}>
                        {badge.description}
                      </p>
                      <div className="flex justify-between items-center text-xs">
                        <span className={`px-2 py-1 rounded-full font-semibold ${getRarityColor(badge.rarity)}`}>
                          {badge.rarity}
                        </span>
                        <span className="text-yellow-600 font-semibold">+{badge.points} pts</span>
                      </div>
                      {earned && (
                        <div className="mt-3 text-xs text-green-600 font-semibold">
                          ✓ Earned
                        </div>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {activeTab === 'leaderboard' && (
          <div className="bg-white rounded-2xl shadow-lg p-6">
            <h3 className="text-xl font-bold text-gray-900 mb-6 flex items-center space-x-2">
              <FaUsers className="w-5 h-5" />
              <span>Top Performers</span>
            </h3>

            <div className="space-y-4">
              {leaderboard.map((entry, index) => (
                <div key={entry.userId} className={`flex items-center space-x-4 p-4 rounded-lg ${
                  entry.userId === user?._id ? 'bg-blue-50 border-2 border-blue-200' : 'bg-gray-50'
                }`}>
                  <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold ${
                    index === 0 ? 'bg-yellow-500 text-white' :
                    index === 1 ? 'bg-gray-400 text-white' :
                    index === 2 ? 'bg-orange-500 text-white' :
                    'bg-blue-500 text-white'
                  }`}>
                    {index + 1}
                  </div>
                  <div className="flex-1">
                    <div className="flex items-center space-x-2">
                      <p className="font-semibold text-gray-900">@{entry.username}</p>
                      {entry.userId === user?._id && (
                        <span className="px-2 py-1 bg-blue-100 text-blue-600 text-xs rounded-full">You</span>
                      )}
                    </div>
                    <p className="text-sm text-gray-500">{entry.userType}</p>
                  </div>
                  <div className="text-right">
                    <p className="font-bold text-lg text-gray-900">{entry.points}</p>
                    <p className="text-sm text-gray-500">points</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default Gamification;