// API Configuration - Production URL
const baseUrl = process.env.REACT_APP_API_URL || 'https://referral-hub-backend-production.up.railway.app';
export const API_BASE_URL = baseUrl.endsWith('/api') ? baseUrl : `${baseUrl}/api`;
export const API_URL = API_BASE_URL;

// Debug logging
console.log('API_BASE_URL:', API_BASE_URL);
console.log('REACT_APP_API_URL:', process.env.REACT_APP_API_URL);

// Helper function to get full API URL
export const getApiUrl = (endpoint) => {
  return `${API_BASE_URL}${endpoint}`;
};

// For backward compatibility - direct export of the base URL
export { API_BASE_URL as REACT_APP_API_URL };