import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import axios from 'axios';
import { REACT_APP_API_URL } from '../utils/constants';
import NotificationCenter from './NotificationCenter';

const Navbar = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [user, setUser] = useState(null);

  useEffect(() => {
    const fetchUser = async () => {
      const token = localStorage.getItem('token');
      if (token) {
        try {
          axios.defaults.headers.common['Authorization'] = `Bearer ${token}`;
          const res = await axios.get(`${REACT_APP_API_URL}/auth/profile`);
          setUser(res.data);
        } catch (error) {
          console.error('Error fetching user:', error);
        }
      }
    };
    fetchUser();
  }, []);

  const handleLogout = () => {
    localStorage.removeItem('token');
    setUser(null);
    navigate('/');
  };

  const isActive = (path) => location.pathname === path;

  // Show navbar for non-logged-in users only on post view pages (referral links)
  const isPostView = location.pathname.startsWith('/post/');
  if (!user && !isPostView) {
    return null;
  }

  return (
    <nav className="bg-white shadow-sm border-b border-gray-200">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-16">
          <div className="flex items-center">
            {/* Back Button */}
            {location.pathname !== '/' && location.pathname !== '/dashboard' && (
              <button
                onClick={() => navigate(-1)}
                className="mr-4 p-2 rounded-md text-gray-600 hover:text-gray-900 hover:bg-gray-100 transition-colors"
                title="Go back"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
                </svg>
              </button>
            )}

            {/* Logo/Brand */}
            <div className="flex-shrink-0">
              <button
                onClick={() => user ? navigate('/dashboard') : navigate('/')}
                className="text-xl font-bold text-indigo-600 hover:text-indigo-700"
              >
                RefHub
              </button>
            </div>
          </div>

          <div className="flex items-center space-x-4">
            {user ? (
              <>
                {/* Notifications */}
                <NotificationCenter user={user} />

                {/* User Info */}
                <div className="hidden md:flex items-center space-x-2 mr-4">
                  <span className="text-sm font-medium text-gray-700">Welcome, {user.username}</span>
                </div>

                {/* Navigation Links */}
                <div className="hidden md:flex items-center space-x-4">
                  <button
                    onClick={() => navigate('/dashboard')}
                    className={`px-3 py-2 rounded-md text-sm font-medium transition-colors ${
                      isActive('/dashboard')
                        ? 'bg-indigo-100 text-indigo-700'
                        : 'text-gray-600 hover:text-gray-900 hover:bg-gray-100'
                    }`}
                  >
                    Dashboard
                  </button>
                  <button
                    onClick={() => navigate('/analytics')}
                    className={`px-3 py-2 rounded-md text-sm font-medium transition-colors ${
                      isActive('/analytics')
                        ? 'bg-indigo-100 text-indigo-700'
                        : 'text-gray-600 hover:text-gray-900 hover:bg-gray-100'
                    }`}
                  >
                    Analytics
                  </button>
                  <button
                    onClick={() => navigate('/journey')}
                    className={`px-3 py-2 rounded-md text-sm font-medium transition-colors ${
                      isActive('/journey')
                        ? 'bg-indigo-100 text-indigo-700'
                        : 'text-gray-600 hover:text-gray-900 hover:bg-gray-100'
                    }`}
                  >
                    Journey
                  </button>
                  <button
                    onClick={() => navigate('/marketplace')}
                    className={`px-3 py-2 rounded-md text-sm font-medium transition-colors ${
                      isActive('/marketplace')
                        ? 'bg-indigo-100 text-indigo-700'
                        : 'text-gray-600 hover:text-gray-900 hover:bg-gray-100'
                    }`}
                  >
                    Marketplace
                  </button>
                  <button
                    onClick={() => navigate('/profile')}
                    className={`px-3 py-2 rounded-md text-sm font-medium transition-colors ${
                      isActive('/profile')
                        ? 'bg-indigo-100 text-indigo-700'
                        : 'text-gray-600 hover:text-gray-900 hover:bg-gray-100'
                    }`}
                  >
                    Profile
                  </button>
                  {user && user.role === 'admin' && (
                    <button
                      onClick={() => navigate('/admin')}
                      className={`px-3 py-2 rounded-md text-sm font-medium transition-colors ${
                        isActive('/admin')
                          ? 'bg-red-100 text-red-700'
                          : 'text-red-600 hover:text-red-900 hover:bg-red-100'
                      }`}
                    >
                      Admin
                    </button>
                  )}
                  <button
                    onClick={() => navigate('/super-admin')}
                    className={`px-3 py-2 rounded-md text-sm font-medium transition-colors ${
                      isActive('/super-admin')
                        ? 'bg-purple-100 text-purple-700'
                        : 'text-purple-600 hover:text-purple-900 hover:bg-purple-100'
                    }`}
                    title="View Complete System Data"
                  >
                    🔍 Data View
                  </button>
                </div>

                {/* Create Post Button */}
                <button
                  onClick={() => navigate('/create-post')}
                  className="bg-indigo-600 text-white px-4 py-2 rounded-md text-sm font-medium hover:bg-indigo-700 transition-colors"
                >
                  Create Post
                </button>

                {/* Logout Button */}
                <button
                  onClick={handleLogout}
                  className="bg-red-100 text-red-700 px-4 py-2 rounded-md text-sm font-medium hover:bg-red-200 transition-colors"
                >
                  Logout
                </button>
              </>
            ) : (
              <>
                {/* Login and Register buttons for non-logged-in users */}
                <div className="flex items-center space-x-4">
                  <button
                    onClick={() => navigate('/login')}
                    className="text-gray-600 hover:text-gray-900 px-3 py-2 rounded-md text-sm font-medium transition-colors"
                  >
                    Login
                  </button>
                  <button
                    onClick={() => navigate('/register')}
                    className="bg-indigo-600 text-white px-4 py-2 rounded-md text-sm font-medium hover:bg-indigo-700 transition-colors"
                  >
                    Sign Up
                  </button>
                </div>
              </>
            )}
          </div>
        </div>

        {/* Mobile Navigation */}
        {user ? (
          <div className="md:hidden pb-3">
            <div className="flex items-center space-x-2">
              <button
                onClick={() => navigate('/dashboard')}
                className={`px-3 py-2 rounded-md text-sm font-medium transition-colors ${
                  isActive('/dashboard')
                    ? 'bg-indigo-100 text-indigo-700'
                    : 'text-gray-600 hover:text-gray-900 hover:bg-gray-100'
                }`}
              >
                Dashboard
              </button>
              <button
                onClick={() => navigate('/analytics')}
                className={`px-3 py-2 rounded-md text-sm font-medium transition-colors ${
                  isActive('/analytics')
                    ? 'bg-indigo-100 text-indigo-700'
                    : 'text-gray-600 hover:text-gray-900 hover:bg-gray-100'
                }`}
              >
                Analytics
              </button>
              <button
                onClick={() => navigate('/journey')}
                className={`px-3 py-2 rounded-md text-sm font-medium transition-colors ${
                  isActive('/journey')
                    ? 'bg-indigo-100 text-indigo-700'
                    : 'text-gray-600 hover:text-gray-900 hover:bg-gray-100'
                }`}
              >
                Journey
              </button>
              <button
                onClick={() => navigate('/marketplace')}
                className={`px-3 py-2 rounded-md text-sm font-medium transition-colors ${
                  isActive('/marketplace')
                    ? 'bg-indigo-100 text-indigo-700'
                    : 'text-gray-600 hover:text-gray-900 hover:bg-gray-100'
                }`}
              >
                Marketplace
              </button>
              <button
                onClick={() => navigate('/profile')}
                className={`px-3 py-2 rounded-md text-sm font-medium transition-colors ${
                  isActive('/profile')
                    ? 'bg-indigo-100 text-indigo-700'
                    : 'text-gray-600 hover:text-gray-900 hover:bg-gray-100'
                }`}
              >
                Profile
              </button>
              <button
                onClick={() => navigate('/super-admin')}
                className={`px-3 py-2 rounded-md text-sm font-medium transition-colors ${
                  isActive('/super-admin')
                    ? 'bg-purple-100 text-purple-700'
                    : 'text-purple-600 hover:text-purple-900 hover:bg-purple-100'
                }`}
              >
                🔍 Data
              </button>
            </div>
          </div>
        ) : (
          <div className="md:hidden pb-3">
            <div className="flex items-center justify-center space-x-4">
              <button
                onClick={() => navigate('/login')}
                className="text-gray-600 hover:text-gray-900 px-3 py-2 rounded-md text-sm font-medium transition-colors"
              >
                Login
              </button>
              <button
                onClick={() => navigate('/register')}
                className="bg-indigo-600 text-white px-4 py-2 rounded-md text-sm font-medium hover:bg-indigo-700 transition-colors"
              >
                Sign Up
              </button>
            </div>
          </div>
        )}
      </div>
    </nav>
  );
};

export default Navbar;