import axios from 'axios';
import { REACT_APP_API_URL } from '../utils/constants';

class ComprehensiveReferralService {
  constructor() {
    this.API_BASE = REACT_APP_API_URL;
    this.sessionId = this.generateSessionId();
  }

  generateSessionId() {
    return `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  getAuthHeaders() {
    const token = localStorage.getItem('token');
    return token ? { Authorization: `Bearer ${token}` } : {};
  }

  async getCurrentUser() {
    try {
      const response = await axios.get(`${this.API_BASE}/auth/profile`, {
        headers: this.getAuthHeaders()
      });
      return response.data;
    } catch (error) {
      console.error('Error getting current user:', error);
      return null;
    }
  }

  async getDeviceInfo() {
    const ua = navigator.userAgent;
    
    // Device detection
    let device = 'desktop';
    if (/mobile/i.test(ua) && !/tablet/i.test(ua)) device = 'mobile';
    else if (/tablet|ipad/i.test(ua)) device = 'tablet';
    else if (/android/i.test(ua) && /mobile/i.test(ua)) device = 'smartphone';

    // Browser detection with version
    let browser = 'Unknown';
    let browserVersion = '';
    if (ua.includes('Edg/')) {
      browser = 'Edge';
      browserVersion = ua.match(/Edg\/(\d+\.\d+)/)?.[1] || '';
    } else if (ua.includes('Chrome/')) {
      browser = 'Chrome';
      browserVersion = ua.match(/Chrome\/(\d+\.\d+)/)?.[1] || '';
    } else if (ua.includes('Firefox/')) {
      browser = 'Firefox';
      browserVersion = ua.match(/Firefox\/(\d+\.\d+)/)?.[1] || '';
    } else if (ua.includes('Safari/') && !ua.includes('Chrome')) {
      browser = 'Safari';
      browserVersion = ua.match(/Version\/(\d+\.\d+)/)?.[1] || '';
    }

    // OS detection
    let os = 'Unknown';
    let osVersion = '';
    if (ua.includes('Windows NT')) {
      os = 'Windows';
      osVersion = ua.match(/Windows NT (\d+\.\d+)/)?.[1] || '';
    } else if (ua.includes('Mac OS X')) {
      os = 'macOS';
      osVersion = ua.match(/Mac OS X (\d+[._]\d+)/)?.[1].replace('_', '.') || '';
    } else if (ua.includes('iPhone')) {
      os = 'iOS';
      osVersion = ua.match(/OS (\d+_\d+)/)?.[1].replace('_', '.') || '';
    } else if (ua.includes('Android')) {
      os = 'Android';
      osVersion = ua.match(/Android (\d+\.\d+)/)?.[1] || '';
    } else if (ua.includes('Linux')) {
      os = 'Linux';
    }

    // Device model (for mobile)
    let deviceModel = '';
    if (os === 'iOS') {
      if (ua.includes('iPhone')) deviceModel = 'iPhone';
      else if (ua.includes('iPad')) deviceModel = 'iPad';
    } else if (os === 'Android') {
      const modelMatch = ua.match(/Android.*;\s([^)]+)\)/);
      deviceModel = modelMatch ? modelMatch[1] : '';
    }

    // Screen size
    const screenSize = {
      width: window.screen.width,
      height: window.screen.height
    };

    // Viewport size
    const viewport = {
      width: window.innerWidth,
      height: window.innerHeight
    };

    // Network information (if available)
    const networkInfo = {};
    if (navigator.connection) {
      networkInfo.connectionType = navigator.connection.type || navigator.connection.effectiveType || null;
      networkInfo.effectiveType = navigator.connection.effectiveType || null;
      networkInfo.downlink = navigator.connection.downlink || null;
      networkInfo.rtt = navigator.connection.rtt || null;
      networkInfo.saveData = navigator.connection.saveData || false;
    }

    // Language and timezone
    const language = navigator.language || navigator.userLanguage;
    const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;

    // Color scheme
    const colorScheme = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';

    // Touch support
    const touchSupport = 'ontouchstart' in window || navigator.maxTouchPoints > 0;

    // Incognito detection (basic)
    let isIncognito = false;
    try {
      if (window.requestFileSystem) {
        isIncognito = true;
      }
    } catch (e) {}

    return {
      device,
      browser,
      browserVersion,
      userAgent: ua,
      os,
      osVersion,
      deviceModel,
      screenSize,
      viewport,
      networkInfo,
      language,
      timezone,
      colorScheme,
      touchSupport,
      isIncognito
    };
  }

  async getLocation() {
    return new Promise((resolve) => {
      if ('geolocation' in navigator) {
        navigator.geolocation.getCurrentPosition(
          (position) => {
            resolve({
              coordinates: {
                latitude: position.coords.latitude,
                longitude: position.coords.longitude,
                accuracy: position.coords.accuracy
              },
              // You can add city/state/country by calling a reverse geocoding API
              city: null,
              state: null,
              country: null
            });
          },
          (error) => {
            console.log('Location permission denied or unavailable');
            resolve({ coordinates: null, city: null, state: null, country: null });
          }
        );
      } else {
        resolve({ coordinates: null, city: null, state: null, country: null });
      }
    });
  }

  /**
   * Initialize post with creator's view (called after post creation)
   * Tracks ALL device, browser, screen, network, location data
   */
  async initializePost(postId) {
    try {
      const deviceInfo = await this.getDeviceInfo();
      const location = await this.getLocation();

      const response = await axios.post(
        `${this.API_BASE}/comprehensive-referrals/post-created`,
        {
          postId,
          metadata: {
            // Device & Browser
            device: deviceInfo.device,
            browser: deviceInfo.browser,
            browserVersion: deviceInfo.browserVersion,
            userAgent: deviceInfo.userAgent,
            
            // Screen & Display
            screenSize: deviceInfo.screenSize,
            viewport: deviceInfo.viewport,
            colorScheme: deviceInfo.colorScheme,
            
            // OS
            os: deviceInfo.os,
            osVersion: deviceInfo.osVersion,
            deviceModel: deviceInfo.deviceModel,
            
            // Network
            networkInfo: deviceInfo.networkInfo,
            
            // Location
            location: location.coordinates ? {
              city: location.city,
              state: location.state,
              country: location.country,
              coordinates: location.coordinates,
              timezone: deviceInfo.timezone
            } : null,
            
            // Language & Settings
            language: deviceInfo.language,
            timezone: deviceInfo.timezone,
            touchSupport: deviceInfo.touchSupport,
            isIncognito: deviceInfo.isIncognito,
            
            sessionId: this.sessionId,
            platform: 'web',
            timestamp: new Date().toISOString()
          }
        },
        { headers: this.getAuthHeaders() }
      );

      console.log('✅ Post initialized with comprehensive tracking:', {
        device: deviceInfo.device,
        browser: deviceInfo.browser,
        os: deviceInfo.os,
        screenSize: `${deviceInfo.screenSize.width}x${deviceInfo.screenSize.height}`,
        network: deviceInfo.networkInfo.effectiveType || 'Unknown'
      });
      
      return response.data;
    } catch (error) {
      console.error('Error initializing post:', error);
      throw error;
    }
  }

  /**
   * Track when user shares a post
   * Returns chainId and shareUrl
   * Tracks EVERYTHING: device, browser, screen, OS, network, location, etc.
   */
  async trackShare(postId, platform = 'web', parentChainId = null, shareMethod = 'copy_link') {
    try {
      const user = await this.getCurrentUser();
      if (!user) {
        throw new Error('User must be logged in to share');
      }

      const deviceInfo = await this.getDeviceInfo();
      const location = await this.getLocation();

      // Comprehensive tracking data
      const trackingData = {
        postId,
        sharerId: user._id,
        platform, // whatsapp, linkedin, twitter, facebook, etc.
        
        // Device & Browser
        device: deviceInfo.device,
        browser: deviceInfo.browser,
        browserVersion: deviceInfo.browserVersion,
        userAgent: deviceInfo.userAgent,
        
        // Screen & Display
        screenSize: deviceInfo.screenSize,
        viewport: deviceInfo.viewport,
        colorScheme: deviceInfo.colorScheme,
        
        // OS & Device Model
        os: deviceInfo.os,
        osVersion: deviceInfo.osVersion,
        deviceModel: deviceInfo.deviceModel,
        
        // Network
        networkInfo: deviceInfo.networkInfo,
        
        // Location
        location: location.coordinates ? {
          city: location.city,
          state: location.state,
          country: location.country,
          coordinates: location.coordinates
        } : null,
        coordinates: location.coordinates,
        
        // Language & Timezone
        language: deviceInfo.language,
        timezone: deviceInfo.timezone,
        
        // Additional tracking
        touchSupport: deviceInfo.touchSupport,
        isIncognito: deviceInfo.isIncognito,
        shareMethod, // native_share, copy_link, direct_platform
        fromLocation: {
          page: window.location.pathname,
          url: window.location.href,
          referrer: document.referrer
        },
        toLocation: null, // Will be filled when someone clicks
        
        parentChainId,
        sessionId: this.sessionId,
        ipAddress: null // Will be captured by backend
      };

      const response = await axios.post(
        `${this.API_BASE}/comprehensive-referrals/share`,
        trackingData,
        { headers: this.getAuthHeaders() }
      );

      console.log('✅ Share tracked with comprehensive data:', {
        platform,
        device: deviceInfo.device,
        browser: deviceInfo.browser,
        os: deviceInfo.os,
        screenSize: `${deviceInfo.screenSize.width}x${deviceInfo.screenSize.height}`,
        location: location.city || 'Unknown'
      });
      
      return response.data;
    } catch (error) {
      console.error('Error tracking share:', error);
      throw error;
    }
  }

  /**
   * Track when someone clicks a referral link
   * Captures ALL device, browser, network, screen data
   */
  async trackClick(postId, chainId, referrerId) {
    try {
      const user = await this.getCurrentUser();
      const deviceInfo = await this.getDeviceInfo();
      const location = await this.getLocation();

      const trackingData = {
        postId,
        chainId,
        clickerId: user?._id || null,
        referrerId,
        
        // Device & Browser
        platform: 'web',
        device: deviceInfo.device,
        browser: deviceInfo.browser,
        browserVersion: deviceInfo.browserVersion,
        userAgent: deviceInfo.userAgent,
        
        // Screen & Display
        screenSize: deviceInfo.screenSize,
        viewport: deviceInfo.viewport,
        colorScheme: deviceInfo.colorScheme,
        
        // OS
        os: deviceInfo.os,
        osVersion: deviceInfo.osVersion,
        deviceModel: deviceInfo.deviceModel,
        
        // Network
        networkInfo: deviceInfo.networkInfo,
        
        // Location
        location: location.coordinates ? {
          city: location.city,
          state: location.state,
          country: location.country,
          coordinates: location.coordinates
        } : null,
        coordinates: location.coordinates,
        
        // Language & Settings
        language: deviceInfo.language,
        timezone: deviceInfo.timezone,
        touchSupport: deviceInfo.touchSupport,
        isIncognito: deviceInfo.isIncognito,
        
        sessionId: this.sessionId
      };

      const response = await axios.post(
        `${this.API_BASE}/comprehensive-referrals/click`,
        trackingData
      );

      console.log('✅ Click tracked with full data:', {
        device: deviceInfo.device,
        browser: deviceInfo.browser,
        os: deviceInfo.os,
        screen: `${deviceInfo.screenSize.width}x${deviceInfo.screenSize.height}`
      });
      
      return response.data;
    } catch (error) {
      console.error('Error tracking click:', error);
      throw error;
    }
  }

  /**
   * Track registration/login via referral link
   * Captures COMPLETE device, browser, network, location data
   */
  async trackRegistration(postId, chainId, referrerId, registrationType = 'register') {
    try {
      const user = await this.getCurrentUser();
      if (!user) {
        console.warn('No user found for registration tracking');
        return null;
      }

      const deviceInfo = await this.getDeviceInfo();
      const location = await this.getLocation();

      const trackingData = {
        postId,
        chainId,
        newUserId: user._id,
        referrerId,
        registrationType,
        
        // Device & Browser
        platform: 'web',
        device: deviceInfo.device,
        browser: deviceInfo.browser,
        browserVersion: deviceInfo.browserVersion,
        userAgent: deviceInfo.userAgent,
        
        // Screen & Display
        screenSize: deviceInfo.screenSize,
        viewport: deviceInfo.viewport,
        colorScheme: deviceInfo.colorScheme,
        
        // OS
        os: deviceInfo.os,
        osVersion: deviceInfo.osVersion,
        deviceModel: deviceInfo.deviceModel,
        
        // Network
        networkInfo: deviceInfo.networkInfo,
        
        // Location
        location: location.coordinates ? {
          city: location.city,
          state: location.state,
          country: location.country,
          coordinates: location.coordinates,
          timezone: deviceInfo.timezone
        } : null,
        coordinates: location.coordinates,
        
        // Language & Settings
        language: deviceInfo.language,
        timezone: deviceInfo.timezone,
        touchSupport: deviceInfo.touchSupport,
        isIncognito: deviceInfo.isIncognito,
        
        sessionId: this.sessionId
      };

      const response = await axios.post(
        `${this.API_BASE}/comprehensive-referrals/register`,
        trackingData
      );

      console.log('✅ Registration tracked with comprehensive data:', {
        type: registrationType,
        device: deviceInfo.device,
        browser: deviceInfo.browser,
        os: deviceInfo.os,
        location: location.city || 'Unknown',
        network: deviceInfo.networkInfo.effectiveType || 'Unknown'
      });
      
      return response.data;
    } catch (error) {
      console.error('Error tracking registration:', error);
      throw error;
    }
  }

  /**
   * Get all referral chains for current user
   */
  async getUserChains(postId = null) {
    try {
      const user = await this.getCurrentUser();
      if (!user) {
        throw new Error('User must be logged in');
      }

      const url = postId
        ? `${this.API_BASE}/comprehensive-referrals/user/${user._id}/chains?postId=${postId}`
        : `${this.API_BASE}/comprehensive-referrals/user/${user._id}/chains`;

      const response = await axios.get(url, {
        headers: this.getAuthHeaders()
      });

      console.log('User chains:', response.data);
      return response.data;
    } catch (error) {
      console.error('Error getting user chains:', error);
      throw error;
    }
  }

  /**
   * Get all chains for a specific post
   */
  async getPostChains(postId) {
    try {
      const response = await axios.get(
        `${this.API_BASE}/comprehensive-referrals/post/${postId}/chains`,
        { headers: this.getAuthHeaders() }
      );

      console.log('Post chains:', response.data);
      return response.data;
    } catch (error) {
      console.error('Error getting post chains:', error);
      throw error;
    }
  }

  /**
   * Get analytics for a post
   */
  async getPostAnalytics(postId) {
    try {
      const response = await axios.get(
        `${this.API_BASE}/comprehensive-referrals/analytics/${postId}`,
        { headers: this.getAuthHeaders() }
      );

      console.log('Post analytics:', response.data);
      return response.data;
    } catch (error) {
      console.error('Error getting post analytics:', error);
      throw error;
    }
  }

  /**
   * Handle purchase and commission distribution
   */
  async processPurchase(postId, buyerUserId = null) {
    try {
      const response = await axios.post(
        `${this.API_BASE}/comprehensive-referrals/purchase`,
        { postId, buyerUserId },
        { headers: this.getAuthHeaders() }
      );

      console.log('Purchase processed:', response.data);
      return response.data;
    } catch (error) {
      console.error('Error processing purchase:', error);
      throw error;
    }
  }

  /**
   * Generate shareable links for different platforms
   */
  async generateShareLinks(postId, chainId) {
    const baseUrl = window.location.origin;
    const shareUrl = `${baseUrl}/post/${postId}?chainId=${chainId}&ref=${(await this.getCurrentUser())?._id}`;

    return {
      web: shareUrl,
      whatsapp: `https://wa.me/?text=${encodeURIComponent('Check out this post: ' + shareUrl)}`,
      linkedin: `https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(shareUrl)}`,
      twitter: `https://twitter.com/intent/tweet?url=${encodeURIComponent(shareUrl)}`,
      facebook: `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(shareUrl)}`,
      telegram: `https://t.me/share/url?url=${encodeURIComponent(shareUrl)}`,
      email: `mailto:?subject=Check this out&body=${encodeURIComponent('Check out this post: ' + shareUrl)}`
    };
  }

  /**
   * Parse URL parameters for referral tracking
   */
  parseReferralParams() {
    const params = new URLSearchParams(window.location.search);
    return {
      chainId: params.get('chainId'),
      referrerId: params.get('ref'),
      platform: params.get('platform') || 'web'
    };
  }

  /**
   * Store referral params in session storage for later use
   */
  storeReferralParams(params) {
    if (params.chainId && params.referrerId) {
      sessionStorage.setItem('referralParams', JSON.stringify(params));
      console.log('Referral params stored:', params);
    }
  }

  /**
   * Get stored referral params
   */
  getStoredReferralParams() {
    const stored = sessionStorage.getItem('referralParams');
    return stored ? JSON.parse(stored) : null;
  }

  /**
   * Clear stored referral params
   */
  clearReferralParams() {
    sessionStorage.removeItem('referralParams');
  }
}

// Export singleton instance
const comprehensiveReferralService = new ComprehensiveReferralService();
export default comprehensiveReferralService;

