import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { API_URL } from '../utils/constants';

const LikeButton = ({ targetType, targetId, initialCounts, initialUserReaction, size = 'md', showCount = true }) => {
  const [counts, setCounts] = useState(initialCounts || {
    total: 0,
    like: 0,
    love: 0,
    wow: 0,
    sad: 0,
    angry: 0,
    haha: 0
  });
  const [userReaction, setUserReaction] = useState(initialUserReaction || null);
  const [isLoading, setIsLoading] = useState(false);
  const [showReactions, setShowReactions] = useState(false);

  const reactions = [
    { type: 'like', emoji: '👍', label: 'Like' },
    { type: 'love', emoji: '❤️', label: 'Love' },
    { type: 'haha', emoji: '😂', label: 'Haha' },
    { type: 'wow', emoji: '😮', label: 'Wow' },
    { type: 'sad', emoji: '😢', label: 'Sad' },
    { type: 'angry', emoji: '😠', label: 'Angry' }
  ];

  const sizeClasses = {
    sm: 'text-sm',
    md: 'text-base',
    lg: 'text-lg'
  };

  const buttonSizeClasses = {
    sm: 'text-xs px-2 py-1',
    md: 'text-sm px-3 py-1.5',
    lg: 'text-base px-4 py-2'
  };

  useEffect(() => {
    if (initialCounts) {
      setCounts(initialCounts);
    }
    if (initialUserReaction) {
      setUserReaction(initialUserReaction);
    }
  }, [initialCounts, initialUserReaction]);

  const fetchLikeCounts = async () => {
    try {
      const response = await axios.get(`${API_URL}/likes/${targetType}/${targetId}/counts`);
      if (response.data.success) {
        setCounts(response.data.counts);
      }
    } catch (error) {
      console.error('Error fetching like counts:', error);
    }
  };

  const handleReaction = async (reactionType) => {
    if (isLoading) return;

    setIsLoading(true);
    setShowReactions(false);

    try {
      const token = localStorage.getItem('token');
      if (!token) {
        alert('Please login to react');
        setIsLoading(false);
        return;
      }

      const response = await axios.post(
        `${API_URL}/likes/toggle`,
        { targetType, targetId, reactionType },
        { headers: { Authorization: `Bearer ${token}` } }
      );

      if (response.data.success) {
        // Update local state based on action
        if (response.data.action === 'unliked') {
          setUserReaction(null);
          setCounts(prev => ({
            ...prev,
            total: Math.max(0, prev.total - 1),
            [reactionType]: Math.max(0, prev[reactionType] - 1)
          }));
        } else if (response.data.action === 'liked') {
          setUserReaction(reactionType);
          setCounts(prev => ({
            ...prev,
            total: prev.total + 1,
            [reactionType]: prev[reactionType] + 1
          }));
        } else if (response.data.action === 'reacted') {
          // Changed reaction
          const oldReaction = userReaction;
          setUserReaction(reactionType);
          setCounts(prev => ({
            ...prev,
            [oldReaction]: Math.max(0, prev[oldReaction] - 1),
            [reactionType]: prev[reactionType] + 1
          }));
        }
      }
    } catch (error) {
      console.error('Error toggling reaction:', error);
      alert('Failed to react. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const getReactionEmoji = (type) => {
    const reaction = reactions.find(r => r.type === type);
    return reaction ? reaction.emoji : '👍';
  };

  return (
    <div className="relative inline-block">
      {/* Main Like Button */}
      <button
        onClick={() => handleReaction('like')}
        onMouseEnter={() => setShowReactions(true)}
        onMouseLeave={() => setTimeout(() => setShowReactions(false), 200)}
        disabled={isLoading}
        className={`
          ${buttonSizeClasses[size]}
          ${userReaction ? 'bg-blue-100 text-blue-600' : 'bg-gray-100 text-gray-700'}
          rounded-full font-medium hover:bg-blue-50 transition-all
          disabled:opacity-50 disabled:cursor-not-allowed
          flex items-center gap-1.5
        `}
      >
        <span className={sizeClasses[size]}>
          {userReaction ? getReactionEmoji(userReaction) : '👍'}
        </span>
        {showCount && counts.total > 0 && (
          <span className="font-semibold">{counts.total}</span>
        )}
      </button>

      {/* Reaction Picker */}
      {showReactions && (
        <div
          onMouseEnter={() => setShowReactions(true)}
          onMouseLeave={() => setShowReactions(false)}
          className="absolute bottom-full left-0 mb-2 bg-white rounded-full shadow-lg border border-gray-200 flex gap-1 p-2 z-10 animate-fade-in"
        >
          {reactions.map((reaction) => (
            <button
              key={reaction.type}
              onClick={() => handleReaction(reaction.type)}
              title={reaction.label}
              className="text-2xl hover:scale-125 transition-transform p-1 rounded-full hover:bg-gray-100"
            >
              {reaction.emoji}
            </button>
          ))}
        </div>
      )}

      {/* Reaction Breakdown (on hover) */}
      {counts.total > 0 && showCount && (
        <div className="hidden group-hover:block absolute top-full left-0 mt-2 bg-white rounded-lg shadow-lg border border-gray-200 p-3 z-10 min-w-[150px]">
          <div className="text-xs font-semibold text-gray-700 mb-2">Reactions</div>
          <div className="space-y-1">
            {reactions.map((reaction) => (
              counts[reaction.type] > 0 && (
                <div key={reaction.type} className="flex items-center justify-between text-xs">
                  <span className="flex items-center gap-1">
                    <span>{reaction.emoji}</span>
                    <span>{reaction.label}</span>
                  </span>
                  <span className="font-semibold">{counts[reaction.type]}</span>
                </div>
              )
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default LikeButton;

