import React, { useState, useEffect } from 'react';
import { fetchCommissions } from '../utils/referralApi';
import { getSocket } from '../utils/socket';

const CommissionTracker = ({ postId, postDetails }) => {
  const [commissions, setCommissions] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [totalCommission, setTotalCommission] = useState(0);
  const [sortBy, setSortBy] = useState('commission'); // commission, chainDepth, position
  const [filter, setFilter] = useState('all'); // all, first, middle, last

  useEffect(() => {
    loadCommissions();
    
    // Socket.IO real-time updates
    const socket = getSocket();
    socket.emit('join_post_room', postId);

    socket.on('referral_update', () => {
      // Reload commissions when new referral comes in
      loadCommissions();
    });

    return () => {
      socket.off('referral_update');
      socket.emit('leave_post_room', postId);
    };
  }, [postId]);

  const loadCommissions = async () => {
    try {
      setIsLoading(true);
      const response = await fetchCommissions(postId);
      if (response.success) {
        setCommissions(response.commissionPreview);
        calculateTotal(response.commissionPreview);
      }
    } catch (error) {
      console.error('Error loading commissions:', error);
      // Set empty state if not authenticated or error
      setCommissions([]);
    } finally {
      setIsLoading(false);
    }
  };

  const calculateTotal = (commissionData) => {
    const total = commissionData.reduce((sum, c) => sum + c.commission, 0);
    setTotalCommission(total);
  };

  // Sort and filter commissions
  const processedCommissions = commissions
    .filter(c => filter === 'all' || c.position === filter)
    .sort((a, b) => {
      switch (sortBy) {
        case 'commission':
          return b.commission - a.commission;
        case 'chainDepth':
          return a.chainDepth - b.chainDepth;
        case 'position':
          return a.position.localeCompare(b.position);
        default:
          return 0;
      }
    });

  // Group by position
  const byPosition = {
    first: commissions.filter(c => c.position === 'first'),
    middle: commissions.filter(c => c.position === 'middle'),
    last: commissions.filter(c => c.position === 'last')
  };

  const totalByPosition = {
    first: byPosition.first.reduce((sum, c) => sum + c.commission, 0),
    middle: byPosition.middle.reduce((sum, c) => sum + c.commission, 0),
    last: byPosition.last.reduce((sum, c) => sum + c.commission, 0)
  };

  const pointsPool = postDetails?.distributablePoints || postDetails?.pointsPool || 0;
  const platformFee = pointsPool * 0.10;

  if (isLoading) {
    return (
      <div className="flex justify-center items-center py-12">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  if (commissions.length === 0) {
    return (
      <div className="bg-white rounded-lg shadow-sm p-8 text-center">
        <div className="text-6xl mb-4">💰</div>
        <h3 className="text-xl font-bold text-gray-900 mb-2">No Commissions Yet</h3>
        <p className="text-gray-600">
          Commissions will appear here once there are referrals for this post
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header with Summary */}
      <div className="bg-gradient-to-r from-green-600 to-emerald-600 rounded-lg p-6 text-white">
        <h2 className="text-2xl font-bold mb-4">💰 Commission Tracker</h2>
        
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="bg-white/20 rounded-lg p-4">
            <p className="text-sm opacity-90 mb-1">Total Points Pool</p>
            <p className="text-2xl font-bold">{pointsPool.toLocaleString()}</p>
          </div>
          
          <div className="bg-white/20 rounded-lg p-4">
            <p className="text-sm opacity-90 mb-1">Platform Fee (10%)</p>
            <p className="text-2xl font-bold">{Math.round(platformFee).toLocaleString()}</p>
          </div>
          
          <div className="bg-white/20 rounded-lg p-4">
            <p className="text-sm opacity-90 mb-1">Distributable</p>
            <p className="text-2xl font-bold">{Math.round(pointsPool - platformFee).toLocaleString()}</p>
          </div>
          
          <div className="bg-white/20 rounded-lg p-4">
            <p className="text-sm opacity-90 mb-1">Total Distributed</p>
            <p className="text-2xl font-bold">{Math.round(totalCommission).toLocaleString()}</p>
          </div>
        </div>
      </div>

      {/* Distribution Breakdown */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white rounded-lg shadow-sm p-6 border-l-4 border-blue-500">
          <div className="flex items-center justify-between mb-3">
            <h3 className="text-lg font-bold text-gray-900">🥇 First Referrer</h3>
            <span className="text-sm font-semibold text-blue-600">30%</span>
          </div>
          <p className="text-3xl font-bold text-blue-600 mb-1">
            {Math.round(totalByPosition.first).toLocaleString()}
          </p>
          <p className="text-sm text-gray-600">{byPosition.first.length} recipient(s)</p>
        </div>

        <div className="bg-white rounded-lg shadow-sm p-6 border-l-4 border-green-500">
          <div className="flex items-center justify-between mb-3">
            <h3 className="text-lg font-bold text-gray-900">🏃 Middle Sharers</h3>
            <span className="text-sm font-semibold text-green-600">40%</span>
          </div>
          <p className="text-3xl font-bold text-green-600 mb-1">
            {Math.round(totalByPosition.middle).toLocaleString()}
          </p>
          <p className="text-sm text-gray-600">{byPosition.middle.length} recipient(s)</p>
        </div>

        <div className="bg-white rounded-lg shadow-sm p-6 border-l-4 border-orange-500">
          <div className="flex items-center justify-between mb-3">
            <h3 className="text-lg font-bold text-gray-900">🎯 Last Referrer</h3>
            <span className="text-sm font-semibold text-orange-600">30%</span>
          </div>
          <p className="text-3xl font-bold text-orange-600 mb-1">
            {Math.round(totalByPosition.last).toLocaleString()}
          </p>
          <p className="text-sm text-gray-600">{byPosition.last.length} recipient(s)</p>
        </div>
      </div>

      {/* Filters and Sort */}
      <div className="bg-white rounded-lg shadow-sm p-4">
        <div className="flex flex-wrap items-center gap-4">
          <div className="flex items-center gap-2">
            <span className="text-sm font-medium text-gray-700">Filter:</span>
            <div className="flex gap-2">
              {['all', 'first', 'middle', 'last'].map((f) => (
                <button
                  key={f}
                  onClick={() => setFilter(f)}
                  className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                    filter === f
                      ? 'bg-green-600 text-white'
                      : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                  }`}
                >
                  {f.charAt(0).toUpperCase() + f.slice(1)}
                </button>
              ))}
            </div>
          </div>

          <div className="flex items-center gap-2">
            <span className="text-sm font-medium text-gray-700">Sort by:</span>
            <select
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value)}
              className="px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-green-500"
            >
              <option value="commission">Commission (High to Low)</option>
              <option value="chainDepth">Chain Depth</option>
              <option value="position">Position</option>
            </select>
          </div>

          <div className="ml-auto text-sm text-gray-600">
            Showing {processedCommissions.length} of {commissions.length} recipients
          </div>
        </div>
      </div>

      {/* Commission List */}
      <div className="bg-white rounded-lg shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead className="bg-gray-50 border-b border-gray-200">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-semibold text-gray-700 uppercase tracking-wider">
                  User
                </th>
                <th className="px-6 py-3 text-left text-xs font-semibold text-gray-700 uppercase tracking-wider">
                  Position
                </th>
                <th className="px-6 py-3 text-left text-xs font-semibold text-gray-700 uppercase tracking-wider">
                  Level
                </th>
                <th className="px-6 py-3 text-right text-xs font-semibold text-gray-700 uppercase tracking-wider">
                  Commission
                </th>
                <th className="px-6 py-3 text-right text-xs font-semibold text-gray-700 uppercase tracking-wider">
                  Percentage
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200">
              {processedCommissions.map((commission, index) => {
                const percentage = ((commission.commission / totalCommission) * 100).toFixed(1);
                
                return (
                  <tr key={commission.chainId || index} className="hover:bg-gray-50 transition-colors">
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-full bg-gradient-to-br from-green-500 to-emerald-600 flex items-center justify-center text-white font-bold">
                          {commission.username?.[0]?.toUpperCase() || 'A'}
                        </div>
                        <div>
                          <p className="font-medium text-gray-900">{commission.username || 'Anonymous'}</p>
                          <p className="text-xs text-gray-500">ID: {commission.userId?.slice(0, 8)}...</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span
                        className={`inline-flex px-3 py-1 rounded-full text-xs font-semibold ${
                          commission.position === 'first'
                            ? 'bg-blue-100 text-blue-800'
                            : commission.position === 'middle'
                            ? 'bg-green-100 text-green-800'
                            : 'bg-orange-100 text-orange-800'
                        }`}
                      >
                        {commission.position.charAt(0).toUpperCase() + commission.position.slice(1)}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className="text-sm text-gray-900">Level {commission.chainDepth}</span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-right">
                      <p className="text-lg font-bold text-green-600">
                        {Math.round(commission.commission).toLocaleString()} pts
                      </p>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-right">
                      <div className="flex items-center justify-end gap-2">
                        <div className="w-20 bg-gray-200 rounded-full h-2">
                          <div
                            className="bg-green-600 h-2 rounded-full"
                            style={{ width: `${percentage}%` }}
                          ></div>
                        </div>
                        <span className="text-sm font-semibold text-gray-700 min-w-[3rem]">
                          {percentage}%
                        </span>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      {/* Commission Formula Info */}
      <div className="bg-blue-50 border border-blue-200 rounded-lg p-6">
        <h3 className="text-lg font-bold text-blue-900 mb-3">📖 Commission Formula</h3>
        <div className="space-y-2 text-sm text-blue-800">
          <p>
            <strong>Platform Fee:</strong> 10% of points pool goes to platform
          </p>
          <p>
            <strong>First Referrer:</strong> 30% of distributable points (person who started the chain)
          </p>
          <p>
            <strong>Last Referrer:</strong> 30% of distributable points (most recent person in chain)
          </p>
          <p>
            <strong>Middle Sharers:</strong> 40% of distributable points (divided equally among all middle sharers)
          </p>
          <p className="pt-2 border-t border-blue-300 mt-3">
            <strong>Example:</strong> For a 1000 point pool → Platform gets 100 pts, 900 pts distributed →
            First gets 270 pts, Last gets 270 pts, Middle sharers split 360 pts
          </p>
        </div>
      </div>
    </div>
  );
};

export default CommissionTracker;

