import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import axios from 'axios';
import { REACT_APP_API_URL } from '../utils/constants';
import comprehensiveReferralService from '../services/comprehensiveReferralService';

const Register = () => {
  const [formData, setFormData] = useState({
    email: '',
    username: '',
    password: '',
    confirmPassword: '',
    type: 'individual',
  });
  const [error, setError] = useState('');
  const [referralId, setReferralId] = useState(null);
  const [trendingPosts, setTrendingPosts] = useState([]);
  const navigate = useNavigate();

  // Extract and STORE referral parameters from URL
  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const refParam = urlParams.get('ref');
    const chainIdParam = urlParams.get('chainId');
    const postIdParam = urlParams.get('postId') || window.location.pathname.split('/post/')[1];
    
    if (refParam) {
      setReferralId(refParam);
      // 🚀 Store referral params for tracking after registration
      comprehensiveReferralService.storeReferralParams({
        referrerId: refParam,
        chainId: chainIdParam,
        postId: postIdParam,
        platform: 'web'
      });
      console.log('✅ Referral params stored for post-registration tracking');
    }
  }, []);

  // Fetch trending posts on component mount
  useEffect(() => {
    const fetchTrendingPosts = async () => {
      try {
        const response = await fetch(`${REACT_APP_API_URL}/posts/trending?limit=3`);
        const data = await response.json();
        setTrendingPosts(data.posts || []);
      } catch (error) {
        console.error('Error fetching trending posts:', error);
        setTrendingPosts([]);
      }
    };
    fetchTrendingPosts();
  }, []);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  // Function to detect device type
  const detectDevice = () => {
    const userAgent = navigator.userAgent;
    if (/mobile/i.test(userAgent)) return 'mobile';
    if (/tablet/i.test(userAgent)) return 'tablet';
    return 'desktop';
  };

  // Function to get browser info
  const getBrowser = () => {
    const userAgent = navigator.userAgent;
    if (userAgent.includes('Chrome')) return 'Chrome';
    if (userAgent.includes('Firefox')) return 'Firefox';
    if (userAgent.includes('Safari')) return 'Safari';
    if (userAgent.includes('Edge')) return 'Edge';
    return 'Other';
  };

  // Function to get coordinates (if available)
  const getCoordinates = async () => {
    return new Promise((resolve) => {
      if (navigator.geolocation) {
        navigator.geolocation.getCurrentPosition(
          (position) => {
            resolve({
              latitude: position.coords.latitude,
              longitude: position.coords.longitude,
              accuracy: position.coords.accuracy
            });
          },
          (error) => {
            console.log('Geolocation error:', error);
            resolve(null);
          },
          { timeout: 10000, enableHighAccuracy: true }
        );
      } else {
        resolve(null);
      }
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError(''); // Clear previous errors
    
    // Validate form data
    if (!formData.email || !formData.username || !formData.password || !formData.confirmPassword) {
      setError('Please fill in all fields');
      return;
    }
    
    if (formData.password !== formData.confirmPassword) {
      setError('Passwords do not match');
      return;
    }
    
    if (formData.password.length < 6) {
      setError('Password must be at least 6 characters long');
      return;
    }
    
    if (formData.username.length < 3) {
      setError('Username must be at least 3 characters long');
      return;
    }
    
    try {
      const coordinates = await getCoordinates();

      const registrationData = {
        ...formData,
        referralId: referralId, // Include referral ID if present
        platform: 'web',
        device: detectDevice(),
        browser: getBrowser(),
        userAgent: navigator.userAgent,
        screenSize: {
          width: window.screen.width,
          height: window.screen.height
        },
        coordinates: coordinates
      };

      console.log('Attempting registration with data:', { email: registrationData.email, username: registrationData.username, type: registrationData.type });
      console.log('API URL:', `${REACT_APP_API_URL}/auth/register`);

      const res = await axios.post(`${REACT_APP_API_URL}/auth/register`, registrationData, {
        headers: {
          'Content-Type': 'application/json',
        },
        timeout: 10000 // 10 second timeout
      });
      
      console.log('Registration successful:', res.data);
      localStorage.setItem('token', res.data.token);
      localStorage.setItem('user', JSON.stringify(res.data.user));
      
      // 🚀 TRACK REGISTRATION VIA REFERRAL LINK (if applicable)
      const storedParams = comprehensiveReferralService.getStoredReferralParams();
      if (storedParams && storedParams.chainId && storedParams.referrerId) {
        try {
          await comprehensiveReferralService.trackRegistration(
            storedParams.postId,
            storedParams.chainId,
            storedParams.referrerId,
            'register'
          );
          console.log('✅ Registration tracked in referral chain!');
          comprehensiveReferralService.clearReferralParams();
        } catch (trackError) {
          console.error('Warning: Registration tracking failed:', trackError);
          // Don't fail registration if tracking fails
        }
      }
      
      navigate('/dashboard');
    } catch (err) {
      console.error('Registration error:', err);
      console.error('Error response:', err.response?.data);
      
      if (err.code === 'ECONNREFUSED' || err.code === 'ERR_NETWORK') {
        setError('Cannot connect to server. Please check if the backend is running.');
      } else if (err.response?.status === 400) {
        const errorData = err.response.data;
        if (errorData.errors) {
          // Handle validation errors
          const errorMessages = Object.values(errorData.errors).filter(Boolean);
          setError(errorMessages.join(', '));
        } else {
          setError(errorData.message || 'Registration failed');
        }
      } else if (err.response?.status === 500) {
        setError('Server error. Please try again later.');
      } else {
        setError(err.response?.data?.message || 'Registration failed. Please try again.');
      }
    }
  };

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex flex-col lg:flex-row items-center justify-center min-h-screen">
          {/* Registration Form */}
          <div className="w-full lg:w-1/2 lg:pr-8">
            <div className="max-w-md mx-auto">
              <div>
                <h2 className="mt-6 text-center text-3xl font-extrabold text-gray-900">
                  Create your account
                </h2>
              </div>
              <form className="mt-8 space-y-6" onSubmit={handleSubmit}>
                <div className="rounded-md shadow-sm -space-y-px">
                  <div>
                    <label htmlFor="email" className="sr-only">
                      Email address
                    </label>
                    <input
                      id="email"
                      name="email"
                      type="email"
                      required
                      className="appearance-none rounded-none relative block w-full px-3 py-2 border border-gray-300 placeholder-gray-500 text-gray-900 rounded-t-md focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 focus:z-10 sm:text-sm"
                      placeholder="Email address"
                      value={formData.email}
                      onChange={handleChange}
                    />
                  </div>
                  <div>
                    <label htmlFor="username" className="sr-only">
                      Username
                    </label>
                    <input
                      id="username"
                      name="username"
                      type="text"
                      required
                      className="appearance-none rounded-none relative block w-full px-3 py-2 border border-gray-300 placeholder-gray-500 text-gray-900 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 focus:z-10 sm:text-sm"
                      placeholder="Username"
                      value={formData.username}
                      onChange={handleChange}
                    />
                  </div>
                  <div>
                    <label htmlFor="password" className="sr-only">
                      Password
                    </label>
                    <input
                      id="password"
                      name="password"
                      type="password"
                      required
                      className="appearance-none rounded-none relative block w-full px-3 py-2 border border-gray-300 placeholder-gray-500 text-gray-900 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 focus:z-10 sm:text-sm"
                      placeholder="Password"
                      value={formData.password}
                      onChange={handleChange}
                    />
                  </div>
                  <div>
                    <label htmlFor="confirmPassword" className="sr-only">
                      Confirm Password
                    </label>
                    <input
                      id="confirmPassword"
                      name="confirmPassword"
                      type="password"
                      required
                      className="appearance-none rounded-none relative block w-full px-3 py-2 border border-gray-300 placeholder-gray-500 text-gray-900 rounded-b-md focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 focus:z-10 sm:text-sm"
                      placeholder="Confirm Password"
                      value={formData.confirmPassword}
                      onChange={handleChange}
                    />
                  </div>
                </div>

                <div>
                  <label htmlFor="type" className="block text-sm font-medium text-gray-700">
                    Account Type
                  </label>
                  <select
                    id="type"
                    name="type"
                    className="mt-1 block w-full py-2 px-3 border border-gray-300 bg-white rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                    value={formData.type}
                    onChange={handleChange}
                  >
                    <option value="individual">Individual</option>
                    <option value="company">Company</option>
                    <option value="enterprise">Enterprise</option>
                  </select>
                </div>

                {error && (
                  <div className="text-red-500 text-sm">{error}</div>
                )}

                <div>
                  <button
                    type="submit"
                    className="group relative w-full flex justify-center py-2 px-4 border border-transparent text-sm font-medium rounded-md text-white bg-indigo-600 hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
                  >
                    Register
                  </button>
                </div>

                <div className="text-center">
                  <Link
                    to="/login"
                    className="font-medium text-indigo-600 hover:text-indigo-500"
                  >
                    Already have an account? Sign in
                  </Link>
                </div>
              </form>
            </div>
          </div>

          {/* Trending Posts */}
          <div className="w-full lg:w-1/2 lg:pl-8 mt-8 lg:mt-0">
            <div className="bg-white rounded-lg shadow-lg p-6">
              <h3 className="text-xl font-bold text-gray-900 mb-4">Trending Posts</h3>
              {trendingPosts.length > 0 ? (
                <div className="space-y-4">
                  {trendingPosts.map((post) => (
                    <div key={post._id} className="border border-gray-200 rounded-lg p-4 hover:shadow-md transition-shadow">
                      <div className="flex space-x-4">
                        {/* Post Image */}
                        <div className="flex-shrink-0">
                          {post.photos && post.photos.length > 0 ? (
                            <img
                              src={`${REACT_APP_API_URL}/uploads/${post.photos[0]}`}
                              alt={post.title}
                              className="w-20 h-20 object-cover rounded-lg"
                            />
                          ) : (
                            <div className="w-20 h-20 bg-gray-200 rounded-lg flex items-center justify-center">
                              <span className="text-gray-400 text-xs">No Image</span>
                            </div>
                          )}
                        </div>

                        {/* Post Details */}
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center space-x-2 mb-1">
                            <span className="text-sm font-medium text-gray-900">@{post.creator?.username || 'Anonymous'}</span>
                            <span className="text-xs text-gray-500 capitalize px-2 py-1 bg-gray-100 rounded-full">{post.status || 'active'}</span>
                          </div>

                          <h4 className="font-semibold text-gray-900 text-sm mb-1 line-clamp-2">{post.title}</h4>

                          <div className="flex items-center justify-between text-xs text-gray-500 mb-2">
                            <span>{new Date(post.createdAt).toLocaleDateString()} {new Date(post.createdAt).toLocaleTimeString()}</span>
                            <span className="font-medium text-green-600">${post.price || 0}</span>
                          </div>

                          <div className="flex items-center space-x-4 text-xs text-gray-600">
                            <span>👁 {post.reach || 0} views</span>
                            <span>👆 {post.conversions || 0} clicks</span>
                          </div>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <p className="text-gray-500">No trending posts available.</p>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Register;