import React, { useState, useEffect } from 'react';
import { 
  FaUser, FaUserPlus, FaRocket, FaShare, FaEye, FaCoins,
  FaClock, FaMapMarkerAlt, FaDesktop, FaMobile, FaGlobe,
  FaCheckCircle, FaFire, FaTrophy
} from 'react-icons/fa';

const ProfessionalActivityFeed = ({ userId = null, limit = 20, showAll = false }) => {
  const [activities, setActivities] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetchActivities();
  }, [userId, limit]);

  const fetchActivities = async () => {
    try {
      setLoading(true);
      setError(null);
      
      // Try multiple activity endpoints
      let url;
      if (showAll) {
        url = `${process.env.REACT_APP_API_URL}/api/activities/recent?limit=${limit}`;
      } else if (userId) {
        // Try the user-specific endpoint first, fallback to user-activities
        url = `${process.env.REACT_APP_API_URL}/api/activities/user/${userId}?limit=${limit}`;
      } else {
        url = `${process.env.REACT_APP_API_URL}/api/activities/recent?limit=${limit}`;
      }

      console.log('🔍 DEBUG: Calling activities API:', url);
      console.log('🔍 DEBUG: UserId provided:', !!userId);
      console.log('🔍 DEBUG: Token present:', !!localStorage.getItem('token'));

      const token = localStorage.getItem('token');
      const headers = userId ? { 'Authorization': `Bearer ${token}` } : {};

      let response;
      let data;

      try {
        response = await fetch(url, { headers });
        console.log('🔍 DEBUG: Activities API response status:', response.status);
        console.log('🔍 DEBUG: Activities API response ok:', response.ok);

        if (!response.ok && userId) {
          // Try fallback endpoint
          console.log('🔍 DEBUG: Primary endpoint failed, trying fallback...');
          const fallbackUrl = `${process.env.REACT_APP_API_URL}/activities/user-activities`;
          response = await fetch(fallbackUrl, { headers });
          console.log('🔍 DEBUG: Fallback activities API response status:', response.status);
        }

        data = await response.json();
        console.log('🔍 DEBUG: Activities API response data:', data);
      } catch (error) {
        console.log('🔍 DEBUG: Error with activities API, trying fallback...');
        if (userId) {
          // Try the user-activities endpoint as fallback
          const fallbackUrl = `${process.env.REACT_APP_API_URL}/activities/user-activities`;
          response = await fetch(fallbackUrl, { headers });
          data = await response.json();
          console.log('🔍 DEBUG: Fallback activities data:', data);
        } else {
          throw error;
        }
      }
      
      // Handle different response formats
      let activities = [];
      if (data.success && data.activities) {
        activities = data.activities;
      } else if (Array.isArray(data)) {
        activities = data;
      } else if (data.activities && Array.isArray(data.activities)) {
        activities = data.activities;
      }

      console.log('✅ Fetched activities:', activities.length);
      if (activities[0]) {
        console.log('📋 Sample activity:', {
          type: activities[0].type,
          message: activities[0].message,
          user: activities[0].user,
          post: activities[0].post
        });
      }

      // ✅ Generate messages if missing
      const activitiesWithMessages = activities.map(act => ({
        ...act,
        message: act.message || generateMessage(act)
      }));

      setActivities(activitiesWithMessages);
    } catch (error) {
      console.error('Error fetching activities:', error);
      setError('Failed to load activities');
      // Provide demo activities when API fails
      setActivities([
        {
          _id: 'demo1',
          type: 'user_registration',
          message: 'Welcome! You joined the platform',
          user: { id: userId || 'demo', username: 'Demo User', name: 'Demo User' },
          timestamp: new Date(Date.now() - 3600000),
          timeAgo: '1h ago'
        },
        {
          _id: 'demo2',
          type: 'post_created',
          message: 'You created a new post: Sample Product',
          user: { id: userId || 'demo', username: 'Demo User', name: 'Demo User' },
          post: { id: 'demo_post', title: 'Sample Product' },
          timestamp: new Date(Date.now() - 7200000),
          timeAgo: '2h ago'
        },
        {
          _id: 'demo3',
          type: 'commission_earned',
          message: 'You earned 25 points from a referral',
          user: { id: userId || 'demo', username: 'Demo User', name: 'Demo User' },
          timestamp: new Date(Date.now() - 86400000),
          timeAgo: '1d ago'
        }
      ]);
    } finally {
      setLoading(false);
    }
  };

  // ✅ Generate meaningful message if backend didn't provide one
  const generateMessage = (activity) => {
    const username = activity.user?.username || 'Someone';
    const postTitle = activity.post?.title || 'a post';
    
    switch (activity.type) {
      case 'user_registration':
        return activity.targetUser 
          ? `${username} joined via ${activity.targetUser.username}'s referral`
          : `${username} joined the platform`;
      case 'user_login':
        return `${username} logged into the platform`;
      case 'post_created':
        return `${username} created a new post: "${postTitle}"`;
      case 'referral_shared':
        const platform = activity.details?.platform || 'social media';
        return `${username} shared "${postTitle}" on ${platform}`;
      case 'referral_click':
        return `Someone clicked ${username}'s referral link for "${postTitle}"`;
      case 'commission_earned':
        const amount = activity.details?.amount || 0;
        return `${username} earned ${amount} credits`;
      default:
        return `${username} performed an action`;
    }
  };

  const getActivityIcon = (type) => {
    const iconClass = "w-5 h-5";
    switch (type) {
      case 'user_registration':
        return <FaUserPlus className={`${iconClass} text-green-500`} />;
      case 'user_login':
        return <FaUser className={`${iconClass} text-blue-500`} />;
      case 'post_created':
        return <FaRocket className={`${iconClass} text-purple-500`} />;
      case 'referral_shared':
        return <FaShare className={`${iconClass} text-pink-500`} />;
      case 'referral_click':
        return <FaEye className={`${iconClass} text-orange-500`} />;
      case 'commission_earned':
        return <FaCoins className={`${iconClass} text-yellow-500`} />;
      default:
        return <FaCheckCircle className={`${iconClass} text-gray-500`} />;
    }
  };

  const getActivityColor = (type) => {
    switch (type) {
      case 'user_registration':
        return 'border-green-200 bg-green-50';
      case 'user_login':
        return 'border-blue-200 bg-blue-50';
      case 'post_created':
        return 'border-purple-200 bg-purple-50';
      case 'referral_shared':
        return 'border-pink-200 bg-pink-50';
      case 'referral_click':
        return 'border-orange-200 bg-orange-50';
      case 'commission_earned':
        return 'border-yellow-200 bg-yellow-50';
      default:
        return 'border-gray-200 bg-gray-50';
    }
  };

  const getBadgeColor = (type) => {
    switch (type) {
      case 'user_registration':
        return 'bg-green-100 text-green-700';
      case 'user_login':
        return 'bg-blue-100 text-blue-700';
      case 'post_created':
        return 'bg-purple-100 text-purple-700';
      case 'referral_shared':
        return 'bg-pink-100 text-pink-700';
      case 'referral_click':
        return 'bg-orange-100 text-orange-700';
      case 'commission_earned':
        return 'bg-yellow-100 text-yellow-700';
      default:
        return 'bg-gray-100 text-gray-700';
    }
  };

  const formatActivityType = (type) => {
    const typeMap = {
      'user_registration': 'Registration',
      'user_login': 'Login',
      'post_created': 'Post Created',
      'referral_shared': 'Shared',
      'referral_click': 'Click',
      'commission_earned': 'Commission'
    };
    return typeMap[type] || type;
  };

  if (loading) {
    return (
      <div className="bg-white rounded-xl shadow-lg p-6">
        <div className="flex items-center justify-center py-12">
          <div className="animate-spin rounded-full h-12 w-12 border-t-4 border-b-4 border-blue-600"></div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-white rounded-xl shadow-lg p-6">
        <div className="text-center py-12">
          <p className="text-red-500 font-semibold">{error}</p>
          <button 
            onClick={fetchActivities}
            className="mt-4 px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
          >
            Retry
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-xl shadow-lg overflow-hidden">
      {/* Header */}
      <div className="bg-gradient-to-r from-blue-600 to-purple-600 p-6">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="text-2xl font-bold text-white flex items-center space-x-2">
              <FaFire className="w-6 h-6 animate-pulse" />
              <span>Recent Activity</span>
            </h3>
            <p className="text-blue-100 mt-1">
              {showAll ? 'All platform activities' : userId ? 'Your activity history' : 'Latest platform events'}
            </p>
          </div>
          <div className="text-right">
            <div className="text-3xl font-bold text-white">{activities.length}</div>
            <div className="text-xs text-blue-100">Events</div>
          </div>
        </div>
      </div>

      {/* Activities List */}
      <div className="divide-y divide-gray-100 max-h-[600px] overflow-y-auto">
        {activities.length === 0 ? (
          <div className="p-12 text-center">
            <FaTrophy className="w-16 h-16 text-gray-300 mx-auto mb-4" />
            <p className="text-lg font-semibold text-gray-600">No activities yet</p>
            <p className="text-sm text-gray-500 mt-2">Start using the platform to see your activity here</p>
          </div>
        ) : (
          activities.map((activity, index) => (
            <div
              key={activity._id || index}
              className={`p-5 border-l-4 ${getActivityColor(activity.type)} hover:bg-white transition-all`}
            >
              <div className="flex items-start space-x-4">
                {/* Icon */}
                <div className="flex-shrink-0">
                  <div className="w-12 h-12 bg-white rounded-full flex items-center justify-center shadow-sm">
                    {getActivityIcon(activity.type)}
                  </div>
                </div>

                {/* Content */}
                <div className="flex-1 min-w-0">
                  {/* Message */}
                  <p className="text-base font-semibold text-gray-900 mb-2">
                    {activity.message}
                  </p>

                  {/* Meta Info */}
                  <div className="flex items-center flex-wrap gap-3 mb-2">
                    {/* Time */}
                    <div className="flex items-center text-sm text-gray-600">
                      <FaClock className="w-3 h-3 mr-1" />
                      <span>{activity.timeAgo || 'Just now'}</span>
                    </div>

                    {/* Type Badge */}
                    <span className={`px-3 py-1 rounded-full text-xs font-bold ${getBadgeColor(activity.type)}`}>
                      {formatActivityType(activity.type)}
                    </span>

                    {/* User Info */}
                    {activity.user && activity.user.username && (
                      <div className="flex items-center text-sm text-gray-600">
                        <FaUser className="w-3 h-3 mr-1 text-blue-500" />
                        <span className="font-medium">{activity.user.username}</span>
                      </div>
                    )}

                    {/* Post Info */}
                    {activity.post && activity.post.title && (
                      <div className="flex items-center text-sm text-gray-600">
                        <FaRocket className="w-3 h-3 mr-1 text-purple-500" />
                        <span className="font-medium truncate max-w-xs">{activity.post.title}</span>
                      </div>
                    )}
                  </div>

                  {/* Additional Details */}
                  {(activity.details || activity.metadata) && (
                    <div className="flex items-center flex-wrap gap-3 text-xs text-gray-500">
                      {/* Location */}
                      {activity.metadata?.location?.city && (
                        <div className="flex items-center bg-white px-2 py-1 rounded">
                          <FaMapMarkerAlt className="w-3 h-3 mr-1 text-red-500" />
                          <span>{activity.metadata.location.city}, {activity.metadata.location.country || ''}</span>
                        </div>
                      )}

                      {/* Device */}
                      {activity.details?.device && (
                        <div className="flex items-center bg-white px-2 py-1 rounded">
                          {activity.details.device === 'mobile' ? (
                            <FaMobile className="w-3 h-3 mr-1 text-blue-500" />
                          ) : (
                            <FaDesktop className="w-3 h-3 mr-1 text-purple-500" />
                          )}
                          <span className="capitalize">{activity.details.device}</span>
                        </div>
                      )}

                      {/* Browser */}
                      {activity.details?.browser && (
                        <div className="flex items-center bg-white px-2 py-1 rounded">
                          <FaGlobe className="w-3 h-3 mr-1 text-green-500" />
                          <span>{activity.details.browser}</span>
                        </div>
                      )}

                      {/* Platform */}
                      {activity.details?.platform && activity.details.platform !== 'web' && (
                        <div className="flex items-center bg-white px-2 py-1 rounded">
                          <FaShare className="w-3 h-3 mr-1 text-pink-500" />
                          <span className="capitalize">{activity.details.platform}</span>
                        </div>
                      )}
                    </div>
                  )}
                </div>
              </div>
            </div>
          ))
        )}
      </div>

      {/* Footer */}
      {activities.length > 0 && (
        <div className="bg-gray-50 px-6 py-4 border-t border-gray-200">
          <div className="flex items-center justify-between">
            <button 
              onClick={fetchActivities}
              className="text-sm font-semibold text-blue-600 hover:text-blue-700 flex items-center"
            >
              <svg className="w-4 h-4 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
              </svg>
              Refresh
            </button>
            <p className="text-xs text-gray-500">
              Showing {activities.length} {activities.length === 1 ? 'activity' : 'activities'}
            </p>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfessionalActivityFeed;

