import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { format } from 'date-fns';
import {
  FaMapMarkerAlt, FaRoute, FaUsers, FaArrowRight, FaGlobe,
  FaMobile, FaDesktop, FaTablet, FaClock, FaEye, FaBrain
} from 'react-icons/fa';
import { API_BASE_URL } from '../utils/constants';
import { MapContainer, TileLayer, CircleMarker, Polyline, Popup, Tooltip as MapTooltip } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';

const RealTimeJourneyVisualization = ({ postId }) => {
  const [journeyData, setJourneyData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [selectedConnection, setSelectedConnection] = useState(null);

  useEffect(() => {
    fetchJourneyData();
    const interval = setInterval(fetchJourneyData, 10000); // Update every 10 seconds
    return () => clearInterval(interval);
  }, [postId]);

  const fetchJourneyData = async () => {
    try {
      const response = await axios.get(
        `${API_BASE_URL}/tracking/comprehensive/journey-map/${postId}`,
        {
          headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
        }
      );
      setJourneyData(response.data);
      setLoading(false);
    } catch (error) {
      console.error('Error fetching journey data:', error);
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500"></div>
      </div>
    );
  }

  if (!journeyData || !journeyData.locationPoints || journeyData.locationPoints.length === 0) {
    return (
      <div className="text-center py-12 bg-white rounded-xl shadow-lg">
        <FaMapMarkerAlt className="text-gray-400 text-4xl mx-auto mb-4" />
        <p className="text-gray-500 text-lg">No journey data available yet</p>
        <p className="text-gray-400 text-sm mt-2">Journey tracking will appear here once users interact with your post</p>
      </div>
    );
  }

  const { locationPoints, journeyConnections, totalPoints } = journeyData;

  // Group location points by city
  const locationGroups = {};
  locationPoints.forEach(point => {
    const key = `${point.city},${point.country}`;
    if (!locationGroups[key]) {
      locationGroups[key] = {
        city: point.city,
        country: point.country,
        lat: point.lat,
        lng: point.lng,
        points: []
      };
    }
    locationGroups[key].points.push(point);
  });

  // Calculate center of map
  const avgLat = locationPoints.reduce((sum, p) => sum + p.lat, 0) / locationPoints.length;
  const avgLng = locationPoints.reduce((sum, p) => sum + p.lng, 0) / locationPoints.length;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="bg-gradient-to-r from-blue-600 to-purple-600 rounded-xl p-6 text-white">
        <h2 className="text-2xl font-bold mb-2 flex items-center">
          <FaRoute className="mr-3" />
          Real-Time Journey Map
        </h2>
        <p className="text-blue-100">Track how your post travels across the world</p>
        
        <div className="grid grid-cols-3 gap-4 mt-4">
          <div className="bg-white/20 rounded-lg p-3">
            <div className="flex items-center justify-between">
              <FaGlobe className="text-2xl" />
              <div className="text-right">
                <p className="text-2xl font-bold">{Object.keys(locationGroups).length}</p>
                <p className="text-xs text-blue-100">Locations</p>
              </div>
            </div>
          </div>
          <div className="bg-white/20 rounded-lg p-3">
            <div className="flex items-center justify-between">
              <FaUsers className="text-2xl" />
              <div className="text-right">
                <p className="text-2xl font-bold">{totalPoints}</p>
                <p className="text-xs text-blue-100">Total Views</p>
              </div>
            </div>
          </div>
          <div className="bg-white/20 rounded-lg p-3">
            <div className="flex items-center justify-between">
              <FaRoute className="text-2xl" />
              <div className="text-right">
                <p className="text-2xl font-bold">{journeyConnections.length}</p>
                <p className="text-xs text-blue-100">Connections</p>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Map */}
      <div className="bg-white rounded-xl shadow-lg overflow-hidden">
        <div className="p-6">
          <h3 className="text-xl font-bold text-gray-900 mb-4">Geographic Distribution</h3>
          <div className="h-96 rounded-lg overflow-hidden border-2 border-gray-200">
            <MapContainer
              center={[avgLat, avgLng]}
              zoom={3}
              style={{ height: '100%', width: '100%' }}
            >
              <TileLayer
                url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
              />
              
              {/* Draw connection lines */}
              {journeyConnections.map((connection, index) => (
                <Polyline
                  key={index}
                  positions={[
                    [connection.from.lat, connection.from.lng],
                    [connection.to.lat, connection.to.lng]
                  ]}
                  color="#8B5CF6"
                  weight={2}
                  opacity={0.6}
                  dashArray="5, 10"
                />
              ))}
              
              {/* Draw location markers */}
              {Object.values(locationGroups).map((group, index) => {
                const markerSize = Math.min(Math.log(group.points.length + 1) * 5, 30);
                const color = group.points.length > 10 ? '#EF4444' : 
                             group.points.length > 5 ? '#F59E0B' : '#3B82F6';
                
                return (
                  <CircleMarker
                    key={index}
                    center={[group.lat, group.lng]}
                    radius={markerSize}
                    fillColor={color}
                    fillOpacity={0.6}
                    color="#fff"
                    weight={2}
                  >
                    <Popup>
                      <div className="p-2">
                        <h4 className="font-bold text-lg mb-2">{group.city}, {group.country}</h4>
                        <div className="space-y-1 text-sm">
                          <p><strong>Total Views:</strong> {group.points.length}</p>
                          <div className="mt-2">
                            <p className="font-semibold mb-1">Recent Visitors:</p>
                            {group.points.slice(0, 5).map((point, idx) => (
                              <div key={idx} className="flex items-center text-xs text-gray-600 mb-1">
                                {point.device === 'mobile' && <FaMobile className="mr-1 text-blue-500" />}
                                {point.device === 'desktop' && <FaDesktop className="mr-1 text-green-500" />}
                                {point.device === 'tablet' && <FaTablet className="mr-1 text-purple-500" />}
                                <span>{point.browser} • {point.timestamp && format(new Date(point.timestamp), 'HH:mm')}</span>
                              </div>
                            ))}
                          </div>
                        </div>
                      </div>
                    </Popup>
                    <MapTooltip direction="top" offset={[0, -10]} opacity={0.9}>
                      <span className="font-semibold">{group.city}</span>
                      <br />
                      <span className="text-xs">{group.points.length} views</span>
                    </MapTooltip>
                  </CircleMarker>
                );
              })}
            </MapContainer>
          </div>
        </div>
      </div>

      {/* Location List */}
      <div className="bg-white rounded-xl p-6 shadow-lg">
        <h3 className="text-xl font-bold text-gray-900 mb-4">Location Details</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {Object.values(locationGroups).map((group, index) => (
            <div key={index} className="border border-gray-200 rounded-lg p-4 hover:shadow-md transition-shadow">
              <div className="flex items-center justify-between mb-3">
                <div className="flex items-center">
                  <FaMapMarkerAlt className="text-red-500 mr-2" />
                  <div>
                    <p className="font-semibold text-gray-900">{group.city}</p>
                    <p className="text-sm text-gray-500">{group.country}</p>
                  </div>
                </div>
                <span className="text-2xl font-bold text-blue-600">{group.points.length}</span>
              </div>

              {/* Device breakdown for this location */}
              <div className="space-y-2">
                <div className="flex items-center text-xs text-gray-600">
                  <FaMobile className="mr-1 text-blue-500" />
                  <span>Mobile: {group.points.filter(p => p.device === 'mobile').length}</span>
                </div>
                <div className="flex items-center text-xs text-gray-600">
                  <FaDesktop className="mr-1 text-green-500" />
                  <span>Desktop: {group.points.filter(p => p.device === 'desktop').length}</span>
                </div>
                <div className="flex items-center text-xs text-gray-600">
                  <FaTablet className="mr-1 text-purple-500" />
                  <span>Tablet: {group.points.filter(p => p.device === 'tablet').length}</span>
                </div>
              </div>

              {/* Average metrics */}
              {group.points.some(p => p.attentionScore) && (
                <div className="mt-3 pt-3 border-t border-gray-200">
                  <p className="text-xs text-gray-500 mb-1">Averages:</p>
                  <div className="flex items-center justify-between text-xs">
                    <span className="flex items-center">
                      <FaBrain className="mr-1 text-purple-500" />
                      Attention: {Math.round(group.points.reduce((sum, p) => sum + (p.attentionScore || 0), 0) / group.points.length)}
                    </span>
                    <span className="flex items-center">
                      <FaClock className="mr-1 text-blue-500" />
                      {Math.round(group.points.reduce((sum, p) => sum + (p.sessionDuration || 0), 0) / group.points.length)}s
                    </span>
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>

      {/* Recent Activity Timeline */}
      <div className="bg-white rounded-xl p-6 shadow-lg">
        <h3 className="text-xl font-bold text-gray-900 mb-4">Recent Activity Timeline</h3>
        <div className="space-y-3">
          {locationPoints.slice(0, 20).map((point, index) => (
            <div key={index} className="flex items-center p-3 bg-gray-50 rounded-lg hover:bg-gray-100 transition-colors">
              <div className="flex items-center flex-1 space-x-4">
                {/* Device Icon */}
                <div className="flex-shrink-0">
                  {point.device === 'mobile' && <FaMobile className="text-blue-500 text-xl" />}
                  {point.device === 'desktop' && <FaDesktop className="text-green-500 text-xl" />}
                  {point.device === 'tablet' && <FaTablet className="text-purple-500 text-xl" />}
                </div>

                {/* Location Info */}
                <div className="flex-1">
                  <p className="text-sm font-medium text-gray-900">
                    {point.city}, {point.country}
                  </p>
                  <p className="text-xs text-gray-500">
                    {point.browser} • {point.timestamp && format(new Date(point.timestamp), 'MMM d, HH:mm:ss')}
                  </p>
                </div>

                {/* Metrics */}
                {point.attentionScore && (
                  <div className="flex items-center space-x-4 text-xs text-gray-600">
                    <div className="flex items-center">
                      <FaBrain className="mr-1 text-purple-500" />
                      <span>{point.attentionScore}</span>
                    </div>
                    <div className="flex items-center">
                      <FaClock className="mr-1 text-blue-500" />
                      <span>{Math.round(point.sessionDuration || 0)}s</span>
                    </div>
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default RealTimeJourneyVisualization;

