import React, { useState, useEffect } from 'react';
import { getSocket } from '../utils/socket';
import { fetchPostAnalytics, fetchTopReferrers, exportReferralData } from '../utils/referralApi';
import {
  BarChart, Bar, PieChart, Pie, LineChart, Line,
  XAxis, YAxis, CartesianGrid, Tooltip, Legend, Cell,
  ResponsiveContainer, Area, AreaChart
} from 'recharts';

const ReferralAnalyticsDashboard = ({ postId }) => {
  const [analytics, setAnalytics] = useState(null);
  const [topReferrers, setTopReferrers] = useState([]);
  const [timeRange, setTimeRange] = useState('week');
  const [isLoading, setIsLoading] = useState(true);
  const [isExporting, setIsExporting] = useState(false);
  const [lastUpdate, setLastUpdate] = useState(new Date());

  const COLORS = [
    '#3B82F6', '#10B981', '#F59E0B', '#EF4444',
    '#8B5CF6', '#EC4899', '#14B8A6', '#F97316'
  ];

  useEffect(() => {
    loadAnalytics();
    loadTopReferrers();

    // Auto-refresh every 10 seconds
    const interval = setInterval(() => {
      loadAnalytics();
      loadTopReferrers();
      setLastUpdate(new Date());
    }, 10000);

    // Socket.IO real-time updates
    const socket = getSocket();
    socket.emit('join_post_room', postId);

    socket.on('analytics_update', handleAnalyticsUpdate);
    socket.on('referral_update', handleReferralUpdate);

    return () => {
      clearInterval(interval);
      socket.off('analytics_update', handleAnalyticsUpdate);
      socket.off('referral_update', handleReferralUpdate);
      socket.emit('leave_post_room', postId);
    };
  }, [postId, timeRange]);

  const handleAnalyticsUpdate = (data) => {
    if (data.postId === postId) {
      setAnalytics(data.analytics);
      setLastUpdate(new Date());
    }
  };

  const handleReferralUpdate = () => {
    // Refresh analytics when new referral comes in
    loadAnalytics();
    loadTopReferrers();
  };

  const loadAnalytics = async () => {
    try {
      setIsLoading(true);
      const response = await fetchPostAnalytics(postId, { timeRange });
      if (response.success) {
        setAnalytics(response.analytics);
      }
    } catch (error) {
      console.error('Error loading analytics:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const loadTopReferrers = async () => {
    try {
      const response = await fetchTopReferrers(postId, 10);
      if (response.success) {
        setTopReferrers(response.topReferrers);
      }
    } catch (error) {
      console.error('Error loading top referrers:', error);
    }
  };

  const handleExport = async (format) => {
    try {
      setIsExporting(true);
      await exportReferralData(postId, format);
      alert(`Data exported successfully as ${format.toUpperCase()}`);
    } catch (error) {
      console.error('Error exporting:', error);
      alert('Failed to export data');
    } finally {
      setIsExporting(false);
    }
  };

  if (isLoading || !analytics) {
    return (
      <div className="flex justify-center items-center py-12">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  // Prepare chart data
  const platformData = analytics.platformBreakdown.map(p => ({
    name: (p._id || 'Unknown').charAt(0).toUpperCase() + (p._id || 'Unknown').slice(1),
    value: p.count,
    percentage: ((p.count / analytics.totalClicks) * 100).toFixed(1)
  }));

  const deviceData = analytics.deviceBreakdown.map(d => ({
    name: (d._id || 'Unknown').charAt(0).toUpperCase() + (d._id || 'Unknown').slice(1),
    value: d.count,
    percentage: ((d.count / analytics.totalClicks) * 100).toFixed(1)
  }));

  const browserData = analytics.browserBreakdown.slice(0, 6).map(b => ({
    name: b._id || 'Unknown',
    value: b.count
  }));

  const timelineData = analytics.timelineData.map(t => ({
    time: t._id.split(' ')[1] || t._id,
    clicks: t.count
  }));

  const geographicData = analytics.geographicBreakdown.slice(0, 10).map((g, i) => ({
    name: `${g._id.city || 'Unknown'}, ${g._id.country || ''}`,
    value: g.count,
    rank: i + 1
  }));

  const depthData = analytics.depthDistribution.map(d => ({
    depth: `L${d._id}`,
    count: d.count,
    name: `Level ${d._id}`
  }));

  // Calculate summary stats
  const avgClicksPerHour = analytics.timelineData.length > 0
    ? (analytics.totalClicks / analytics.timelineData.length).toFixed(1)
    : 0;

  const maxDepth = analytics.depthDistribution.length > 0
    ? Math.max(...analytics.depthDistribution.map(d => d._id))
    : 0;

  const topPlatform = platformData.length > 0 ? platformData[0].name : 'N/A';
  const topDevice = deviceData.length > 0 ? deviceData[0].name : 'N/A';

  return (
    <div className="space-y-6">
      {/* Header with Real-Time Indicator */}
      <div className="bg-gradient-to-r from-indigo-600 to-purple-600 rounded-lg p-6 text-white">
        <div className="flex items-center justify-between">
          <div>
            <div className="flex items-center gap-3 mb-2">
              <h2 className="text-2xl font-bold">Analytics Dashboard</h2>
              <div className="flex items-center gap-2 bg-white/20 rounded-full px-3 py-1">
                <div className="w-2 h-2 bg-green-400 rounded-full animate-pulse"></div>
                <span className="text-xs">Live</span>
              </div>
            </div>
            <p className="text-indigo-100 text-sm">
              Last updated: {lastUpdate.toLocaleTimeString()}
            </p>
          </div>

          {/* Export Buttons */}
          <div className="flex gap-2">
            <button
              onClick={() => handleExport('json')}
              disabled={isExporting}
              className="px-4 py-2 bg-white text-indigo-600 rounded-lg font-medium hover:bg-indigo-50 transition-colors disabled:opacity-50 text-sm"
            >
              📥 JSON
            </button>
            <button
              onClick={() => handleExport('csv')}
              disabled={isExporting}
              className="px-4 py-2 bg-white text-indigo-600 rounded-lg font-medium hover:bg-indigo-50 transition-colors disabled:opacity-50 text-sm"
            >
              📥 CSV
            </button>
          </div>
        </div>
      </div>

      {/* Time Range Selector */}
      <div className="bg-white rounded-lg shadow-sm p-4">
        <div className="flex items-center gap-4">
          <span className="text-sm font-medium text-gray-700">Time Range:</span>
          <div className="flex gap-2">
            {['hour', 'day', 'week', 'month'].map((range) => (
              <button
                key={range}
                onClick={() => setTimeRange(range)}
                className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                  timeRange === range
                    ? 'bg-indigo-600 text-white'
                    : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                }`}
              >
                {range.charAt(0).toUpperCase() + range.slice(1)}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Key Metrics Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white rounded-lg shadow-sm p-6">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 mb-1">Total Clicks</p>
              <p className="text-3xl font-bold text-gray-900">{analytics.totalClicks}</p>
              <p className="text-xs text-gray-500 mt-1">{avgClicksPerHour}/hour avg</p>
            </div>
            <div className="w-12 h-12 bg-blue-100 rounded-full flex items-center justify-center">
              <span className="text-2xl">👆</span>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-lg shadow-sm p-6">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 mb-1">Top Platform</p>
              <p className="text-2xl font-bold text-gray-900">{topPlatform}</p>
              <p className="text-xs text-gray-500 mt-1">{platformData[0]?.percentage}% of traffic</p>
            </div>
            <div className="w-12 h-12 bg-green-100 rounded-full flex items-center justify-center">
              <span className="text-2xl">📱</span>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-lg shadow-sm p-6">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 mb-1">Top Device</p>
              <p className="text-2xl font-bold text-gray-900">{topDevice}</p>
              <p className="text-xs text-gray-500 mt-1">{deviceData[0]?.percentage}% of users</p>
            </div>
            <div className="w-12 h-12 bg-orange-100 rounded-full flex items-center justify-center">
              <span className="text-2xl">💻</span>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-lg shadow-sm p-6">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 mb-1">Max Depth</p>
              <p className="text-3xl font-bold text-gray-900">{maxDepth}</p>
              <p className="text-xs text-gray-500 mt-1">referral levels</p>
            </div>
            <div className="w-12 h-12 bg-purple-100 rounded-full flex items-center justify-center">
              <span className="text-2xl">📊</span>
            </div>
          </div>
        </div>
      </div>

      {/* Charts Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Platform Distribution */}
        <div className="bg-white rounded-lg shadow-sm p-6">
          <h3 className="text-lg font-bold text-gray-900 mb-4">Platform Distribution</h3>
          <ResponsiveContainer width="100%" height={300}>
            <PieChart>
              <Pie
                data={platformData}
                dataKey="value"
                nameKey="name"
                cx="50%"
                cy="50%"
                outerRadius={100}
                label={(entry) => `${entry.name} (${entry.percentage}%)`}
              >
                {platformData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
          <div className="mt-4 grid grid-cols-2 gap-2">
            {platformData.map((item, index) => (
              <div key={index} className="flex items-center gap-2 text-sm">
                <div
                  className="w-3 h-3 rounded-full"
                  style={{ backgroundColor: COLORS[index % COLORS.length] }}
                ></div>
                <span>{item.name}: {item.value}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Device Distribution */}
        <div className="bg-white rounded-lg shadow-sm p-6">
          <h3 className="text-lg font-bold text-gray-900 mb-4">Device Distribution</h3>
          <ResponsiveContainer width="100%" height={300}>
            <PieChart>
              <Pie
                data={deviceData}
                dataKey="value"
                nameKey="name"
                cx="50%"
                cy="50%"
                outerRadius={100}
                label={(entry) => `${entry.name} (${entry.percentage}%)`}
              >
                {deviceData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
          <div className="mt-4 grid grid-cols-2 gap-2">
            {deviceData.map((item, index) => (
              <div key={index} className="flex items-center gap-2 text-sm">
                <div
                  className="w-3 h-3 rounded-full"
                  style={{ backgroundColor: COLORS[index % COLORS.length] }}
                ></div>
                <span>{item.name}: {item.value}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Browser Breakdown */}
        <div className="bg-white rounded-lg shadow-sm p-6">
          <h3 className="text-lg font-bold text-gray-900 mb-4">Top Browsers</h3>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={browserData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="name" />
              <YAxis />
              <Tooltip />
              <Legend />
              <Bar dataKey="value" fill="#3B82F6" name="Clicks" />
            </BarChart>
          </ResponsiveContainer>
        </div>

        {/* Chain Depth Distribution */}
        <div className="bg-white rounded-lg shadow-sm p-6">
          <h3 className="text-lg font-bold text-gray-900 mb-4">Chain Depth Distribution</h3>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={depthData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="depth" />
              <YAxis />
              <Tooltip />
              <Legend />
              <Bar dataKey="count" fill="#8B5CF6" name="Nodes" />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Timeline Chart */}
      <div className="bg-white rounded-lg shadow-sm p-6">
        <h3 className="text-lg font-bold text-gray-900 mb-4">Clicks Over Time</h3>
        <ResponsiveContainer width="100%" height={300}>
          <AreaChart data={timelineData}>
            <defs>
              <linearGradient id="colorClicks" x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor="#3B82F6" stopOpacity={0.8}/>
                <stop offset="95%" stopColor="#3B82F6" stopOpacity={0}/>
              </linearGradient>
            </defs>
            <CartesianGrid strokeDasharray="3 3" />
            <XAxis dataKey="time" />
            <YAxis />
            <Tooltip />
            <Legend />
            <Area
              type="monotone"
              dataKey="clicks"
              stroke="#3B82F6"
              fillOpacity={1}
              fill="url(#colorClicks)"
              name="Clicks"
            />
          </AreaChart>
        </ResponsiveContainer>
      </div>

      {/* Top Referrers */}
      <div className="bg-white rounded-lg shadow-sm p-6">
        <h3 className="text-lg font-bold text-gray-900 mb-4">🏆 Top Referrers</h3>
        <div className="space-y-3">
          {topReferrers.map((referrer, index) => (
            <div
              key={referrer.userId}
              className="flex items-center justify-between p-4 bg-gradient-to-r from-gray-50 to-white rounded-lg hover:shadow-md transition-shadow"
            >
              <div className="flex items-center gap-4">
                <div
                  className={`flex items-center justify-center w-10 h-10 rounded-full font-bold text-white ${
                    index === 0
                      ? 'bg-yellow-500'
                      : index === 1
                      ? 'bg-gray-400'
                      : index === 2
                      ? 'bg-orange-600'
                      : 'bg-indigo-600'
                  }`}
                >
                  #{index + 1}
                </div>
                {referrer.avatar ? (
                  <img
                    src={referrer.avatar}
                    alt={referrer.username}
                    className="w-12 h-12 rounded-full"
                  />
                ) : (
                  <div className="w-12 h-12 rounded-full bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center text-white font-bold text-lg">
                    {referrer.username?.[0]?.toUpperCase()}
                  </div>
                )}
                <div>
                  <p className="font-semibold text-gray-900">
                    {referrer.firstName || referrer.username}
                  </p>
                  <p className="text-sm text-gray-500">@{referrer.username}</p>
                </div>
              </div>
              <div className="text-right">
                <p className="text-2xl font-bold text-indigo-600">{referrer.count}</p>
                <p className="text-xs text-gray-500">referrals</p>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Geographic Distribution */}
      <div className="bg-white rounded-lg shadow-sm p-6">
        <h3 className="text-lg font-bold text-gray-900 mb-4">🌍 Geographic Distribution</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {geographicData.map((location, index) => (
            <div
              key={index}
              className="flex items-center justify-between p-4 border border-gray-200 rounded-lg hover:border-indigo-400 transition-colors"
            >
              <div className="flex items-center gap-3">
                <span className="text-sm font-semibold text-gray-400">#{location.rank}</span>
                <span className="text-xl">📍</span>
                <span className="font-medium text-gray-900">{location.name}</span>
              </div>
              <div className="flex items-center gap-2">
                <div className="w-24 bg-gray-200 rounded-full h-2">
                  <div
                    className="bg-indigo-600 h-2 rounded-full"
                    style={{
                      width: `${(location.value / geographicData[0].value) * 100}%`
                    }}
                  ></div>
                </div>
                <span className="text-lg font-bold text-indigo-600 min-w-[3rem] text-right">
                  {location.value}
                </span>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default ReferralAnalyticsDashboard;

